(window.GIM_TS=window.GIM_TS||{})["Shevuot.2"]={"from":48,"a":[["\u0003חדא מינייהו\u0004 \u0005[אחת מן\u0006 האמרות \u0005הללו]\u0006 לא אביי, אלא תלמידו \u0003רב פפא\u0004 הוא ש\u0003אמרה.\u0004","שנינו במשנה ש\u0003ר' ישמעאל אומר: אינו חייב אלא על העתיד לבא.\u0004 ובענין זה מביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר בשבועת ביטוי \"נפש כי תשבע לבטא בשפתים \u0003להרע או להיטיב\"\u0004 (ויקרא ה, ד), \u0003אין לי\u0004 שחייב \u0003אלא\u0004 על \u0003דברים שיש בהן הרעה והטבה,\u0004 על דברים \u0003שאין בהן הרעה והטבה, מנין\u0004 שגם עליהם מתחייב? \u0003תלמוד לומר\u0004 מתחילה: \u0003\"או נפש כי תשבע לבטא בשפתים\"\u0004 (ויקרא ה, ד), לרבות גם דברים אחרים.","\u0003אין לי אלא\u0004 שנשבע \u0003להבא\u0004 (לעתיד לבוא), שנשבע \u0003לשעבר מנין? תלמוד לומר: \"לכל אשר יבטא האדם בשבעה\"\u0004 (ויקרא ה, ד), אלו \u0003דברי ר' עקיבא. ר' ישמעאל אומר:\u0004 נאמר \u0003\"להרע או להיטיב\"\u0004 — הרי זה דווקא \u0003להבא,\u0004 כמשמעותו.","\u0003אמר לו ר' עקיבא: אם כן,\u0004 אם אתה מדייק כלשון הכתוב הזה, \u0003אין לי אלא דברים שיש בהן הטבה והרעה, דברים שאין בהן הרעה והטבה מנין? אמר לו: מרבוי הכתוב\u0004 כמו שראינו. \u0003אמר לו: אם ריבה הכתוב לכך\u0004 לדברים שאינם הרעה והטבה, \u0003ריבה הכתוב לכך\u0004 גם לדברים שהם לשעבר.","ושואלים: \u0003שפיר קא אמר ליה\u0004 \u0005[יפה אמר לו]\u0006 \u0003ר' עקיבא לר' ישמעאל,\u0004 וכיצד יתרץ ר' ישמעאל קושי זה?","\u0003אמר ר' יוחנן: ר' ישמעאל ששימש\u0004 כתלמיד \u0003את ר' נחוניא בן הקנה, שהיה דורש את כל התורה כולה ב\u0004שיטת הלימוד של \u0003כלל ופרט, איהו נמי\u0004 \u0005[הוא גם כן]\u0006 \u0003דורש ב\u0004שיטת \u0003כלל ופרט,\u0004 ואילו \u0003ר' עקיבא ששימש את נחום איש גם זו, שהיה דורש את כל התורה כולה ב\u0004שיטת \u0003ריבה ומיעט, איהו נמי\u0004 \u0005[הוא גם כן]\u0006 \u0003דורש ריבה ומיעט.\u0004","\u0003מאי\u0004 \u0005[מהו]\u0006 כיצד מצאנו את \u0003ר' עקיבא דדריש ריבויי ומיעוטי\u0004 \u0005[ש\u0006הוא \u0005דורש ריבויים ומיעוטים]\u0006 במקרא זה? \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003\"או נפש כי תשבע\"\u0004 (ויקרא ה, ד) — הרי זה \u0003ריבה\u0004 כל מיני שבועות, \u0003\"להרע או להיטיב\"\u0004 (ויקרא ה, ד) — \u0003מיעט, \"לכל אשר יבטא האדם\"\u0004 (ויקרא ה, ד) — \u0003חזר וריבה,\u0004 הרי \u0003ריבה ומיעט וריבה,\u0004 ולפי שיטה זו \u0003ריבה הכל,\u0004","\u0003מאי\u0004 \u0005[מה]\u0006 \u0003ריבה? ריבה\u0004 את \u0003כל מילי\u0004 \u0005[הדברים]\u0006 שנשבעים עליהם, \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003מיעט\u0004 בכל זאת, כיון שמיעט הכתוב \"להרע או להיטיב\"? \u0003מיעט דבר מצוה,\u0004 שאין שבועה חלה עליו לקיימו או לבטלו.","\u0003ו\u0004אילו \u0003ר' ישמעאל דריש\u0004 \u0005[דורש]\u0006 אותו מקרא ב\u0003כלל ופרט,\u0004 ובאופן זה: \u0003\"או נפש כי תשבע לבטא בשפתים\"\u0004 — הרי זה \u0003כלל, \"להרע או להיטיב\"\u0004 — הרי זה \u0003פרט, \"לכל אשר יבטא האדם\"\u0004 — \u0003חזר וכלל,\u0004 הרי זה \u0003כלל ופרט וכלל,\u0004 ולפי דרך זו \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט: מה הפרט מפורש\u0004 הוא \u0003להבא. אף כל להבא.\u0004","\u0003אהני כללא לאתויי\u0004 \u0005[הועיל הכלל להביא,\u0006 להוסיף\u0005]\u0006 \u0003אפילו דברים שאין בהן הרעה והטבה\u0004 שנשבע עליהם \u0003להבא, אהני פרטא למעוטי\u0004 \u0005[הואיל הפרט למעט]\u0006 \u0003אפילו דברים שיש בהן הרעה והטבה\u0004 אם נשבע עליהם \u0003לשעבר.\u0004","ושואלים: \u0003איפוך אנא\u0004 \u0005[אהפוך אני]\u0006 ואומר שהכלל בא לרבות לשעבר, והפרט בא למעט דברים שאין בהם הרעה והטבה, כמו ששאל ר' עקיבא!","\u0003אמר ר' יצחק:\u0004 יש להכניס בכלל את מה שהוא \u0003דומיא\u0004 \u0005[בדומה]\u0006 \u0003להרע או להיטיב,\u0004 והוא \u0003מי שאיסורו\u0004 (שהאיסור שיש בכך) הוא \u0003משום \"בל יחל דברו\"\u0004 (במדבר ל, ג), שמחלל ומפר את השבועה שנשבע, \u0003יצאתה\u0004 (יצאה) \u0003זו\u0004 שבועה על מה שהיה בעבר \u0003שאין איסורו משום \"בל יחל דברו\",\u0004 שהרי אינו מחלל שבועה, \u0003אלא\u0004 שהוא עובר \u0003משום \"בל תשקרו\"\u0004 (ראה ויקרא יט, יא).","\u0003רב יצחק בר אבין אמר\u0004 הסבר אחר לדבר, \u0003אמר קרא\u0004 \u0005[המקרא]:\u0006 \u0003\"או נפש כי תשבע לבטא בשפתים\"\u0004 (ויקרא ה, ד), \u0003מי שהשבועה קודמת ל\u0004מעשה ה\u0003ביטוי, ולא שהביטוי קודמת לשבועה, יצא זה\u0004 שנשבע \u0003\"אכלתי\" ו\"לא אכלתי\"\u0004 — \u0003שהמעשה קודם לשבועה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר שם \"לכל אשר יבטא האדם בשבועה ונעלם ממנו\" (ויקרא ה, ד), ומן המלים \"\u0003האדם בשבועה\u0004\" יש ללמוד שהאדם הנשבע מתחייב בקרבן דווקא אם היה בשלימות דעתו ורצונו — \u0003פרט לאנוס,\u0004 שאינו עובר על השבועה מרצונו אלא מחמת אונס כלשהו. ומה שנאמר \u0003\"ונעלם\"\u0004 — \u0003פרט ל\u0004מי שעושה זאת ב\u0003מזיד\u0004 שאינו מתכפר בקרבן.","\u0003\"ממנו\"\u0004 — הכוונה היא \u0003שנתעלמה\u0004 (נשכחה) \u0003ממנו שבועה,\u0004 שעבר על שבועתו לפי ששכח שנשבע. \u0003יכול\u0004 שמדובר גם במי \u0003שנתעלמה ממנו חפץ,\u0004 שעבר על שבועתו משום שטעה וחשב שהוא דבר אחר שלא נשבע עליו? \u0003תלמוד לומר: \"בשבועה ונעלם\", על העלם שבועה הוא חייב, ואינו חייב על העלם חפץ.\u0004","את הברייתא הזו מבארים לפרטיה: \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003\"האדם בשבועה\"\u0004 — \u0003פרט לאנוס.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד\u0006 בדיוק \u0005הוא]\u0006 אנוס? כלומר, מה הוא הנחשב אונס לענין שבועה?","ואומרים: \u0003כ\u0004דרך ש\u0003רב כהנא ורב אסי כי הוו קיימי מקמי\u0004 \u0005[כאשר היו קמים\u0006 לאחר לימודם \u0005מלפני]\u0006 \u0003רב,\u0004 והיו מדברים ביניהם על מה שלמדו, והתווכחו מה בדיוק אמר רב, \u0003מר אמר\u0004 \u0005[חכם זה היה אומר]:\u0006 \u0003שבועתא דהכי\u0004 \u0005[שבועה שכך]\u0006 \u0003אמר רב, ומר אמר\u0004 \u0005[וחכם זה היה אומר]:\u0006 \u0003שבועתא דהכי\u0004 \u0005[שבועה שכך]\u0006 \u0003אמר רב. כי אתו לקמיה\u0004 \u0005[כאשר היו באים לפני]\u0006 \u0003רב, אמר כחד מינייהו\u0004 \u0005[היה אומר כ\u0006דברי \u0005אחד מהם].\u0006 \u0003אמר ליה אידך\u0004 \u0005[לו האחר]\u0006 לרב: \u0003ואנא בשיקרא אישתבעי\u0004 \u0005[ואני בשקר נשבעתי]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רב: אין זה נקרא שקר, כי \u0003לבך אנסך,\u0004 כי בשעת שבועה היית בטוח שאתה אומר אמת, ואין זה בכלל שבועת שקר.","ועוד שנינו בברייתא: \u0003\"ונעלם ממנו\"\u0004 — \u0003שנתעלם ממנו שבועה, יכול שנתעלם ממנו חפץ? תלמוד לומר: \"בשבועה ונעלם ממנו\", על העלם שבועה הוא חייב, ואינו חייב על העלם חפץ.\u0004","\u0003מחכו עליה במערבא\u0004 \u0005[היו צוחקים על כך בארץ ישראל]:\u0006 \u0003בשלמא\u0004 \u0005[נניח]\u0006 העלם \u0003שבועה משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 \u0003בלא\u0004 העלם \u0003חפץ,\u0004 כיצד? \u0003כגון\u0004 ש\u0003אמר: \"שבועה שלא אוכל פת חטין\",\u0004 \u0003וכסבור \"שאוכל\u0004 פת חטין\" \u0003קאמר\u0004 \u0005[אמר]\u0006 בשבועתו, \u0003דשבועתיה אינשי\u0004 \u0005[ששבועתו נשכחה]\u0006 כלומר, שכח מה בדיוק נשבע, אבל \u0003חפצא דכיר\u0004 \u0005[\u0006את ה\u0005חפץ זכור]\u0006 שנשבע על פת חיטין. \u0003אלא\u0004 העלם \u0003חפץ בלא\u0004 העלם \u0003שבועה היכי דמי\u0004 \u0005[כיצד יכול להיות]?\u0006","אם נאמר \u0003כגון\u0004 ש\u0003אמר \"שבועה שלא אוכל פת חטין\" וכסבור \"של שעורים\" קאמר\u0004 \u0005[אמר],\u0006 \u0003דשבועתיה דכיר ליה\u0004 \u0005[ששבועתו זכורה לו],\u0006 \u0003חפצא אינשי\u0004 \u0005[והחפץ נשכח],\u0006 והרי \u0003כיון דחפצא אינשי ליה\u0004 \u0005[שהחפץ שכוח לו]\u0006 \u0003היינו\u0004 \u0005[הרי זו]\u0006 \u0003העלם שבועה,\u0004 שהרי מה ששכח היה מפרטי השבועה!","\u0003אלא אמר ר' אלעזר: דא ודא\u0004 \u0005[זו וזו]\u0006 \u0003אחת היא.\u0004","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף: אלמא\u0004 \u0005[מכאן\u0006 אתה מסיק\u0005]\u0006 ש\u0003חפץ בלא שבועה לא משכחת לה\u0004 \u0005[אין אתה מוצא]?\u0006 \u0003והא משכחת לה\u0004 \u0005[והרי אתה\u0006 יכול \u0005למצוא אותה],\u0006 \u0003כגון\u0004 ש\u0003אמר \"שבועה שלא אוכל פת חטין\", והושיט ידו לסל ליטול פת שעורין, ועלתה בידו\u0004 פת \u0003של חטין, וכסבור\u0004 שפת \u0003שעורים היא ואכלה, דשבועתיה דכיר ליה\u0004 \u0005[ששבועתו זכורה לו],\u0006 \u0003חפצא הוא דלא ידע ליה\u0004 \u0005[והחפץ הוא שאינו ידוע לו]!\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: כלום מחייבת ליה\u0004 \u0005[\u0006אין \u0005אתה מחייב אותו]\u0006 \u0003קרבן\u0004 שעבר על שבועתו \u0003אלא אמאי דתפיס בידיה\u0004 \u0005[על מה ש\u0006הוא \u0005תופס בידו\u0006 ואוכל\u0005],\u0006 והרי \u0003העלם שבועה הוא,\u0004 שהוא סבור שלא נשבע על כך!","\u0003לישנא אחרינא\u0004 \u0005[לשון אחרת],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: סוף סוף קרבן דקא מייתי עלה דהאי פת מיהת\u0004 \u0005[שהוא מביא על הפת הזו מכל מקום]\u0006 על \u0003העלם שבועה הוא\u0004 ששכח שנשבע על פת זו, ואין הדבר תלוי בהעלם החפץ!","\u0003ורב יוסף אמר לך\u0004 \u0005[היה אומר לך]\u0006 בתשובה לכך: \u0003כיון דכי ידע ליה\u0004 \u0005[שאם היה יודע]\u0006 שפת של \u0003חטין הוא פריש מיניה\u0004 \u0005[היה פורש ממנה],\u0006 הרי שאת השבועה עדיין הוא זוכר, ולא נעלמה ממנו, אלא ש\u0003העלם חפץ הוא.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן: העלם זה וזה בידו\u0004 (ששכח גם את השבועה וגם את החפץ), \u0003מהו? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הרי העלם שבועה בידו, וחייב.\u0004 אמר לו: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 אני יכול לומר \u0003הרי העלם חפץ בידו, ופטור!\u0004","\u0003אמר רב אשי: חזינן\u0004 \u0005[רואים אנו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003מחמת שבועה קא פריש\u0004 \u0005[הוא פורש]\u0006 מן הדבר, כאשר אומרים לו: הרי נשבעת — \u0003הרי\u0004 נמצא ש\u0003העלם שבועה בידו, וחייב. אי\u0004 \u0005[אם]\u0006 \u0003מחמת חפץ קא פריש\u0004 \u0005[הוא פורש]\u0006 כשמזכירים לו שמה שנמצא בידו הוא חפץ מסויים — \u0003הרי העלם חפץ בידו, ופטור.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 באופן זה אין להוכיח כלל איזה העלם בידו, כי בהכרח הוא חייב להיזכר הכל, \u0003כלום פריש\u0004 \u0005[\u0006אין הוא \u0005פורש]\u0006 \u0003משבועה אלא משום חפץ\u0004 שנזכר שנשבע עליו, וכן \u0003כלום\u0004 לא \u0003פריש\u0004 \u0005[פורש]\u0006 הוא \u0003מחפץ אלא משום שבועה!\u0004 כשאומרים לו שהוא חפץ מסוים ופורש ממנו, הלוא עושה זאת רק משום שנזכר שנשבע שלא לאכול ממנו! \u0003אלא לא שנא\u0004 \u0005[אין שונה]\u0006 אין הבדל בין זה לזה.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004"],["\u0003איזו היא\u0004 כלומר, באיזה אופן מתקיימת \u0003שגגת שבועת ביטוי לשעבר\u0004 ששנינו שחייב עליה קרבן? שכן \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003דידע\u0004 \u0005[ש\u0006הוא \u0005יודע]\u0006 כשהוא נשבע שלא כך הדבר — אם כן \u0003מזיד הוא\u0004 ולא שוגג, \u0003אי\u0004 \u0005[אם]\u0006 מדובר \u0003דלא ידע\u0004 \u0005[שאינו יודע]\u0006 והוא סבור שבאמת הרי זה כמו שנשבע, הרי כפי שאמרנו לעיל \u0003אנוס הוא!\u0004","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003באומר: יודע אני ששבועה זו אסורה, אבל איני יודע אם חייבין עליה קרבן או לאו\u0004 \u0005[לא]\u0006 וחוסר ידיעתו בענין חיוב הקרבן הוא העושה אותו שוגג.","שאל אותו: \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003כ\u0004שיטת \u0003מונבז,\u0004 ש\u0003אמר: שגגת קרבן שמה שגגה?\u0004 שהוא סבור שאם עבר אדם עבירה (כגון חילול שבת) ואינו יודע שיש בדבר זה חיוב קרבן הרי זה נחשב כשגגה. אבל חכמים חולקים על כך והם סבורים שאי ידיעה כזאת אינה פוטרת מקרבן.","ודחה רב נחמן: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים על מונבז, \u0003עד כאן לא פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 על \u0003מונבז,\u0004 וסבורים ששגגה כזאת אינה נחשבת שגגה לחייבו קרבן, \u0003אלא בכל התורה כולה,\u0004 במקרים \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003חידוש הוא,\u0004 שכל עבירה שחייב על זדונה כרת חייב על שגגתה קרבן חטאת. \u0003אבל הכא\u0004 \u0005[כאן],\u0006 לענין שבועה, ש\u0003חידוש הוא,\u0004 שהרי \u0003בכל התורה כולה לא אשכחן\u0004 \u0005[מצאנו]\u0006 עוד איסור \u0003לאו\u0004 בלבד (שיש בו חיוב מלקות במזיד) \u0003דמייתי\u0004 \u0005[שמביא\u0006 עליו\u0005]\u0006 \u0003קרבן,\u0004 משום","\u0003דילפינן\u0004 \u0005[שאנו לומדים]\u0006 \u0003מעבודה זרה\u0004 שרק על דבר שיש חיוב כרת על זדונו מביאים חטאת, \u0003והכא מייתי\u0004 \u0005[ו\u0006אילו \u0005כאן,\u0006 בשבועה הוא \u0005מביא]\u0006 קרבן, בזה \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שגם על שגגת הקרבן מביא קרבן.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבינא מרבא: נשבע על ככר\u0004 שלא יאכלנה \u0003ומסתכן\u0004 היה בנפשו \u0003עליה\u0004 אם לא היה אוכלנה, \u0003מהו\u0004 דינו לענין הבאת קרבן על אכילתה?","תהה רבא על שאלתו: אם \u0003מסתכן\u0004 הוא, \u0003לישרי ליה מר\u0004 \u0005[שיתיר לו אדוני]\u0006 מלכתחילה, שהרי פיקוח נפש דוחה גם איסור שבועה, ואין כאן עבירה באכילת הככר אלא אונס גמור! \u0003אלא\u0004 יש לשאול: לא במסתכן, אלא ב\u0003מצטער\u0004 שסובל מרעב, שהיה אוכל כיכר זו בכל מקרה \u0003ואכלה בשגגת שבועה,\u0004 במקרה כזה \u0003מאי\u0004 \u0005[מה]\u0006 דינו?","\u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003תנינא\u0004 \u0005[שנינו]\u0006 תשובה לשאלה זו: דווקא אם \u0003שב מידיעתו\u0004 כלומר, דווקא מי שחוסר ידיעתו גרם לו לחטוא, ומפני שנודע לו החטא חוזר בתשובה — \u0003מביא קרבן על שגגתו,\u0004 אבל אם \u0003לא שב מידיעתו\u0004 אלא גם אם היה יודע היה חוטא — \u0003אין מביא קרבן על שגגתו.\u0004","\u0003אמר שמואל:\u0004 אף ש\u0003גמר\u0004 אדם \u0003בלבו\u0004 להישבע על דבר, \u0003צריך\u0004 בכל זאת \u0003שיוציא\u0004 את השבועה \u0003בשפתיו\u0004 כדי שיתחייב על כך, \u0003שנאמר: \"לבטא בשפתים\"\u0004 (ויקרא ה, ד).","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: נאמר \u0003\"בשפתים\"\u0004 ומשמעו — \u0003ולא בלב.\u0004 אם \u0003גמר בלבו\u0004 ולא ביטא בשפתיים, \u0003מנין\u0004 שחייב? \u0003תלמוד לומר: \"לכל אשר יבטא האדם בשבועה\"\u0004 (ויקרא ה, ד).","ולפני שבאים לביאור הקושיה מבררים את לשון הברייתא, ותמהים: \u0003הא גופה קשיא\u0004 \u0005[היא עצמה קשה],\u0006 \u0003אמרת\u0004 בתחילה: \u0003\"בשפתים\"\u0004 — \u0003ולא בלב,\u0004 שהריהו פטור על מחשבת הלב, \u0003והדר\u0004 \u0005[וחזרת]\u0006 ו\u0003אמרת\u0004 הוכחה להלכה הפוכה: \u0003גמר בלבו, מנין\u0004 שחייב על מחשבת הלב!","\u0003אמר רב ששת: הא לא קשיא\u0004 \u0005[זה אינו קשה],\u0006 \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך יש לישב את לשון הברייתא: \u0003\"בשפתים\"\u0004 ולא בלב, כוונתו: \u0003ולא שגמר בלבו להוציא\u0004 שבועה זו \u0003בשפתיו ולא הוציא\u0004 בפועל, שכיון שנתכוון לבטא את השבועה בפיו ולא ביטאה — פטור. אבל אם \u0003גמר בלבו סתם\u0004 ומתחילה לא התכוון להוציא בשפתיו, \u0003מנין\u0004 שהוא חייב על פי כוונתו? \u0003תלמוד לומר: \"לכל אשר יבטא\".\u0004","ושואלים: \u0003אלא לשמואל קשיא\u0004 \u0005[קשה]\u0006 ברייתא זו, שהרי עולה ממנה שגם בלי לבטא בשפתיים הוא חייב!","\u0003אמר רב ששת, תריץ ואימא הכי\u0004 \u0005[ישב\u0006 את הברייתא בדרך אחרת \u0005ואמור כך]:\u0006 \u0003\"בשפתים\"\u0004 — \u0003ולא שגמר בלבו להוציא\u0004 מפיו את המלים \u0003\"פת חטין\", והוציא\u0004 מפיו בטעות את המלים \u0003\"פת שעורין\".\u0004 אבל אם \u0003גמר בלבו להוציא\u0004 ולומר שהוא אוסר על עצמו \u0003\"פת חטין\", והוציא\u0004 מפיו \u0003\"פת\" סתם\u0004 (ולא פירש \"פת חיטין\"), \u0003מנין\u0004 שהוא חייב על פת חיטין? \u0003תלמוד לומר: \"לכל אשר יבטא האדם\".\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על שמואל ממה ששנינו בברייתא: נאמר \u0003\"מוצא שפתיך תשמר ועשית\"\u0004 (דברים כג, כד), \u0003אין לי אלא שהוציא בשפתיו,\u0004 שרק אז חייב לקיים את נדרו, \u0003גמר בלבו\u0004 בלבד \u0003מנין\u0004 שהוא גם כן חייב על כך? \u0003תלמוד לומר: \"כל נדיב לב\"\u0004 (שמות לה, כב), משמע שמתחייב על ידי החלטת הלב בלבד!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם],\u0006 בנדבת קודש, \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 במפורש \u0003\"כל נדיב לב\".\u0004","ושואלים: \u0003וניגמר מינה\u0004 \u0005[ונלמד מכאן]\u0006 שבכל דבר די בהחלטה שבלב!","ומשיבים: \u0003משום דהוו\u0004 \u0005[שהריהם]\u0006 \u0003תרומה וקדשים,\u0004 שבשניהם יש תוקף הלכתי להחלטה בלב, \u0003שני כתובין הבאין כאחד,\u0004 שמלמדים במפורש דין מסויים, \u0003וכל שני כתובין הבאין כאחד אין מלמדין\u0004 על השאר.","ומקשים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר]\u0006 ששני כתובים הבאים כאחד \u0003אין מלמדין, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שהם \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 מדוע אין למדים מהם?","ומשיבים: כי \u0003הוו\u0004 \u0005[הרי זה]\u0006 \u0003חולין וקדשים, וחולין מקדשים לא גמרינן\u0004 \u0005[אין אנו לומדים],\u0006 שיש בדיני קדשים צדדים חמורים הרבה."],["\u0003נשבע לבטל את המצוה, ולא ביטל\u0004 — \u0003פטור\u0004 מקרבן על שבועת ביטוי. וכן הנשבע \u0003לקיים\u0004 מצווה, \u0003ולא קיים\u0004 — \u0003פטור. שהיה בדין שיהא חייב, כדברי ר' יהודה בן בתירא.\u0004","שכך \u0003אמר ר' יהודה בן בתירא: מה אם\u0004 דבר של \u0003הרשות\u0004 (שאינו מצוה) \u0003שאינו מושבע עליו\u0004 לעשותו \u0003מהר סיני\u0004 — \u0003הרי הוא חייב עליו\u0004 אם עבר על שבועתו, דבר של \u0003מצוה שהוא\u0004 כבר \u0003מושבע עליה מהר סיני\u0004 — \u0003אינו דין שיהא חייב עליה?\u0004","\u0003אמרו לו: לא, אם אמרת בשבועת הרשות\u0004 — \u0003שכן עשה בה לאו כהן,\u0004 שיכול להישבע על אותו הדבר גם שלא יעשנו, ומשום כך הוא חייב, \u0003תאמר בשבועת מצוה\u0004 — \u0003שלא עשה בה לאו כהן, שאם נשבע לבטל\u0004 מצוה \u0003ולא ביטל\u0004 — הרי בוודאי \u0003פטור,\u0004 שאינו יכול לבטל מצוה שמן התורה.","ובדין זה ששנינו במשנה בנשבע לבטל את המצוה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003יכול\u0004 ה\u0003נשבע לבטל את המצוה ולא ביטל יהא חייב\u0004 על שבועתו? \u0003תלמוד לומר: \"להרע או להיטיב\"\u0004 (ויקרא ה, ד), \u0003מה הטבה\u0004 שמדובר בה היא בדבר \u0003רשות,\u0004 שנשבע לעשות דבר שאינו אסור בו או מצווה עליו, \u0003אף הרעה\u0004 שנשבע שלא לעשות, הריהי בדבר ה\u0003רשות,\u0004 ולכן \u0003אוציא\u0004 מכלל זה מי ש\u0003נשבע לבטל את המצוה ולא ביטל שהוא פטור,\u0004 שהרי אינו רשאי לבטל את המצוה.","\u0003יכול נשבע לקיים את המצוה ולא קיים שיהא חייב? תלמוד לומר: \"להרע או להיטיב\"\u0004 (ויקרא ה, ד), \u0003מה הרעה רשות, אף הטבה רשות,\u0004 ולכן \u0003אוציא נשבע לקיים את המצוה ולא קיים שהוא פטור,\u0004 שהרי אינו רשאי שלא לקיים מצוה.","\u0003יכול נשבע להרע לעצמו ולא הרע, יכול יהא פטור? תלמוד לומר: \"להרע או להיטיב\", מה הטבה רשות, אף הרעה רשות,\u0004 ולכן \u0003אביא\u0004 בכלל שבועת ביטוי \u0003נשבע להרע לעצמו ולא הרע,\u0004 לפי \u0003שהרשות בידו\u0004 להרע לעצמו.","\u0003יכול נשבע להרע לאחרים ולא הרע שיהא חייב? תלמוד לומר: \"להרע או להיטיב\", מה הטבה רשות, אף הרעה רשות,\u0004 ולכן \u0003אוציא נשבע להרע לאחרים ולא הרע\u0004 שפטור משום \u0003שאין הרשות בידו. מנין לרבות הטבת אחרים?\u0004 שאם נשבע להיטיב להם חייב על שבועתו, למרות שאם נשבע להרע לאחרים אין ממש בשבועתו? \u0003תלמוד לומר\u0004 לשון ריבוי: \u0003\"או להיטיב\". ואיזו היא הרעת אחרים?\u0004 כגון שנשבע \u0003\"אכה את פלוני ואפצע את מוחו\".\u0004","על דרך ההוכחה בברייתא זו (\"מה הטבה רשות\" וכו'), שואלים: \u0003וממאי\u0004 \u0005[וממה]\u0006 יודע אתה \u0003דקראי\u0004 \u0005[שהמקראות\u0006 הללו\u0005]\u0006 \u0003בדבר הרשות כתיבי\u0004 \u0005[כתובים]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בדבר מצוה כתיבי\u0004 \u0005[כתובים\u0006 הם\u0005]!\u0006","ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[לא יכול להעלות על דעתך\u0006 לומר כן\u0005],\u0006 משום \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שתהא \u0003הטבה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003הרעה, והרעה דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003הטבה, דאקיש\u0004 \u0005[שהקיש,\u0006 השווה\u0005]\u0006 הכתוב \u0003הרעה להטבה\u0004 (\"להרע או להיטיב\"), ולפי זה היינו צריכים לומר כך: \u0003מה הטבה\u0004 כגון שנשבע לאכול \u0003אינה בביטול מצוה,\u0004 שהרי המבטל מצוה, גם אם הוא מיטיב לגופו באכילה זו הריהו עושה מעשה רע ואין זה בכלל הטבה, \u0003אף הרעה\u0004 שנשבע שלא לאכול \u0003אינה בביטול מצוה,\u0004 אלא כגון שנשבע שלא יאכל חמץ בפסח. ואולם במקרה זה נמצא ש\u0003הרעה גופה הטבה היא,\u0004 שאמנם נשבע להרע לגופו, אבל יש בכך הטבה לנפשו, ואין זו איפוא הרעה ממש.","\u0003ו\u0004כיוצא בזה \u0003אקיש\u0004 \u0005[הקש,\u0006 השווה\u0005]\u0006 \u0003הטבה להרעה, מה הרעה\u0004 כגון שנשבע שלא לאכול \u0003אינה בקיום מצוה\u0004 אלא בביטולה, כגון שנשבע שלא לאכול מצה בליל פסח, \u0003אף הטבה\u0004 שנשבע לאכול \u0003אינה בקיום מצוה\u0004 אלא בביטולה, כגון שנשבע לאכול ביום הכיפורים. ואם כן נמצא שאותה \u0003הטבה גופה הרעה היא,\u0004 שמרע לנפשו בעבירה. ולפיכך אי אפשר לפרש את המקרא בשבועה על דבר מצוה.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך],\u0006 שמשווים הטבה להרעה לכל ענין, \u0003בדבר הרשות נמי לא משכחת לה\u0004 \u0005[גם כן אין אתה מוצא אותה]!\u0006 שאם צריך שתהא ההרעה בדומה להטבה, הרי כשם שהטבה היא בדבר שמועיל לו, כך הרעה צריך לפרשה בדבר המועיל לו, כגון שנשבע שלא לאכול דבר המזיק לו, ואולם נמצא שההרעה בעצם הטבה היא, וכן להיפך.","\u0003אלא\u0004 יש לחזור בנו מדרך הוכחה זו ולהוכיח בדרך אחרת: \u0003מדאיצטריך\u0004 \u0005[מ\u0006כך \u0005שהוצרך]\u0006 המקרא לכתוב \u0003\"או\u0004 להיטיב\" \u0003לרבות הטבת אחרים, שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003בדבר הרשות כתיבי\u0004 \u0005[כתובים]\u0006 מקראות אלה, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך\u0006 לומר\u0005]\u0006 ש\u0003בדבר מצוה כתיבי\u0004 \u0005[כתובים],\u0006 \u0003השתא\u0004 \u0005[עכשיו]\u0006 \u0003הרעת אחרים איתרבי\u0004 \u0005[התרבתה]\u0006 מן הכתוב, שהרי שיכול להישבע לבטל את המצוה ולהרע, \u0003הטבת אחרים מיבעיא\u0004 \u0005[צריכה]\u0006 כתוב מיוחד, שהשבועה חלה?","ועל עצם ההנחה ש\"או\" נצרך להטבת אחרים, מקשים: \u0003ו\u0004הרי \u0003האי \"או\"\u0004 \u0005[\"או\" זה]\u0006 \u0003מיבעי ליה\u0004 \u0005[נצרך לו]\u0006 \u0003לחלק,\u0004 שאם היה כתוב \"להרע ולהיטיב\" היית סבור שאינו חייב עד שישבע על שני הדברים! ודוחים: \u0003לחלק לא צריך קרא\u0004 \u0005[מקרא],\u0006 כי גם ללא המלה \"או\" הייתי מפרש שחייב על כל אחד מהם לחוד.","ומקשים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' יונתן\u0004 בפירוש המקראות, \u0003אלא ל\u0004דעת \u0003ר' יאשיה מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]\u0006 שבה מתבררות שיטות אלו של ר' יונתן ור' יאשיה, נאמר: \"כי \u0003איש אשר יקלל את אביו ואת אמו\u0004 מות יומת\" (ויקרא כ, ט), \u0003אין לי\u0004 לחייב \u0003אלא\u0004 המקלל את \u0003אביו ואמו\u0004 יחד; אבל אם קילל \u0003אביו ולא אמו, אמו ולא אביו, מנין\u0004 שגם כן חייב? \u0003תלמוד לומר\u0004 בהמשך הפסוק: \u0003\"אביו ואמו קלל\u0004 דמיו בו\" (ויקרא כ, ט), ומסמיכות לשון קללה הן לאביו והן לאמו אנו למדים שחייב הן משום ש\u0003אביו קלל,\u0004 והן משום ש\u0003אמו קלל,\u0004 אלו \u0003דברי ר' יאשיה.\u0004","\u0003ר' יונתן אומר:\u0004 בכל מקום שמנויים שני דברים כגון זה בכתוב אחד, \u0003משמע שניהם כאחד, ומשמע\u0004 גם כל \u0003אחד\u0004 מהם \u0003בפני עצמו,\u0004"],["\u0003עד שיפרוט לך הכתוב\u0004 ויאמר במפורש \u0003\"יחדיו\"\u0004 (כגון \"לא תחרוש בשור ובחמור יחדיו\" דברים כב, י), שרק אז חייב על שניהם יחד דווקא!","ודוחים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כדעת \u0003ר' יאשיה,\u0004 שצריך את ה\"או\" כדי לחלק, ולא להטבת אחרים, עדיין יש להוכיח שהכתוב עוסק בדברי הרשות, \u0003ו\u0004כיצד? \u0003סבר לה\u0004 \u0005[סבור]\u0006 הוא \u0003כ\u0004דברי \u0003ר' עקיבא דדריש רבויי ומיעוטי\u0004 \u0005[שדורש\u0006 את המקרא בדרך של \u0005ריבויים ומיעוטים],\u0006 (ראה לעיל שבועות כו,א) \u0003ואייתר ליה\u0004 \u0005[ו\u0006משום כך \u0005נותרה לו]\u0006 המלה \u0003\"או\"\u0004 כדי \u0003לחלק.\u0004","ומעתה, \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003בדבר הרשות כתיב\u0004 \u0005[נאמר\u0006 עוסק\u0005]\u0006 הכתוב, אם כן \u0003ממעט\u0004 הכתוב \u0003דבר מצוה, אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003בדבר מצוה כתיב\u0004 \u0005[נאמר],\u0006 \u0003ממאי קא\u0004 \u0005[ממה]\u0006 \u0003ממעט?\u0004","שנינו במשנה בענין הנשבע לקיים את המצוה מה ש\u0003אמר ר' יהודה בן בתירא\u0004 בהסבר שיטתו: \u0003מה אם הרשות\u0004 אדם חייב אם נשבע עליה, מצוה לא כל שכן? וכן שנינו את תשובתם של חכמים על הסברו זה, שברשות יכול להישבע \"להרע\" או \"להיטיב\", אבל במצוה אין אדם יכול להישבע לבטל מצוה, ואין כאן \"להרע\" או \"להיטיב\". ושואלים: \u0003ורבנן, שפיר קאמרי ליה\u0004 \u0005[וחכמים, יפה הם אומרים לו]\u0006 \u0003לר' יהודה בן בתירא!\u0004","ומשיבים: \u0003ור' יהודה בן בתירא אמר לך\u0004 \u0005[יכול היה לומר לך]:\u0006 \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003הטבת אחרים, לאו אף על גב דליתא\u0004 \u0005[האם לא אף על פי שאינה]\u0006 \u0003בכלל הרעת אחרים ו\u0004בכל זאת \u0003רבי רחמנא\u0004 \u0005[ריבה\u0006 אותו \u0005הכתוב]?\u0006 משמע שאין הכרח שכל שבועה תהיה בה אפשרות להרעה והטבה, ולפיכך \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003ב\u0004שבועה ל\u0003קיום מצוה, אף על גב דליתיה\u0004 \u0005[אף על פי שאינו]\u0006 \u0003בביטול מצוה, רבייה רחמנא\u0004 \u0005[ריבה אותו הכתוב].\u0006","\u0003ורבנן\u0004 \u0005[וחכמים],\u0006 מה הם אומרים על כך? \u0003התם איתיה\u0004 \u0005[שם יש]\u0006 אפשרות לשבועה זו בלאו, שנשבע \u0003ב\"לא איטיב\u0004 לאחרים\", \u0003הכא מי איתיה\u0004 \u0005[כאן האם יש]\u0006 דבר כזה שיישבע \u0003ב\"לא אקיים\u0004 מצוה\"?","אמר: \u0003\"שבועה שלא אוכל ככר זו\",\u0004 וחזר ואמר \u0003\"שבועה שלא אוכלנה\", \"שבועה שלא אוכלנה\", ואכלה\u0004 — \u0003אינו חייב אלא אחת,\u0004 שהרי כבר חלה עליו שבועה ראשונה, ואין שבועה שניה חלה עוד על איסור זה.","\u0003זו היא\u0004 (\"שבועה שלא אוכל\") \u0003שבועת בטוי, שחייבין על זדונה\u0004 (אם עבר עליה בזדון) \u0003מכות, ועל שגגתה\u0004 (אם עבר עליה בשגגה) \u0003קרבן עולה ויורד.\u0004","ואילו \u0003שבועת שוא\u0004 — \u0003חייבין על זדונה מכות, ועל שגגתה פטור.\u0004","על לשון המשנה שואלים: \u0003למה לי למיתני\u0004 \u0005[לשנות]\u0006 בשינוי לשון \u0003\"שבועה שלא אוכל\", \"שבועה שלא אוכלנה\"?\u0004","ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 \u0003טעמא\u0004 \u0005[הטעם,\u0006 מדובר דווקא\u0005]\u0006 ש\u0003אמר\u0004 בתחילה \u0003\"שלא אוכל\" והדר\u0004 \u0005[וחזר]\u0006 ו\u0003אמר \"שלא אוכלנה\"\u0004 — \u0003דלא מיחייב\u0004 \u0005[ש\u0006אז \u0005אינו חייב]\u0006 \u0003אלא חדא\u0004 \u0005[אחת],\u0006 \u0003אבל\u0004 אם \u0003אמר\u0004 תחילה \u0003\"שלא אוכלנה\", והדר\u0004 \u0005[וחזר]\u0006 ו\u0003אמר \"שלא אוכל\"\u0004 — הרי הוא \u0003מיחייב תרתי\u0004 \u0005[מתחייב שתים],\u0006 לפי שהוסיף בשבועה השניה איסור שלא היה בראשונה.","והוא \u0003כ\u0004דברי \u0003רבא,\u0004 ש\u0003אמר רבא:\u0004 אם אמר \u0003\"שבועה שלא אוכל ככר זו\", כיון שאכל ממנה כזית\u0004 — \u0003חייב,\u0004 שכל כזית מככר זו אסור עליו. אבל אם אמר \u0003\"שלא אוכלנה\"\u0004 (אוכל אותה) — \u0003אינו חייב עד שיאכל את כולה.\u0004 ולכן בכלל \"שבועה שלא אוכל\" נכללת \"שבועה שלא אוכלנה\", אבל לא להיפך.","שנינו במשנה: \"שבועה שלא אוכל ככר זו\" \"שבועה שלא אוכלנה\" \u0003\"שבועה שלא אוכלנה\" ואכלה\u0004 — \u0003אינו חייב אלא אחת.\u0004 ושואלים: \u0003הא תו\u0004 \u0005[זו עוד]\u0006 \u0003למה לי\u0004 להוסיף עוד פעם \"שבועה שלא אוכלנה\"?","ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו]:\u0006 \u0003חיובא\u0004 \u0005[חיוב]\u0006 \u0003הוא דליכא\u0004 \u0005[שאין\u0006 בכך\u0005],\u0006 \u0003הא\u0004 \u0005[אבל]\u0006 \u0003שבועה איכא\u0004 \u0005[יש],\u0006 שהשבועה השניה לא בטלה לגמרי. לאיזה ענין? \u0003דאי משכחת רווחא, חיילא\u0004 \u0005[שאם תמצא רווח,\u0006 מקום, \u0005תחול].\u0006","\u0003למאי הלכתא\u0004 \u0005[לאיזו הלכה]?\u0006 \u0003לכ\u0004 דברי \u0003רבא,\u0004 ש\u0003אמר רבא\u0004 לגבי מי שנשבע שתי שבועות על דבר אחר, \u0003שאם נשאל על הראשונה\u0004 והתיר לו החכם את השבועה הראשונה — \u0003עלתה לו שניה תחתיה\u0004 אם לא התירו אותה.","ומציעים: \u0003לימא מסייעא ליה\u0004 \u0005[האם אפשר לומר לסייע לו]\u0006 מברייתא זו: \u0003מי שנדר שתי נזירות, ומנה\u0004 שלושים ימי נזירות \u0003ראשונה\u0004 כדין, \u0003והפריש עליה קרבן, ואחר כך נשאל על הראשונה\u0004 והתירו לו אותה — \u0003עלתה לו\u0004 חובת הנזירות ה\u0003שניה ב\u0004ימי ה\u0003ראשונה,\u0004 ואינו צריך לחזור ולנהוג נזירות. ומכאן משמע שהנזירות השניה חלה על ידי התרת הנזירות הראשונה, וכן הדין בשבועות!","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 \u0003נזירות\u0004 שניה \u0003מיהא איתא\u0004 \u0005[על כל פנים ישנה]\u0006 מתחילה, \u0003דכי מני\u0004 \u0005[שכאשר\u0006 הוא \u0005מונה\u0006 ומסיים\u0005]\u0006 את ה\u0003ראשונה בעי מיהדר מימנא\u0004 \u0005[צריך היה לחזור ולמנות]\u0006 את ה\u0003שניה\u0004 גם \u0003ב\u0004מקרה ש\u0003לא\u0004 היתה \u0003שאלה, הכא\u0004 \u0005[כאן]\u0006 במקרה שלא נשאל על הראשונה \u0003שבועה שניה מי איתא\u0004 \u0005[האם ישנה]\u0006 \u0003כלל?\u0004 ואם כן אין הדברים דומים.","\u0003אמר רבא: נשבע על ככר ואכלה, אם שייר ממנה כזית\u0004 — \u0003נשאל עליה\u0004 על שבועתו ומתיר אותה, אם \u0003אכלה כולה\u0004 — שוב \u0003אין נשאל עליה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר\u0004 בלשון \u0003\"שלא אוכל\u0004 ככר זו\", הרי \u0003מכזית קמא\u0004 \u0005[הראשון]\u0006 שאכל \u0003עבדיה לאיסוריה\u0004 \u0005[עשה את איסורו]\u0006 ועבר על שבועתו, \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר \"שלא אוכלנה\",\u0004 שמשמעות הדבר היא שלא אוכל את כולה, \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 שהשאיר ממנה דווקא \u0003כזית?\u0004"],["\u0003אפילו\u0004 שייר מהככר \u0003כל שהוא נמי\u0004 \u0005[גם כן]\u0006 יכול הוא להישאל על שבועתו, שהרי עדיין לא עבר עליה, כיון שנשבע על כל הככר!","ומתרצים: \u0003אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר שנשבע \u0003\"שלא אוכל\", אי בעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שמדובר שנשבע \u0003\"שלא אוכלנה\".\u0004 ומפרטים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שנשבע \u0003\"שלא אוכל\",\u0004 ולמרות שכבר עבר על האיסור כשאכל מן הככר כזית, \u0003מיגו דמהניא ליה\u0004 \u0005[מתוך שמועילה לו,\u0006 חלה\u0005]\u0006 ה\u0003שאלה\u0004 על ה\u0003כזית בתרא\u0004 \u0005[האחרון]\u0006 שהוא אסור בו בשבועה זו, \u0003מהניא ליה\u0004 \u0005[מועילה לו,\u0006 חלה\u0005]\u0006 ה\u0003שאלה נמי\u0004 \u0005[גם כן]\u0006 על ה\u0003כזית קמא\u0004 \u0005[הראשון],\u0006 ומתבטל למפרע האיסור שהיה בדבר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שנשבע \u0003\"שלא אוכלנה\",\u0004 שאינו עובר על השבועה עד שיאכל את כולה, ולמרות זאת, \u0003אי\u0004 \u0005[אם]\u0006 \u0003שייר\u0004 מהפת \u0003כזית\u0004 שלם שעדיין לא אכלו — \u0003חשיב לאיתשולי עליה\u0004 \u0005[חשוב\u0006 ראוי הוא \u0005להישאל עליו],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 השאיר כזית — \u0003לא חשיב לאיתשולי עליה\u0004 \u0005[חשוב\u0006 כדי \u0005להישאל עליו].\u0006 הנחת היסוד בדברי רבא היתה שמי שנשבע שלא לאכול ואכל הכל שוב אינו יכול להישאל על השבועה.","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003מי שנדר שתי נזירות, ומנה\u0004 ימי נזירות \u0003ראשונה,\u0004 שהשלים כראוי את כל ימי נזירותו הראשונה, \u0003והפריש עליה קרבן, ואחר כך נשאל על הראשונה\u0004 — \u0003עלתה\u0004 (נחשבת) \u0003לו שניה בראשונה.\u0004 הרי אף שהראשונה נגמרה כולה הריהו נשאל עליה!","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 \u0003בשלא כיפר\u0004 כלומר, שלא הביא עדיין את קרבנותיו, ולכן נשאר שיור בראשונה, ויכול להישאל עליה.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]\u0006 שיכול להישאל על נזירותו אפילו כאשר \u0003כיפר\u0004 והקריב את קרבנותיו! ומשיבים: מדובר \u0003בשלא גלח\u0004 עדיין את שערו, \u0003ו\u0004שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר: תגלחת מעכבא\u0004 \u0005[מעכבת],\u0006 שכל זמן שלא גילח עדיין חל עליו דין הנזירות.","ומקשים: \u0003והתניא\u0004 \u0005[והרי שנויה\u0006 ברייתא נוספת\u0005],\u0006 ולפיה גם אם נזיר זה כבר \u0003גלח\u0004 יכול להישאל! \u0003אמר רב אשי:\u0004 מענין \u0003נזירות קא רמית\u0004 \u0005[אתה משליך,\u0006 מקשה\u0005]\u0006 לענין שבועה? אין הדברים דומים, כי \u0003מי גרם ל\u0004נזירות ה\u0003שניה שלא תחול\u0004 עד עכשיו? נזירות \u0003ראשונה, ו\u0004אם כן רק עכשיו, לאחר שנשאל \u0003אינה\u0004 קיימת עוד, הרי שעד עכשיו היא קיימת ומשום כך יכול להישאל. מה שאין כן בשבועה, משעה שאכל את הככר שוב אין השבועה קיימת כלל.","\u0003אמימר אמר,\u0004 בניגוד לדברי רבא: הנשבע שלא לאכול ככר, \u0003אפילו אכלה כולה נשאל עליה,\u0004 כי \u0003אי\u0004 \u0005[אם]\u0006 אכלה \u0003בשוגג\u0004 — הרי עדיין הוא \u0003מחוסר קרבן\u0004 שצריך להביא קרבן על שגגתו ולא הביא, \u0003אי\u0004 \u0005[אם]\u0006 \u0003במזיד\u0004 אכלה — \u0003מחוסר מלקות. אבל\u0004 אם \u0003כפתוהו\u0004 כבר \u0003על העמוד\u0004 להלקותו, אף שעדיין לא הלקוהו — \u0003לא\u0004 יכול עוד להישאל, \u0003כ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל:\u0004 אדם שנידון למלקות, אם \u0003כפתוהו על העמוד\u0004 להלקותו, \u0003ורץ\u0004 וברח \u0003מבית דין\u0004 — \u0003פטור\u0004 מן המלקות, משום שאנו אומרים שהכפיתה היא כתחילת נתינת המלקות.","ודוחים: \u0003ולא היא,\u0004 אין הדבר דומה, \u0003התם\u0004 \u0005[שם]\u0006 מדובר במי ש\u0003רץ\u0004 וברח, ושוב אינו עומד ללקות, \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003לא רץ,\u0004 ולפיכך עונש המלקות עדיין מוטל עליו.","\u0003אמר רבא:\u0004 אם נשבע באופן כזה \u0003\"שבועה שלא אוכל ככר זו אם אוכל זו\"\u0004 שהתנה שרק אם יאכל את ככר התנאי, יחול איסור שבועה על האחרת, \u0003ואכל את הראשונה\u0004 את הככר של התנאי \u0003בשוגג, ו\u0004את \u0003השניה\u0004 שנאסרה עליו בגלל אכילת הראשונה אכל \u0003במזיד\u0004 — \u0003פטור,\u0004 שבזמן שצריכה השבועה לחול (בשעת אכילת התנאי) לא היה מודע לדבר, ואמרנו (לעיל שבועות כז,א) שאם אין ליבו שלם בשבועה לא חלה השבועה. אבל אם אכל את ה\u0003ראשונה במזיד\u0004 שידע שאם יאכל אותה ייאסר באחרת, \u0003ו\u0004את ה\u0003שניה\u0004 אכל \u0003בשוגג\u0004 — הרי הוא \u0003חייב\u0004 קרבן, ככל אדם שעבר על שבועתו בשגגה. אם אכל את \u0003שתיהן בשוגג\u0004 — \u0003פטור,\u0004 שהרי את התנאי אכל בשוגג, ואם כן לא חלה השבועה."],["אכל את \u0003שתיהן במזיד,\u0004 אם \u0003אכליה לתנאיה\u0004 \u0005[אכל את תנאו,\u0006 את הככר שהתנה עליה\u0005],\u0006 \u0003והדר אכליה לאיסוריה\u0004 \u0005[ואחר כך אכל את איסורו]\u0006 את הככר שנאסרה עליו מחמת התנאי — \u0003מיחייב\u0004 \u0005[חייב]\u0006 מלקות על אכילת האיסור, שהרי אכל במזיד דבר שנאסר עליו בשבועה. אבל אם \u0003אכליה לאיסוריה\u0004 \u0005[אכל את\u0006 הככר \u0005של האיסור]\u0006 \u0003והדר אכליה לתנאיה\u0004 \u0005[ואחר כך אכל את\u0006 הככר \u0005של התנאי]\u0006 — הרי זו \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003ר' יוחנן וריש לקיש, למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003התראת ספק שמה התראה\u0004 — הרי הוא \u0003חייב\u0004 מלקות, שכן התראה כזו, שאם יאכל ככר זו הוא עתיד ללקות על אכילת הככר האחרת אף שבשעת ההתראה ספק הוא אם יעשה כן — הריהי התראה, וחייב מלקות. \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 התראת ספק \u0003לאו\u0004 \u0005[אין]\u0006 \u0003שמה התראה,\u0004 שאין התראה נחשבת אלא כשהאדם עומד בוודאי לעבור על איסור — \u0003פטור\u0004 מן המלקות, כיון שנחשב הדבר כמי שלא התרו בו.","ובמקרה אחר, אם נשבע על שתי ככרות ו\u0003תלאן זו בזו,\u0004 שאומר כך: \u0003\"לא אוכל זו אם אוכל זו,\u0004 וכן \u0003לא אוכל זו אם אוכל זו\", ואכל זו\u0004 אחת מהן \u0003בזדון עצמה ובשגגת חבירתה,\u0004 שבשעת אכילה ידע שנשבע שלא יאכלנה אם יאכל את השניה, אבל שכח שאסר את השניה בשבועה אם יאכל את זו. \u0003ו\u0004אחר כך אכל גם את \u0003זו\u0004 האחרת \u0003בזדון עצמה ובשגגת חבירתה\u0004 שנזכר שנשבע שלא יאכל את זו אם אכל את הראשונה, ושכח שנשבע שלא יאכל את הראשונה אם יאכל את זו — \u0003פטור\u0004 על שתיהן, לפי, שלא חלה השבועה, שהרי שבשעת אכילת התנאי לא זכר שהוא אוסר על ידי כן את הככר האחרת.","אבל אם אכל \u0003זו בשגגת עצמה ובזדון חבירתה\u0004 שלא זכר שיש בה איסור אם יאכל את חברתה, אבל זכר שכאשר אוכל את זו ייאסר באחרת, \u0003ו\u0004כן אכל את \u0003זו בשגגת עצמה ובזדון חבירתה\u0004 ששכח שנאסר בשניה בגלל הראשונה, אבל נזכר שאם יאכל את זו נאסרה הראשונה — \u0003חייב,\u0004 שהרי בשעת אכילת התנאי זכר שהאחרת נאסרת בכך.","אם אכל את \u0003שתיהן בשוגג\u0004 — \u0003פטור,\u0004 שהרי שגג בתנאי.","אם אכל את \u0003שתיהן במזיד\u0004 — על ה\u0003שניה מיחייב\u0004 \u0005[חייב]\u0006 מלקות. על ה\u0003ראשונה\u0004 — \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 \u0003ר' יוחנן וריש לקיש\u0004 כמו שנזכר קודם לגבי התראת ספק, האם התראה כזו שאם יאכל את הככר השניה יעבור על השבועה באכילת ככר זו ילקה — התראה היא.","\u0003אמר רב מרי, אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 ראיה לדברי רבא, שאם נשבע על תנאי ואינו זוכר את השבועה בשעה שהתנאי חל — אין השבועה חלה עליו. ששנינו, \u0003ארבעה נדרים התירו חכמים\u0004 שאינם נחשבים לנדרים: \u0003נדרי זרוזין\u0004 כגון שבשעת משא ומתן נודר שלא ימכור אלא בסכום מסויים, משום שבאמת אינו מתכוון לכך, \u0003נדרי הבאי\u0004 שנודר על דבר שידוע לכל שהוא שקר, \u0003נדרי שגגות, נדרי אונסין\u0004 שנאנס על ידי אחרים לנדור.","ומסבירים במשנה שם: \u0003נדרי שגגות, כיצד?\u0004 אמר \u0003\"קונם\u0004 עלי דבר מסויים \u0003אם אכלתי ואם שתיתי\", ונזכר\u0004 לאחר שאמר זאת \u0003שאכל ושתה,\u0004 או אמר \"קונם עלי דבר מסויים \u0003שאיני אוכל, שאיני שותה\",\u0004 כלומר, אם אוכל או אם אשתה, ו\u0003שכח\u0004 את נדרו \u0003ואכל ושתה\u0004 — \u0003מותר\u0004 באותו דבר, משום שבשעת התנאי, שאז הנדר (הקונם) היה שוגג. \u0003ותני עלה\u0004 \u0005[ושנויה\u0006 ברייתא \u0005עליה,\u0006 על משנה זו\u0005]:\u0006 \u0003כשם שנדרי שגגות מותרין, כך שבועות שגגות מותרות.\u0004","ונברר: \u0003שבועות שגגות, היכי דמי\u0004 \u0005[כיצד הן]?\u0006 \u0003לאו כי האי גוונא\u0004 \u0005[האם לא כגון זה],\u0006 שמתנה תנאי בשבועה, ובשעת חלות התנאי שוכח את הדבר? \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 ראיה לדברי רבא.","מסופר, החכם \u0003עיפא תני\u0004 \u0005[למד]\u0006 מסכת \u0003שבועות בי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003רבה, פגע ביה\u0004 \u0005[פגש אותו]\u0006 \u0003אבימי אחוה\u0004 \u0005[אחיו],\u0006 ובחנו בדיני שבועות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אבימי: אם נשבע \u0003\"שבועה שלא אכלתי\",\u0004 ושוב: \u0003\"שבועה שלא אכלתי\", מהו\u0004 דינו אם עבר על דבריו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינו חייב אלא אחת,\u0004 שסבר שאין שבועה חלה על שבועה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אישתבשת\u0004 \u0005[השתבשת\u0006 בדבריך טעית\u0005],\u0006 כי \u0003הרי\u0004 כבר \u0003יצאה שבועה לשקר\u0004 בשעה שאמרה, וכבר עבר את העבירה, והשבועה השניה אף היא שבועת שקר גמורה.","ועוד שאל אותו: אם אמר \u0003\"שבועה שלא אוכל תשע, ועשר\",\u0004 כלומר, נשבע תחילה שלא יאכל תשע (כגון תאנים), וחזר ונשבע שלא יאכל עשר \u0003מהו?\u0004 אמר לו: \u0003חייב על כל אחת ואחת\u0004 מן השבועות, שהרי שבועה אחרונה כוללת יותר מן הראשונה ומוסיפה עליה. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אישתבשת\u0004 \u0005[השתבשת\u0006 טעית\u0005],\u0006 שכשנשבע על עשר חזר על שבועתו הראשונה, שהרי \u0003אי\u0004 \u0005[אם]\u0006 \u0003תשע לא אכיל\u0004 \u0005[אוכל],\u0006 \u0003עשר לא אכיל\u0004 \u0005[אוכל],\u0006 שאינו יכול לאכול עשר אלא אם כן אכל קודם תשע, ואין שבועה חלה על שבועה, וממילא על שבועה אחת הוא עובר.","ועוד שאלו אבימי: אם אמר \u0003\"שבועה שלא אוכל עשר ותשע\",\u0004 שקודם נשבע שלא יאכל עשר, ואחר כך נשבע שלא יאכל תשע \u0003מהו?\u0004 אמר לו: \u0003אינו חייב אלא אחת,\u0004 שהיה סבור שהשבועה השניה בכלל הראשונה היא. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אבימי: \u0003אישתבשת\u0004 \u0005[טעית],\u0006 שכן לפי השבועה הראשונה \u0003עשר הוא\u0004 ש\u0003לא אכיל\u0004 \u0005[אוכל],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003תשע מיהא אכיל\u0004 \u0005[בכל זאת אוכל]\u0006 שהרי לא נשבע על כך, ולפיכך חלה שבועה על התשע. ואם יאכל עשר — יתחייב משום שתי שבועות.","\u0003אמר אביי: זימנין דמשכחת לה להא\u0004 \u0005[פעמים שאתה מוצא אותה]\u0006 אפשרות שיהיה כדברי \u0003עיפא,\u0004 שנשבע שלא יאכל עשר ואחר כך שלא יאכל תשע, ובכל זאת יתחייב רק על שבועה אחת, כמו שאמר \u0003מר\u0004 \u0005[אדוני]\u0006 רבה, ש\u0003אמר רבה:\u0004 נשבע \u0003\"שבועה שלא אוכל תאנים וענבים\u0004 יחד\", \u0003וחזר ואמר \"שבועה שלא אוכל תאנים\",\u0004"],["\u0003ואכל תאנים\u0004 בשגגה \u0003והפריש קרבן\u0004 על שבועתו השניה, \u0003ואחר כך אכל ענבים לחודייהו\u0004 \u0005[לבדם]\u0006 בשגגה, \u0003הויא להו\u0004 \u0005[הריהם]\u0006 ה\u0003ענבים חצי שיעור\u0004 של שבועתו הראשונה, שהרי נשבע שלא יאכל תאנים וענבים גם יחד, \u0003ו\u0004על \u0003חצי שיעור לא מיחייב\u0004 \u0005[מתחייב]\u0006 \u0003קרבן.\u0004 אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן],\u0006 \u0003כגון\u0004 ש\u0003אמר \"שבועה שלא אוכל עשר\"\u0004 (שעדיין אינו אסור בתשע) \u0003וחזר ואמר \"שבועה שלא אוכל תשע\", ואכל תשע והפריש קרבן\u0004 על שבועתו השניה, \u0003ואחר כך אכל\u0004 את ה\u0003עשירית, הויא לה\u0004 \u0005[הריהי]\u0006 \u0003עשירית\u0004 זו רק \u0003חצי שיעור,\u0004 משום שהיא רק חלק מן השבועה של העשר, \u0003ו\u0004על \u0003חצי שיעור לא מיחייב\u0004 \u0005[מתחייב]\u0006 קרבן.","\u0003איזו היא שבועת שוא\u0004 שהוזכרה קודם לכן (ראה לעיל שבועות כז,ב)? כמה אופנים הם: אופן אחד מי ש\u0003נשבע לשנות את הידוע לאדם\u0004 כלומר, שנשבע על דבר שידוע שאינו כדברי שבועתו, כגון: \u0003אמר על העמוד של אבן שהוא של זהב, ועל האיש שהוא אשה, ועל האשה שהיא איש.\u0004","אופן אחר הריהו במי ש\u0003נשבע על דבר שאי אפשר לו\u0004 להיות, כגון הנשבע: \u0003\"אם לא ראיתי גמל שפורח באויר\", ו\"אם לא ראיתי נחש\u0004 גדול \u0003כקורת בית הבד\".\u0004","אופן אחר של שבועת שוא הוא שבועה לבטל מצוה, אם \u0003אמר לעדים: \"בואו והעידוני\",\u0004 והם אומרים: \u0003\"שבועה שלא נעידך\".\u0004 וכן כל מי ש\u0003נשבע לבטל את המצוה,\u0004 כגון: \u0003שלא לעשות סוכה, ושלא ליטול לולב, ושלא להניח תפילין\u0004 — \u0003זו היא שבועת שוא,\u0004 ששנינו ש\u0003חייבין על זדונה\u0004 אם נשבע בזדון \u0003מכות, ועל שגגתה פטור.\u0004","אם אמר: \u0003\"שבועה שאוכל ככר זו\",\u0004 ואחר כך אמר: \u0003\"שבועה שלא אוכלנה\"\u0004 — \u0003הראשונה שבועת ביטוי, והשניה\u0004 היא \u0003שבועת שוא,\u0004 שהרי נשבע לעבור על איסור שבועה.","אם \u0003אכלה\u0004 — \u0003עבר על שבועת שוא, לא אכלה\u0004 — \u0003עבר על שבועת ביטוי.\u0004","על מה ששנינו שהנשבע לשנות את הידוע לאדם היא שבועת שוא, כגון הנשבע על עמוד של אבן שהוא של זהב, \u0003אמר עולא: והוא שניכר\u0004 אותו עמוד לפחות \u0003לשלשה בני אדם\u0004 ויודעים שהוא של אבן. שדווקא דבר שהוא מפורסם לרבים והוא נשבע לשנותו הרי זו שבועת שוא.","\u0003נשבע על דבר שאי אפשר לו \"אם לא ראיתי גמל פורח באויר\".\u0004 ומדקדקים בלשון: הרי \u0003\"שבועה שראיתי\" לא קאמר\u0004 \u0005[אמר],\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש בלשון התורה \u0003\"אם לא ראיתי\"?\u0004 \u0003אביי אמר,\u0004 תקן בלשון \u0003תני\u0004 \u0005[שנה]\u0006 \u0003\"שבועה שראיתי\". רבא אמר\u0004 שהוא חלק ממשפט גדול יותר, \u0003באומר: \"יאסרו כל פירות שבעולם עלי אם לא ראיתי גמל פורח באויר\".\u0004","על שבועה זו \"אם לא ראיתי גמל פורח באויר\", \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: ודלמא האי גברא\u0004 \u0005[ושמא אדם זה]\u0006 שנשבע שבועה זו, \u0003ציפורא רבא חזי\u0004 \u0005[ציפור גדולה ראה]\u0006 שעפה באויר, \u0003ואסיק ליה שמא\u0004 \u0005[וקרא לה בשם]\u0006 \u0003גמלא\u0004 \u0005[גמל],\u0006 \u0003וכי קא משתבע\u0004 — \u0003אדעתיה דידיה אישתבע\u0004 \u0005[וכאשר הוא נשבע\u0006 — \u0005על דעתו שלו נשבע],\u0006 והרי לפי האופן שהוא מגדיר את הדברים באמת נשבע!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003בתר פומיה אזלינן, ולא אזלינן בתר דעתיה\u0004 \u0005[אחרי פיו אנו הולכים, ואין אנו הולכים אחר דעתו]\u0006 שאינו כמשמעות הלשון, \u0003והא תניא\u0004 \u0005[והרי שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כשמשביעין אותו\u0004 את החייב שבועה בבית דין, \u0003אומרים לו\u0004 הדיינים: \u0003הוי יודע, שלא על דעתך אנו משביעין אותך אלא על דעתנו ועל דעת בית דין; מאי טעמא\u0004 \u0005[מה טעם הדבר]?\u0006 \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 מעשים כגון זה, \u0003דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003דלמא איסקונדרי יהיב ליה\u0004 \u0005[שמא פיסות עץ נתן לו]\u0006 לבעל חובו \u0003ואסיק להו זוזי\u0004 \u0005[והוא קורא להם\u0006 בליבו \u0005מטבעות],\u0006 \u0003דכי קא משתבע\u0004 — \u0003אדעתיה דידיה קא משתבע\u0004 \u0005[שכאשר הוא נשבע\u0006 — \u0005על דעתו שלו הוא נשבע],\u0006 ומשום כך צריך להזהיר אותו ששבועה זו אינה על דעתו אלא על דעת בית דין?","ודחה רב אשי: \u0003לא,\u0004 פירוש כזה שהוא עושה לדבריו לא היה מועיל, שכיון שנשבע על מטבעות הרי זו שבועה על מטבעות ממש. אלא \u0003התם\u0004 \u0005[שם]\u0006 משביעים אותו כך \u0003משום\u0004 מעשים כגון המעשה שהיה ב\u0003קניא\u0004 \u0005[קנה]\u0006 של \u0003רבא,\u0004 שנתן אדם לתובע קנה מלא מטבעות ונשבע שכבר נתן לו הכל, שאף שהיתה בזה מרמה, מכל מקום נשבע על עובדה אמיתית.","ומקשים עוד באותו ענין: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה שאמרו חכמים באותה ברייתא: \u0003וכן מצינו כשהשביע משה את ישראל\u0004 על קיום התורה, ואמר להם: \"ולא אתכם לבדכם אני כורת את הברית הזאת\" וכו' (דברים כט, יג), \u0003אמר להן\u0004 משה: \u0003דעו, שלא על דעתכם אני משביע אתכם, אלא על דעת המקום ועל דעתי; ואמאי\u0004 \u0005[ומדוע]\u0006 היה צריך לומר כך? \u0003לימא להו\u0004 \u0005[שיאמר להם]\u0006 רק: \u0003קיימו מאי דאמר\u0004 \u0005[מה שאמר]\u0006 \u0003אלוה,\u0004 ועל כך הם נשבעים; \u0003לאו\u0004 \u0005[האם לא]\u0006 הוסיף ואמר להם שעל דעתו הם נשבעים \u0003משום דמסקי אדעתייהו\u0004 \u0005[ש\u0006הוא חושש שמא \u0005יעלו על דעתם]\u0006 שהם נשבעים ל\u0003עבודה זרה\u0004 למרות שבפיהם הם נשבעים לקיים את דברי ה'?","ודוחים: \u0003לא,\u0004 הטעם אינו משום שהם יחשבו בלבם על דבר אחר ממה שנשבעו עליו, אלא \u0003משום\u0004 ש\u0003עבודה זרה\u0004 עצמה \u0003נמי איקרי\u0004 \u0005[גם כן נקראת]\u0006 \u0003\"אלוה\", דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"אלהי כסף ואלהי זהב\"\u0004 (שמות כ, ה), ולכך היתה דעתם מועילה, אלמלא התנאי שהתנה עמם.","וחוזרים ומקשים: אם כן, שמחשבה אינה מועילה נגד דיבור מפורש, \u0003ולימא להו\u0004 \u0005[ושיאמר להם]\u0006 ר ק כך: \u0003קיימו תורה!\u0004 ומשיבים: אם כך היה אומר, הרי משמעות הדברים היא רק \u0003חדא תורה\u0004 \u0005[תורה אחת],\u0006 והיו נשבעים על מנת לקיים או תורה שבכתב או שבעל פה. ומקשים: \u0003ולימא\u0004 \u0005[ושיאמר להם]:\u0006 \u0003קיימו שתי תורות!\u0004 ומשיבים: יש במשמעות הדברים עניינים מצומצמים יותר, כגון \u0003תורת חטאת, תורת אשם.\u0004 ומקשים, יכול היה לומר להם: \u0003קיימו כל התורה כולה!\u0004 ומשיבים: שיש במשמעות הדברים איסור \u0003עבודה זרה\u0004 בלבד, ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003חמורה עבודה זרה, שכל הכופר בה\u0004 — \u0003כמודה בכל התורה כולה,\u0004 ולכן אפשר לקרוא לה \"כל התורה\"!","ומקשים: \u0003ולימא להו\u0004 \u0005[ושיאמר להם]:\u0006 \u0003קיימו מצוה!\u0004 ומשיבים: אפשר להבין שהכוונה היא ל\u0003חדא מצוה\u0004 \u0005[מצוה אחת\u0006 בלבד\u0005].\u0006 ועוד מקשים: הרי היה יכול לומר: \u0003קיימו מצו‍ת!\u0004 ומשיבים, אף זו אינה לשון ברורה, שיכולים גם להבינה במשמעות של \u0003תרתי\u0004 \u0005[שתי]\u0006 מצוות בלבד. ומקשים: שיאמר להם: קיימו \u0003כל המצו‍ת כולן!\u0004 ומשיבים: אפשר לפרש זאת כקיום \u0003מצות ציצית,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003שקולה מצות ציצית כנגד כל המצו‍ת כולן.\u0004","ומקשים: \u0003ולימא להו\u0004 \u0005[ושיאמר להם]:\u0006 \u0003קיימו שש מאות ושלש עשרה מצו‍ת\u0004 ואז יהיה הדבר ברור! ואומרים: \u0003ולטעמיך\u0004 \u0005[ולשיטתך],\u0006 שהיה יכול להבטיח את הבנת הדברים כראוי בלשון אחרת, ומשנזקק להשביע אותם על דעתו משמע שמחשבה שבלב היתה מועילה לענין השבועה, \u0003לימא להו\u0004 \u0005[שיאמר להם]\u0006 רק: אתם נשבעים \u0003על דעתי, על דעת המקום למה לי\u0004 לומר? שהרי לכאורה מספיק שיאמר שהיא על דעתו שלו!"],["\u0003אלא\u0004 שעשה זאת \u0003כי היכי דלא תהוי\u0004 \u0005[שלא תהיה]\u0006 \u0003הפרה לשבועתייהו\u0004 \u0005[לשבועתם],\u0006 כי על ידי כך נעשית זאת כשבועה על דעת רבים (דעת המקום ודעתו), ושבועה על דעת רבים אין יכולים להתיר. ואין מכאן ראיה לענייננו, שמחשבה שבליבם אכן היתה מועילה.","שנינו במשנה בענין נשבע על דבר שאי אפשר לו: \u0003\"ואם לא ראיתי נחש כקורת בית הבד\".\u0004 ושואלים: \u0003ולא?\u0004 וכי אין נחש גדול כזה? \u0003והא ההוא דהוה\u0004 \u0005[והרי\u0006 היה \u0005אותו\u0006 נחש \u0005שהיה]\u0006 \u0003בשני\u0004 \u0005[בשנותיו]\u0006 של \u0003שבור מלכא, הוה חד דאחזיק תליסר אורוותא תיבנא\u0004 \u0005[היה אחד שהחזיק,\u0006 שבלע, \u0005שלוש עשרה אורוות של תבן]!\u0006","\u0003אמר שמואל:\u0004 לא מדובר במשנתנו בנשבע על גודלו של הנחש שהוא כקורת בית הבד, אלא \u0003ב\u0004צורתו, שהוא \u0003טרוף,\u0004 שהוא ישר ושטוח כמו קורת בית הבד. ואומרים: \u0003כולהו נמי מיטרף טריפין\u0004 \u0005[\u0006כל הנחשים \u0005כולם גם כן שטוחים]!\u0006 ומשיבים: \u0003ב\u0004נשבע \u0003שגבו טרוף,\u0004 שהנחשים שטוחים בגחונם, אבל לא בגבם.","שנינו במשנה: \u0003\"שבועה שאוכל ככר זו\", \"שבועה שלא אוכלנה\"\u0004 — הראשונה שבועת ביטוי, והשניה שבועת שוא (שנשבע לבטל שבועה). אכלה — עובר משום שבועת שוא, ואם לא אכלה — עובר משום שבועת ביטוי. ושואלים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 \u0003משום שבועת ביטוי מיחייב\u0004 \u0005[מתחייב],\u0006 כשלא אכלה, \u0003משום שבועת שוא לא מיחייב\u0004 \u0005[מתחייב]?\u0006 \u0003הרי\u0004 מיד שנשבע להתיר דבר האסור לו \u0003יצתה שבועה לשוא,\u0004 בלא קשר למה שהוא עושה!","\u0003אמר ר' ירמיה, תני\u0004 \u0005[שנה]:\u0006 לא אכלה — עבר על שבועת שוא, ו\u0003אף על שבועת ביטוי.\u0004","\u0003שבועת ביטוי נוהגת\u0004 (שלא כשבועת העדות שבפרק הבא) בין \u0003באנשים ו\u0004בין \u0003בנשים,\u0004 בין \u0003בקרובים ו\u0004בין \u0003ברחוקים,\u0004 בין \u0003בכשרין ו\u0004בין \u0003בפסולין,\u0004 בין שנשבע \u0003בפני בית דין ושלא בפני בית דין,\u0004 ובשנשבע \u0003מפי עצמו. וחייבין על זדונה מכות ועל שגגתה קרבן עולה ויורד.\u0004","וכן \u0003שבועת שוא נוהגת באנשים ובנשים, ברחוקים ובקרובים, בכשרין ובפסולין, בפני בית דין ושלא בפני בית דין, ומפי עצמו, וחייבין על זדונה מכות ועל שגגתה פטור.\u0004","\u0003אחת זו ואחת זו,\u0004 בין שבועת ביטוי ובין שבועת שוא — גם \u0003המושבע מפי אחרים חייב,\u0004 כגון \u0003אם\u0004 אומר: \u0003\"לא אכלתי היום\" ו\u0004כיוצא בזה \u0003\"לא הנחתי תפלין היום\",\u0004 ואמר לו חבירו: \u0003\"משביעך אני\" ואמר: \"אמן\",\u0004 אם היה הדבר שקר — הרי זה \u0003חייב.\u0004","\u0003אמר שמואל: כל העונה \"אמן\" אחר שבועה\u0004 — \u0003כמוציא שבועה בפיו דמי\u0004 \u0005[נחשב],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 כאשר הכהן משביע את האשה החשודה כסוטה: \u0003\"ואמרה האשה אמן אמן\"\u0004 (במדבר ה, כב), שאף שאינה נשבעת, נחשב לה הדבר כשבועה.","\u0003אמר רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: מתניתין וברייתא נמי דיקא\u0004 \u0005[המשנה והברייתא גם כן מדוייקות]\u0006 כשיטה זו, כאשר אנו משווים את שתיהן. \u0003דקתני\u0004 \u0005[ש\u0006הוא \u0005שונה\u0006 במשנה\u0005]:\u0006 \u0003שבועת העדות נוהגת\u0004 רק באלה היכולים לשמש כעדים, ולכן נוהגת \u0003באנשים ולא בנשים, ברחוקים ולא בקרובים\u0004 קרבת משפחה לבעלי הדין, שהם פסולים להעיד מחמת קרבתם, \u0003בכשרין ולא בפסולין\u0004 לעדות, \u0003ואינה נוהגת אלא ב\u0004אלה שהם \u0003ראוין להעיד, ובפני בית דין ושלא בפני בית דין מפי עצמו, ו\u0004אולם \u0003מפי אחרים\u0004 — \u0003אינן חייבין עד שיכפרו בהן בבית דין,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ותניא\u0004 \u0005[ו\u0006מצד אחר \u0005שנויה]\u0006 \u0003בברייתא\u0004: \u0003שבועת העדות כיצד? אמר לעדים: \"בואו והעידוני\"\u0004 והם אמרו: \u0003\"שבועה שאין אנו יודעין לך עדות\". או שאמרו\u0004 לו אחרי שביקש מהם: \u0003\"אין אנו יודעין לך עדות\",\u0004 ואמר להם: \u0003\"משביע אני עליכם\", ואמרו: \"אמן\", בין\u0004 שאמרו זאת \u0003בפני בית דין בין שלא בפני בית דין, בין\u0004 שהשביעם \u0003מפי עצמו בין מפי אחרים, כיון שכפרו בהם\u0004 — \u0003חייבין,\u0004 אלו \u0003דברי ר' מאיר.\u0004","ולכאורה \u0003קשיין אהדדי\u0004 \u0005[קשים הם זה על זה]\u0006 שהרי הוא אומר במשנה כי מפי אחרים, אין הוא חייב שלא בפני דין! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שיש להבדיל: \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003ענה \"אמן\"\u0004 הרי הוא מתחייב על השבועה גם שלא בפני בית דין, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003לא ענה \"אמן\"?\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","\u0003אמר רבינא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: מתניתין דהכא נמי דיקא\u0004 \u0005[המשנה של כאן גם כן מדוייקת]\u0006 כשיטה זו, \u0003דקא תני\u0004 \u0005[שהוא שונה]:\u0006 \u0003שבועת ביטוי נוהגת באנשים ובנשים, ברחוקים ובקרובים, בכשרין ובפסולין, בפני בית דין ושלא בפני בית דין, מפי עצמו\u0004 — ואם נדייק: מפי עצמו \u0003אין\u0004 \u0005[כן],\u0006 \u0003מפי אחרים\u0004 — \u0003לא; וקתני סיפא\u0004 \u0005[ו\u0006הוא \u0005שונה בסופה]:\u0006 \u0003זה וזה מושבע מפי אחרים\u0004 — \u0003חייב,\u0004 ולכאורה","\u0003קשיין אהדדי\u0004 \u0005[\u0006הרי הם \u0005קשים זה על זה]!\u0006 \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תלמד מכאן]\u0006 שיש לחלק: \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003ענה \"אמן\"\u0004 חייב גם מפי אחרים, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003לא ענה \"אמן\"\u0004 אינו חייב. \u0003ו\u0004שואלים: לפי שהוכחנו את הדבר הזה מכמה מקורות, \u0003אלא שמואל מאי קא משמע לן\u0004 \u0005[מה הוא משמיע לנו]?\u0006 הרי הדבר עולה יפה מתוך המקורות הללו! ומשיבים: \u0003דוקיא דמתניתין קא משמע לן\u0004","",""],["\u0003שבועת העדות נוהגת באנשים ולא בנשים, ברחוקין\u0004 בבעלי דין שאין קרבת משפחה ביניהם, \u0003ולא בקרובין, בכשרין\u0004 לעדות \u0003ולא בפסולין\u0004 לעדות מחמת עבירה, \u0003ואינה נוהגת אלא בראוין להעיד.\u0004","ונוהגת שבועה זו \u0003בפני בית דין ושלא בפני בית דין,\u0004 כאשר העד נשבע \u0003מפי עצמו\u0004 שאינו יודע בעדות. \u0003ו\u0004אולם \u0003מפי אחרים,\u0004 אם אחרים משביעים אותם — \u0003אין חייבין\u0004 העדים משום שבועת העדות, אלא \u0003עד שיכפרו בהן\u0004 בשבועה \u0003בבית דין, דברי ר' מאיר. וחכמים אומרים: בין\u0004 שנשבע העד \u0003מפי עצמו ובין מפי אחרים\u0004 — \u0003אינן חייבין עד שיכפרו בהן\u0004 בעלי הדין \u0003בבית דין.\u0004","\u0003וחייבין על זדון השבועה\u0004 הזו, \u0003ועל שגגתה עם זדון העדות\u0004 שאינם יודעים את פרטי ההלכה בענין שבועה זו, אבל יודעים הם שהם מעידים שקר. אבל \u0003אינן חייבין על שגגתה\u0004 הגמורה, כשסבורים שבאמת אינם יודעים את העדות. \u0003ומה הן חייבין על זדון השבועה? קרבן עולה ויורד.\u0004","אמרנו במשנה שאין שבועת העדות נוהגת בנשים משום שאינן ראויות להעיד. ושואלים \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שנשים אינן מעידות? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \"כי יקום עד חמס באיש... \u0003ועמדו שני האנשים\"\u0004 (דברים יט, יב) — \u0003בעדים הכתוב מדבר,\u0004 ולמדים מכאן: אנשים דוקא מעידים ולא נשים.","ודנים בדבר: \u0003אתה אומר: בעדים\u0004 מדובר, \u0003או אינו אלא בבעלי דינין? כשהוא אומר\u0004 בהמשך הכתוב: \u0003\"אשר להם הריב\"\u0004 (דברים יט, יב) — \u0003הרי\u0004 \u0003בעלי דינין אמור\u0004 בכתוב, \u0003הא\u0004 \u0003מה אני מקיים\u0004 במה יש להעמיד את הכתוב \u0003\"ועמדו שני האנשים\"? בעדים הכתוב מדבר. ואם נפשך לומר\u0004 ולטעון כנגד זה, אביא לך ראיה אחרת: \u0003נאמר כאן \"שני\u0004 האנשים\" \u0003ונאמר להלן \"שני\"\u0004 — \"על פי שני עדים\" (דברים יט, טו), \u0003מה להלן\u0004 מדובר \u0003בעדים, אף כאן\u0004 מדובר \u0003בעדים.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"אם נפשך לומר\"?\u0004 מה היתה הטענה שאפשר היה לטעון? ומסבירים: כך היתה הטענה, \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003מ\u0004מה ש\u0003לא כתב\u0004 המקרא \"ועמדו שני האנשים \u0003ואשר להם הריב\",\u0004 לומר שמכאן מתחיל הכתוב לדבר בבעלי הדין, אם כן אפשר לפרש \u0003כוליה קרא\u0004 \u0005[כל המקרא]\u0006 \u0003בבעלי דינין משתעי\u0004 \u0005[מדבר],\u0006 על כן מביאים ראיה אחרת: \u0003נאמר כאן \"שני\" ונאמר להלן \"שני\", מה להלן\u0004 מדובר \u0003בעדים, אף כאן בעדים.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 בענין זה: \u0003\"ועמדו שני האנשים\"\u0004 — \u0003בעדים הכתוב מדבר.\u0004 ויש לדון: \u0003אתה אומר: בעדים, או אינו אלא בבעלי דינין?\u0004 על כך יש לתמוה: \u0003אמרת\u0004 \u0005[אומר אתה\u0006 כך\u0005]?\u0006 אם כן מדוע מדובר בשנים? \u0003וכי שנים באים לדין, שלשה אין באין לדין?! ואם נפשך לומר\u0004 כנגד טענה זו, אפשר להביא ראיה אחרת: \u0003נאמר כאן \"שני\" ונאמר להלן \"שני\", מה להלן בעדים, אף כאן בעדים.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 עניינו של \u0003\"אם נפשך לומר\"?\u0004 מה היתה הטענה שאפשר היה לטעון? ומסבירים, \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003בתובע ונתבע קא משתעי קרא\u0004 \u0005[מדבר המקרא],\u0006 שהכוונה היא פה לשני הצדדים המתדיינים בדין, אף שיכול להיות שיהיו אנשים מרובים בכל צד, על כן מביאים ראיה אחרת: \u0003נאמר כאן \"שני\" ונאמר להלן \"שני\", מה להלן\u0004 מדובר \u0003בעדים, אף כאן בעדים.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 בענין זה: \u0003\"ועמדו שני האנשים\"\u0004 — \u0003בעדים הכתוב מדבר. אתה אומר: בעדים, או אינו אלא בבעלי דינין? אמרת? וכי אנשים באין לדין, נשים אין באות לדין? ואם נפשך לומר, נאמר כאן \"שני\" ונאמר להלן \"שני\", מה להלן בעדים, אף כאן בעדים.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 הטענה שאפשר היה לטען שרמז לה ב\u0003\"אם נפשך לומר\"?\u0004 ומסבירים, \u0003וכי תימא\u0004 \u0005[ואם תאמר]:\u0006 \u0003אשה לאו אורחה\u0004 \u0005[אין דרכה]\u0006 ללכת לבית דין, \u0003משום \"כל כבודה בת מלך פנימה\"\u0004 (תהלים מה, יד), שאין דרכן של נשים ללכת למקום ציבורי להתבזות בבית הדין, ואפשר היה לומר שהכתוב מדבר בהווה, שסתם מתדיינים הם גברים, ואין הכוונה כאן למעט נשים מעדות. על כן מביאים ראיה אחרת: \u0003נאמר כאן \"שני\" ונאמר להלן \"שני\", מה להלן בעדים, אף כאן בעדים.\u0004","ומביאים דרשה נוספת בפסוק שדנו בו. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"ועמדו שני האנשים\"\u0004 — \u0003מצוה לבעלי דינין שיעמדו\u0004 בזמן הדיונים בעניינם. \u0003אמר ר' יהודה: שמעתי, שאם רצו\u0004 בית הדין \u0003להושיב את שניהם\u0004 — \u0003מושיבין, איזהו\u0004 דבר ש\u0003אסור\u0004 לעשות? \u0003שלא יהא אחד\u0004 מבעלי הדין \u0003עומד ואחד יושב, אחד מדבר כל צרכו ואחד אומר לו\u0004 הדיין: \u0003\"קצר דבריך\".\u0004","וכיוצא בזה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"בצדק תשפט עמיתך\"\u0004 (ויקרא יט, טו) — \u0003שלא יהא אחד\u0004 מבעלי הדין \u0003יושב ואחד עומד, אחד מדבר כל צרכו ואחד אומר לו: \"קצר דבריך\". דבר אחר: \"בצדק תשפט עמיתך\"\u0004 — \u0003הוי דן את חבירך לכף זכות,\u0004 שתנסה למצוא לו ככל האפשר הצדקה כאשר אתה שופט אותו בליבך.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף\u0004 על פסוק זה: \u0003\"בצדק תשפט עמיתך\"\u0004 — \"עמיתך\" פירושו: \u0003עם\u0004 זה \u0003ש\u0004הוא \u0003אתך ב\u0004קיום \u0003תורה ובמצו‍ת, השתדל לדונו יפה,\u0004 כמבואר להלן.","מסופר, \u0003רב עולא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב עילאי הוה ליה דינא קמיה\u0004 \u0005[היה לו דין לפני]\u0006 \u0003רב נחמן, שלח ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף\u0004 מכתב לרב נחמן: \u0003עולא חברנו, עמית בתורה ובמצות\u0004 כלומר, שהוא אחד מאלה שאפשר לקרוא לו \"עמיתך\". \u0003אמר\u0004 רב נחמן: \u0003למאי\u0004 \u0005[למה]\u0006 \u0003שלח לי?\u0004 האם כדי \u0003לחנופי ליה\u0004 \u0005[להחניף לו]?\u0006 הרי דין צריך להיות דין אמת וצדק! \u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר:\u0004 לא לשם כך התכוון, אלא \u0003למישרא בתיגריה\u0004 \u0005[לפתוח בדינו]\u0006 שאם יבואו לפני דינים נוספים צריך להקדים את דינו מפני כבוד התורה."],["\u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יש טעם להודיע שהוא תלמיד חכם, \u0003ל\u0004ענין \u0003שודא דדייני\u0004 \u0005[השלכת הדיינים]\u0006 שפעמים אין בידם לפסוק על פי ראיות אלא לפי ראות עיניהם, והודיע לו רב יוסף שאדם זה ראוי שיחליטו לטובתו.","\u0003אמר עולא: מחלוקת\u0004 חכמים ור' יהודה אם חייבים לעמוד או לא, היא דווקא \u0003בבעלי דינין, אבל בעדים\u0004 — \u0003דברי הכל\u0004 עדותם צריכה להיות \u0003בעמידה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ועמדו שני האנשים\"\u0004 (דברים יט, יז). \u0003אמר רב הונא: מחלוקת\u0004 זו אם צריכים בעלי הדין לעמוד, היא דווקא \u0003בשעת משא ומתן, אבל בשעת גמר דין\u0004 — \u0003דברי הכל דיינין בישיבה ובעלי דינין בעמידה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישב משה לשפט את העם ויעמד העם\"\u0004 (שמות יח, יג). \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]\u0006 בדברי רב הונא: \u0003מחלוקת\u0004 — \u0003בשעת משא ומתן, אבל בשעת גמר דין\u0004 — \u0003דברי הכל\u0004 יהיו \u0003דיינין בישיבה ובעלי דינין בעמידה, דהא\u0004 \u0005[שהרי]\u0006 \u0003עדים כגמר דין דמו\u0004 \u0005[נחשבים],\u0006 שעדותם היא סיום הענין והכרעתו מבחינתם, \u0003וכתיב בהו\u0004 \u0005[ונאמר בהם]:\u0006 \u0003\"ועמדו שני האנשים\".\u0004","","מסופר, \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003רב הונא הוה\u0004 \u0005[היה]\u0006 \u0003לה דינא קמיה\u0004 \u0005[דין לפני]\u0006 \u0003רב נחמן, אמר: היכי נעביד\u0004 \u0005[כיצד נעשה]\u0006 בענין זה? \u0003אי איקום מקמה\u0004 \u0005[אם אעמוד לפניה]\u0006 משום כבודה כאשת תלמיד חכם, על ידי כך \u0003מסתתמן טענתיה דבעל דינא\u0004 \u0005[יסתתמו טענותיו של בעל הדין]\u0006 שאין הכל יודעים שצריך לחלוק לה כבוד משום שהיא אשת חכם, ויחשוב הצד השני שרב נחמן מעדיף אותה משום מה. ומן הצד האחר, אם \u0003לא איקום מקמה\u0004 \u0005[אעמוד לפניה],\u0006 הרי אמרו ש\u0003אשת חבר הרי היא כחבר,\u0004 וכבוד התורה הוא! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן \u0003לשמעיה\u0004 \u0005[לשמשו]:\u0006 \u0003צא ואפרח\u0004 \u0005[והפרח]\u0006 \u0003עלי בר אווזא\u0004 \u0005[ברווז]\u0006 \u0003ושדי עלוואי, ואיקום\u0004 \u0005[וזרוק אותו לעברי, ואעמוד],\u0006 כביכול בגלל הברווז, שאז אקיים את מצות העמידה, אבל לא ייראה הדבר כך.","ושואלים: ומה מועילה עצה זו? \u0003והאמר מר\u0004 \u0005[והרי אמר החכם,\u0006 רב הונא\u0005]:\u0006 \u0003מחלוקת\u0004 ר' יהודה וחכמים היא \u0003בשעת משא ומתן, אבל בשעת גמר דין\u0004 — \u0003דברי הכל דיינים בישיבה ובעלי דינין בעמידה!\u0004 ומשיבים: ניתן לקיים דבר זה באופן \u0003דיתיב כמאן דשרי מסאניה\u0004 \u0005[\u0006שהדיין \u0005יושב כמי שמתיר\u0006 את \u0005מנעלו]\u0006 שאין זו ישיבה גמורה אלא מעין חצי עמידה, \u0003ואמר\u0004 \u0005[ואומר]\u0006 את דינו: \u0003איש פלוני אתה זכאי, איש פלוני אתה חייב.\u0004","\u0003אמר רבה בר רב הונא: האי צורבא מרבנן\u0004 \u0005[תלמיד חכם]\u0006 \u0003ועם הארץ דאית להו דינא בהדי הדדי\u0004 \u0005[שיש להם דין זה עם זה],\u0006 \u0003מותבינן ליה לצורבא מרבנן\u0004 \u0005[מושיבים אנו אותו את התלמיד חכם],\u0006 \u0003ולעם הארץ נמי אמרינן ליה: \"תיב\"\u0004 \u0005[גם כן אומרים אנו לו: \"שב\"],\u0006 \u0003ואי קאי\u0004 \u0005[ואם\u0006 הוא \u0005עומד],\u0006 מחמת כבוד או בושה, \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 ואין אנו צריכים להקפיד על כך.","מסופר, \u0003רב בר שרביא הוה ליה דינא קמיה\u0004 \u0005[היה לו דין לפני]\u0006 \u0003רב פפא, אותביה ואותיב נמי לבעל דיניה\u0004 \u0005[הושיבו והושיב גם כן את בעל דינו],\u0006 \u0003אתא שליחא דבי דינא בטש ביה ואוקמיה\u0004 \u0005[בא שליח בית הדין בעט בו והקימו]\u0006 את \u0003עם הארץ,\u0004 שהוא יושב במקום גדולים, \u0003ולא אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא: \"תיב\"\u0004 \u0005[שב].\u0006 ושואלים: \u0003היכי עביד הכי\u0004 \u0005[כיצד עשה כך]\u0006 רב פפא? \u0003והא\u0004 \u0005[והרי]\u0006 בכך \u0003מסתתמן טענתיה\u0004 \u0005[מסתתמות טענותיו]\u0006 של אותו האיש כשרואה שמעדיפים את בעל דינו! ומשיבים: במקרה זה \u0003אמר רב פפא\u0004 לעצמו, \u0003מימר אמר\u0004 \u0005[אומר הוא\u0006 אותו בעל דין \u0005בליבו]:\u0006 \u0003איהו הא אותבן\u0004 \u0005[הוא\u0006 הדיין \u0005הרי הושיב אותי],\u0006 \u0003שליחא\u0004 \u0005[השליח]\u0006 \u0003הוא\u0004 זה \u0003דלא מפייס מינאי\u0004 \u0005[שאינו מרוצה ממני]\u0006 ומציק לי, ואין הוא סבור שהדבר נוגע לדיין.","\u0003ואמר רבה בר רב הונא: האי צורבא מרבנן\u0004 \u0005[תלמיד חכם]\u0006 \u0003ועם הארץ דאית להו דינא בהדי הדדי\u0004 \u0005[שיש להם דין זה עם זה],\u0006 \u0003לא ליקדום צורבא מרבנן וליתיב\u0004 \u0005[שלא יקדים התלמיד חכם וישב\u0006 לפני הדיין ללמוד\u0005],\u0006 \u0003משום דמיחזי כמאן דסדר ליה לדיניה\u0004 \u0005[שנראה\u0006 הדבר \u0005כמי שמסדר את דינו,\u0006 טענותיו, לפניו] ואסור הדבר. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 בתלמיד \u0003דלא קביע ליה עידניה\u0004 \u0005[שלא קבוע לו זמנו]\u0006 לבוא ללמוד לפני חכם זה באותה שעה, \u0003אבל\u0004 כאשר \u0003קביע ליה עידניה לית לן בה\u0004 \u0005[קבוע לו זמנו אין לנו בה],\u0006 לפי שאז \u0003מימר אמר\u0004 \u0005[אומר\u0006 הצד השני\u0005]:\u0006 \u0003בעידניה טריד\u0004 \u0005[בזמנו,\u0006 בלימודו הוא \u0005עסוק]\u0006 ולכן הוא יושב לפניו. \u0003ואמר רבה בר רב הונא: האי צורבא מרבנן דידע בסהדותא\u0004 \u0005[תלמיד חכם היודע בעדות\u0006 לאדם מסויים\u0005],\u0006 \u0003וזילא ביה מילתא למיזל לבי דיינא דזוטר מיניה לאסהודי קמיה\u0004 \u0005[ומזולזל בו הדבר ללכת לבית דין של דיין קטן ממנו להעיד לפניו],\u0006 \u0003לא ליזיל\u0004 \u0005[שלא ילך].\u0006 \u0003אמר רב שישא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 ראיה לדבר שמפני כבודו של חכם יכול הוא להימנע ממצוה, ששנינו: \u0003מצא\u0004 אדם \u0003שק או קופה\u0004 בדרך, \u0003ואין דרכו ליטול\u0004 לטלטל דברים כאלה — \u0003הרי זה לא יטול\u0004 כדי להשיבו לבעליו. משמע שמפני כבוד תלמיד חכם מבטלים מצות השבת אבידה שמן התורה.","","ומעירים: \u0003הני מילי בממונא\u0004 \u0005[דברים אלה\u0006 אמורים \u0005ב\u0006עדות ובשאר עניינים של \u0005ממון],\u0006 \u0003אבל באיסורא\u0004 \u0005[ב\u0006דבר \u0005איסור]\u0006 אין חוששים לכבוד החכם, שהכלל הוא: \u0003\"אין חכמה ואין תבונה ואין עצה לנגד ה' \"\u0004(משלי כא, ל), לומר: \u0003כל מקום שיש בו חלול ה'\u0004 — \u0003אין חולקין כבוד לרב,\u0004 וצריך החכם למחול על כבודו כדי שלא ייגרם על ידי כך איסור, שהוא חילול השם.","מסופר, \u0003רב יימר הוה ידע ליה סהדותא\u0004 \u0005[היה יודע לו עדות]\u0006 \u0003למר זוטרא, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003אמימר, אותבינהו לכולהו\u0004 \u0005[הושיב את כולם]\u0006 את כל העדים, מפני כבודו של רב יימר. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אשי לאמימר, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003עולא: מחלוקת\u0004 — \u0003בבעלי דינין, אבל בעדים\u0004 — \u0003דברי הכל\u0004 שמעידים \u0003בעמידה! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003האי\u0004 \u0005[זו]\u0006 מצות \u0003עשה\u0004 שיעמדו העדים, \u0003והאי\u0004 \u0005[וזו]\u0006 מצות \u0003עשה\u0004 על כבוד התורה להושיב את רב יימר, \u0003עשה\u0004 של \u0003כבוד תורה עדיף,\u0004 ולכן אני מושיב אותו, וכדי שלא לעוות את הדין, אני צריך להושיב את כולם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין לדיין שלא יעשה סניגרון\u0004 (סניגור) \u0003לדבריו?\u0004 כלומר, שלא יצדיק את הדברים המוטעים שאמר בכל מיני תואנות? \u0003תלמוד לומר: \"מדבר שקר תרחק\"\u0004 (שמות כג, ז). \u0003ומנין לדיין שלא ישב תלמיד בור לפניו? תלמוד לומר: \"מדבר שקר תרחק\",\u0004 וכשיושב תלמיד כזה לפניו יכול לגרום לדיין לטעות.","","","ועוד, \u0003מנין לדיין שיודע לחבירו\u0004 הדיין שיושב עמו בדין \u0003שהוא גזלן\u0004 ופסול לדין, \u0003וכן עד שיודע בחבירו שהוא גזלן\u0004 ופסול לעדות, \u0003מנין שלא יצטרף עמו? תלמוד לומר: \"מדבר שקר תרחק\".\u0004 \u0003מנין לדיין שיודע בדין שהוא מרומה,\u0004 שהוא מרגיש שדברי העדים הם שקר, אף שאינו יכול להוכיח זאת בחקירה ודרישה, \u0003שלא יאמר: הואיל והעדים מעידין\u0004 את הדין, ואין אני יכול להוכיח את שקרם, \u0003אחתכנו\u0004 כפי העדות, \u0003ויהא\u0004",""],["\u0003קולר\u0004 (שלשלת של צוואר הנידונים, כלומר העבירה) \u0003תלוי בצואר עדים\u0004 שהם שיקרו? \u0003תלמוד לומר: \"מדבר שקר תרחק\".\u0004 (שמות כג, ז).","\u0003(סימן\u0004 לדברים הנלמדים להלן מן הפסוק \"מדבר שקר תרחק\": \u0003תלת\"א\u0004 \u0005[שלושה]\u0006 בענין \u0003תלמי\"ד, ותל\"ת\u0004 \u0005[ושלושה]\u0006 בענין \u0003בעל\"י חו\"ב,\u0004 ועוד שלושה לדיין: \u0003סמרטו\"ט שומ\"ע ומטעי\"ם).\u0004","\u0003מנין לתלמיד שיושב לפני רבו ורואה זכות לעני וחוב לעשיר, מנין שלא ישתוק? תלמוד לומר: \"מדבר שקר תרחק\".\u0004","ועוד, \u0003מנין לתלמיד שרואה את רבו שטועה בדין, שלא יאמר: אמתין לו\u0004 לרבי \u0003עד שיגמרנו\u0004 את הדין, \u0003ו\u0004אז \u0003אסתרנו ואבננו משלי\u0004 כראוי, \u0003כדי שיקרא הדין על שמי? תלמוד לומר: \"מדבר שקר תרחק\".\u0004","ועוד, \u0003מנין לתלמיד שאמר לו רבו: יודע\u0004 \u0003אתה בי\u0004 (מכיר אתה אותי) \u0003שאם נותנין לי\u0004 אפילו \u0003מאה מנה איני מבדה\u0004 (משקר), אולם חוב של \u0003מנה\u0004 (מאה דינרים) \u0003יש לי אצל פלוני\u0004 שנתתים לו בהלוואה \u0003ואין לי עליו אלא עד אחד\u0004 שיעיד על כך, ונדרשת עדות שני עדים כדי להוציא את החוב מידו, \u0003מנין שלא יצטרף\u0004 התלמיד להעיד \u0003עמו\u0004 עם אותו עד? \u0003תלמוד לומר: \"מדבר שקר תרחק\".\u0004","ושואלים: \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 מהאיסור \u0003\"מדבר שקר תרחק\" נפקא\u0004 \u0005[\u0006הוא \u0005יוצא]?\u0006 שיש בזה רק משום התרחקות מן השקר? \u0003הא\u0004 \u0005[הרי\u0006 כאן\u0005]\u0006 \u0003ודאי שקורי קא משקר\u0004 \u0005[משקר הוא],\u0006 \u0003ורחמנא אמר\u0004 \u0005[והתורה אומרת]\u0006 במפורש: \u0003\"לא תענה ברעך עד שקר\"\u0004 (שמות כ, ג), ויש בזה איסור חמור מן התורה! \u0003אלא כגון דאמר ליה\u0004 \u0005[שאומר לו]\u0006 רבו: \u0003ודאי חד סהדא אית\u0004 \u0005[עד אחד יש]\u0006 \u0003לי, ותא\u0004 \u0005[ובוא]\u0006 \u0003אתה קום התם\u0004 \u0005[עמוד שם]\u0006 ליד העד \u0003ולא תימא ולא מידי\u0004 \u0005[תאמר דבר],\u0006 \u0003דהא לא מפקת מפומך שקרא\u0004 \u0005[שהרי אינך מוציא מפיך שקר],\u0006 ואילו הצד השני יחשוב שיש שני עדים בדבר ויודה — \u0003אפילו הכי\u0004 \u0005[כך]\u0006 \u0003אסור, משום שנאמר: \"מדבר שקר תרחק\".\u0004 ועוד דברים הנוגעים בענין זה לבעל חוב.","\u0003מנין לנושה בחבירו מנה\u0004 ואין לו עדים, \u0003שלא יאמר: אטעננו\u0004 מתחילה \u0003במאתים\u0004 דינרים \u0003כדי שיודה לי במנה ויתחייב לי שבועה\u0004 של מודה במקצת, \u0003ו\u0004אגב אותה שבועה \u0003אגלגל עליו שבועה\u0004 על חוב אחר שהוא חייב לי \u0003ממקום אחר? תלמוד לומר: \"מדבר שקר תרחק\".\u0004","ועוד, \u0003מנין לנושה בחבירו מנה וטענו מאתים, שלא יאמר\u0004 החייב: \u0003אכפרנו בבית דין\u0004 ואומר שאינני חייב בכלל, \u0003ואודה לו חוץ לבית דין, כדי שלא אתחייב לו שבועה ולא יגלגל עלי שבועה ממקום אחר? תלמוד לומר: \"מדבר שקר תרחק\".\u0004","ועוד, \u0003מנין לשלשה שנושין\u0004 (תובעים) יחד \u0003מנה באחד, שלא יהא אחד\u0004 מהם נעשה \u0003בעל דין\u0004 כתובע, \u0003ושנים\u0004 יהיו \u0003עדים, כדי ש\u0004לבסוף \u0003יוציאו\u0004 אותו \u0003מנה\u0004 מן החייב \u0003ויחלוקו? תלמוד לומר: \"מדבר שקר תרחק\".\u0004 ומביאים דברים נוספים הנלמדים מפסוק זה לדיין.","\u0003מנין לשנים שבאו לדין, אחד לבוש סמרטוטין ואחד לבוש איצטלית\u0004 (כסות, מעיל) \u0003בת\u0004 (ששווה) \u0003מאה מנה, שאומרין לו\u0004 לעשיר: \u0003לבוש כמותו או הלבישהו כמותך? תלמוד לומר: \"מדבר שקר תרחק\".\u0004 ומסופר, \u0003כי הוו אתו לקמיה\u0004 \u0005[כאשר היו באים\u0006 לדין אנשים שונים \u0005לפני]\u0006 \u0003רבא בר רב הונא, אמר להו\u0004 \u0005[היה אומר להם]:\u0006 \u0003שלופו פוזמוקייכו וחותו לדינא\u0004 \u0005[הורידו\u0006 את \u0005הנעלים היפות שלכם ובואו לדין],\u0006 שלא תיראו מכובדים יותר.","ועוד, \u0003מנין לדיין שלא ישמע דברי בעל דין קודם שיבא בעל דין חבירו? תלמוד לומר: \"מדבר שקר תרחק\".\u0004","ועוד, \u0003מנין לבעל דין שלא יטעים\u0004 (יסביר ויתן הוכחה) את \u0003דבריו לדיין קודם שיבא בעל דין חבירו? תלמוד לומר: \"מדבר שקר תרחק\". רב כהנא מתני\u0004 \u0005[היה שונה]\u0006 ולומד זאת \u0003מ\u0004מה שנאמר \u0003\"לא תשיא\u0004 שמע שוא\" (שמות כג, א), והוא מפרש אותו כאילו היה נאמר \u0003\"לא תשיא\"\u0004 כלומר, אל תגרום לאדם לקבל דבר שקר.","נאמר \u0003\"ואשר לא טוב עשה בתוך עמיו\"\u0004 (יחזקאל יח, יח) — \u0003רב אמר: זה הבא בהרשאה,\u0004 שנעשה שליח לחבירו בבית הדין לטעון עבורו. \u0003ושמואל אמר: זה הלוקח שדה שיש עליה עסיקין\u0004 (עוררין), שהוא נכנס לסכסוכים אף על פי שהוא לא גרם אותם.","שנינו ששבועת העדות \u0003אינה נוהגת אלא בראוין להעיד.\u0004 ושואלים: \u0003לאפוקי מאי\u0004 \u0005[להוציא\u0006 את \u0005מה]\u0006 בנוסף לכל האמורים לעיל? שהרי כבר מנה את הפסולים לעדות מכל הסוגים! \u0003אמר רב פפא: לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מלך,\u0004 שאף שאינו לא קרוב ולא פסול, מכל מקום אינו מעיד בבית דין. \u0003ורב אחא בר יעקב אמר: לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003משחק בקוביא,\u0004 שהוא פסול לעדות מדברי סופרים.","ומעירים: \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 כי אינה נוהגת ב\u0003משחק בקוביא, כל שכן\u0004 ב\u0003מלך,\u0004 שמן התורה איננו מעיד. \u0003ומאן דאמר\u0004 \u0005[ומי שאומר]\u0006 שאינה נוהגת ב\u0003מלך, אבל משחק בקוביא\u0004 אפשר לומר שנוהגת בו, לפי ש\u0003מדאורייתא מחזא חזי\u0004 \u0005[מן התורה ראוי\u0006 הוא\u0005],\u0006 \u0003ורבנן הוא\u0004 \u0005[וחכמים הם]\u0006 ש\u0003פסלוהו,\u0004 ולכן שבועת העדות שמן התורה חלה עליו.","שנינו במשנתנו ששבועת העדות נוהגת \u0003בפני בית דין ושלא בפני בית דין\u0004 אם נשבע העד מעצמו. ומפי אחרים — דווקא בבית דין, דברי ר' מאיר. וחכמים אומרים שבכל מקרה חייבים רק כאשר כופרים בפני בית דין. ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה הם חלוקים]?\u0006 מהו יסוד המחלוקת?","\u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים לפני]\u0006 \u0003רב פפא\u0004 שנחלקו בשאלה של דרכי הלימוד בגזירה שווה: האם הולכים בשאלה \u0003ב\u0004דרך של \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה]\u0006 כלומר, כשלומדים דבר מדבר האם חוזרים ולמדים דברים נוספים מאותו מקור באמצעות גזירה שווה זו, או האם הולכים \u0003ב\u0004דרך של \u0003דון מינה ואוקי באתרה\u0004 \u0005[למד ממנה והעמידה במקומה]\u0006 שלומדים בגזירה שווה רק דבר אחד, ובשאר הפרטים ממשיכים לדון בדבר לפי עניינו, בזה \u0003קא מיפלגי\u0004 \u0005[הם חלוקים],\u0006","\u0003ר' מאיר סבר: דון\u0004 \u0003מינה ומינה\u0004 \u0005[למד ממנה וממנה],\u0006 שהוא לומד בגזירה שווה דין שבועת עדות \u0003מ\u0004דין שבועת \u0003פקדון, מה\u0004 בשבועת \u0003פקדון מושבע מפי עצמו\u0004 — \u0003חייב, אף\u0004 שבועת \u0003עדות מושבע מפי עצמו\u0004 — \u0003חייב, ומינה\u0004 \u0005[וממנה]\u0006 הוא ממשיך ללמוד עוד, \u0003מה\u0004 שבועת \u0003פקדון\u0004 חייב עליה \u0003בין\u0004 כשנשבע על כך \u0003בבית דין ובין שלא בבית דין, אף\u0004 שבועת \u0003עדות\u0004 חייב \u0003בין בבית דין ובין שלא בבית דין. ו\u0004אילו","\u0003רבנן סברי\u0004 \u0005[חכמים סבורים]:\u0006 \u0003דון מינה ואוקי באתרה\u0004 \u0005[למד ממנה והעמידנה במקומה],\u0006 שאכן הם למדים: \u0003מה פקדון מושבע מפי עצמו\u0004 — \u0003חייב, אף עדות מושבע מפי עצמו\u0004 — \u0003חייב, ו\u0004אולם \u0003אוקי באתרה\u0004 \u0005[העמידנה במקומה],\u0006 ולמד משבועת העדות עצמה על שבועת העדות, \u0003מה מושבע מפי אחרים,\u0004 אם כפר \u0003בבית דין\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חייב, \u0003שלא בבית דין\u0004 — \u0003לא,\u0004 כמבואר להלן, \u0003אף מושבע מפי עצמו\u0004 בהשבעה זו, \u0003בבית דין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא בבית דין\u0004 — \u0003לא.\u0004"],["\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב פפא\u0004 לחכמים: \u0003אי\u0004 \u0005[אם]\u0006 \u0003מפקדון גמרי לה רבנן\u0004 \u0005[לומדים אותה חכמים]\u0006 בגזירה שווה, \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל אינם חולקים]\u0006 שהולכים בשיטה של \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה]\u0006 והיינו צריכים ללמוד מכל דיני הפקדון, ובכלל זה שנשבע מעצמו חוץ לבית דין — חייב.","\u0003אלא היינו טעמא דרבנן\u0004 \u0005[זהו הטעם של חכמים]\u0006 שאינם סבורים כן, \u0003דמייתו לה\u0004 \u0005[שמביאים אותה],\u0006 את הסברה שחייב אם נשבע מעצמו, \u0003בקל וחומר\u0004 מדין שבועת עדות עצמה. והסברה היא: \u0003ומה\u0004 מושבע \u0003מפי אחרים —\u0004 \u0003חייב, מפי עצמו לא כל שכן?\u0004","\u0003ומדמייתו לה\u0004 \u0005[וכיון שמביאים אותה]\u0006 רק בדרך \u0003קל וחומר,\u0004 הרי כלל הוא בדיני קל וחומר: \u0003דיו לבא מן הדין להיות כנדון,\u0004 שאין הנלמד בקל וחומר יכול להיות יותר מן המלמד. ולכן, \u0003מה מושבע מפי אחרים, בבית דין\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חייב, \u0003שלא בבית דין\u0004 — \u0003לא, אף מושבע מפי עצמו, בפני בית דין\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003שלא בפני בית דין\u0004 — \u0003לא.\u0004","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרב פפא: מי מצית אמרת\u0004 \u0005[האם יכול אתה לומר]\u0006 \u0003דלאו\u0004 \u0005[שלא]\u0006 \u0003ב\u0004ענין של \u0003דון מינה ומינה\u0004 \u0005[למד ממנה וממנה]\u0006 הם \u0003פליגי\u0004 \u0005[חולקים]?\u0006 \u0003והתנן גבי\u0004 \u0005[והרי שנינו\u0006 במשנה \u0005אצל]\u0006 שבועת ה\u0003פקדון\u0004 כך: \u0003שבועת הפקדון נוהגת באנשים ובנשים, ברחוקין ובקרובין, בכשרין ובפסולין, בפני בית דין ושלא בפני בית דין\u0004 — \u0003מפי עצמו, ומפי אחרים אינו חייב עד שיכפור בו בבית דין, דברי ר' מאיר. וחכמים אומרים: בין מפי עצמו ובין מפי אחרים\u0004 — \u0003כיון שכפר בו חייב.\u0004","ויש לשאול: \u0003מושבע מפי אחרים בפקדון מנא להו לרבנן\u0004 \u0005[מנין להם לחכמים]\u0006 שהוא \u0003חייב?\u0004 שהרי לא נאמר דבר זה בתורה בשבועת הפקדון, \u0003לאו דגמרי לה\u0004 \u0005[האם לא\u0006 מפני \u0005שלומדים זאת]\u0006 \u0003מ\u0004שבועת \u0003עדות? ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 שבשאלה האם \u0003בדון מינה ומינה פליגי\u0004 \u0005[לומדים ממנה וממנה חלוקים\u0006 הם\u0005],\u0006 שלדעת חכמים ש\"אוקי באתרה\" למדים רק שחייב גם מפי אחרים, אבל אין להמשיך וללמוד מעדות שחייב רק כשכפר בבית דין, אלא כדין שבועת הפקדון עצמה — גם מחוץ לבית דין.","אמר להם רב פפא: \u0003מההיא\u0004 — \u0003אין\u0004 \u0005[מאותה\u0006 ברייתא — \u0005כן],\u0006 שמשם אפשר לראות שהם חולקים בנושא זה, אולם \u0003מהא\u0004 — \u0003ליכא למשמע מינה\u0004 \u0005[מזו\u0006 ממשנתנו, שממנה רציתם להוכיח — \u0005אי אפשר לשמוע ממנה]\u0006 ואין להביא ממנה ראיה זו לענין זה.","שנינו במשנה: \u0003וחייבין על זדון השבועה.\u0004 ושואלים: \u0003מנהני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שבשבועת העדות חייבים על הזדון? \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]:\u0006 \u0003בכולן\u0004 בשאר הדינים המוזכרים בפרשת קרבן עולה ויורד (טומאת מקדש וקדשיו ושבועת ביטוי) \u0003נאמר בהן \"ונעלם\"\u0004 (ראה ויקרא ה, ב— ד), \u0003וכאן\u0004 בשבועת העדות \u0003לא נאמר בה \"ונעלם\",\u0004 משמע שבא הכתוב ללמדנו, שחייב גם אם לא נעלם ממנו, ומכאן יש \u0003לחייב על המזיד כשוגג.\u0004","ועוד שנינו במשנה: \u0003ו\u0004חייבים \u0003על שגגתה עם זדון העדות.\u0004 ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003שגגתה עם זדון העדות? אמר רב יהודה אמר רב, באומר: יודע אני ששבועה זו,\u0004 שאדם נשבע לשקר שאינו יודע עדות לחבירו, \u0003אסורה, אבל איני יודע אם חייבין עליה קרבן אם לא.\u0004","ועוד שנינו במשנה: \u0003ואין חייבין על שגגתה גרידתא\u0004 כלומר, שאם טעה האיש באמת, ששכח שהוא יודע את העדות — פטור מלהביא קרבן. ושואלים: \u0003לימא תנינא\u0004 \u0005[האם לומר ששנינו]\u0006 כבר במשנה את זו של \u0003רב כהנא ו\u0004של \u0003רב אסי\u0004 (לעיל שבועות כו,א) שהיו חולקים זה עם זה ונשבעים על מה שאמר רב, ואמר רב שמי שטעה ונשבע על כך — אין זה נחשב לשבועת שקר, משום שבשעת שבועה היה בטוח שהוא אומר אמת, ואין זו שגגה, אלא אונס?","ודוחים: \u0003לא, אף על גב דתנן איצטריך\u0004 \u0005[אף על פי ששנינו את הדבר\u0006 במשנה זו, \u0005הוצרך]\u0006 רב לומר להם לענין מה שנשבעו, שכן אם רק לפי משנה זו \u0003סלקא דעתך\u0004 \u0003אמינא\u0004 \u0005[היה עולה על דעתך לומר]:\u0006 \u0003הכא\u0004 \u0005[כאן]\u0006 \u0003הוא\u0004 בשבועת העדות הדין כן, משום ש\u0003לא כתיב\u0004 \u0005[נאמר]\u0006 בה \u0003\"ונעלם\", דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שיהיה ה\u0003שוגג\u0004 שמביאים עליו קרבן \u0003דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003מזיד,\u0004 שיודע שהוא נשבע לשקר (אלא שלא ידע שחייב על כך קרבן) ואם אין זה זדון גמור הריהו פטור. \u0003אבל התם\u0004 \u0005[שם]\u0006 במקרה של רב כהנא ורב אסי, שמדובר בשבועת הביטוי \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בה \u0003\"ונעלם\"\u0004 (ויקרא ה, ד) — היינו אומרים כי \u0003אפילו שגגתה כל דהו\u0004 \u0005[שהוא],\u0006 גם אם התכוונו להישבע באמת, ונעלם מהם הדבר לגמרי, נחשב הדבר כשגגה לחייב קרבן, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שאפילו בשבועת הביטוי שגגה כגון זו נחשבת כאונס, ופטור.","\u0003שבועת העדות\u0004 שמביא עליה קרבן עולה ויורד \u0003כיצד? אמר לשנים: \"בואו והעידוני\",\u0004 ואמרו לו: \u0003\"שבועה שאין אנו יודעין לך עדות\". או שאמרו לו: \"אין אנו יודעין לך עדות\",\u0004 ואמר להם: \u0003\"משביע אני עליכם\", ואמרו: \"אמן\",\u0004 והתברר שהיה זה שקר — \u0003הרי אלו חייבין.\u0004","\u0003השביע עליהם חמש פעמים חוץ לבית דין, ובאו לבית דין והודו\u0004 כלומר, העידו כראוי — הרי הם \u0003פטורין;\u0004 אבל אם \u0003כפרו\u0004 גם בבית דין — \u0003חייבין על כל אחת ואחת\u0004 מהפעמים שהשביע עליהם מחוץ לבית דין. \u0003השביע עליהן חמש פעמים בפני בית דין וכפרו\u0004 — \u0003אינן חייבין אלא אחת. אמר ר' שמעון: מה טעם\u0004 הדבר? \u0003הואיל ואינם יכולין לחזור ולהודות\u0004 לאחר שאמרו בפני בית דין שאינם יודעים עדות, נמצא שהיתה כאן רק שבועת שקר אחת, ועל השאר פטורים.","\u0003כפרו\u0004 העדים \u0003שניהן כאחד\u0004 — \u0003שניהן חייבין,\u0004 אם כפרו \u0003בזה אחר זה, הראשון\u0004 שכפר — \u0003חייב, והשני\u0004 — \u0003פטור,\u0004 שכיון שהראשון אינו מעיד נשאר רק עד אחד בלבד, ועד יחיד אינו ראוי להעיד. \u0003כפר אחד\u0004 מן העדים, \u0003והודה אחד\u0004 והעיד — \u0003הכופר\u0004 בעדות \u0003חייב.\u0004","\u0003היו שתי כיתי עדים\u0004 שנשבעו שבועת העדות, \u0003כפרה הראשונה ואחר כך כפרה השניה\u0004 — \u0003שתיהן חייבות, מפני שהעדות יכולה להתקיים בשתיהן,\u0004 שביטול העדות של כת ראשונה עדיין משאיר אפשרות לכת שניה להעיד עדות גמורה.","\u0003אמר שמואל: ראוהו\u0004 העדים לבעל הדין \u0003שרץ אחריהן, אמרו לו: \"מה אתה רץ אחרינו? שבועה שאין אנו יודעין לך עדות\"\u0004 — הרי אלו \u0003פטורין, עד שישמעו מפיו\u0004 תביעה להעיד. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 שמואל? הלוא \u0003תנינא\u0004 \u0005[שנינו]\u0006 את הדבר הזה: \u0003שילח\u0004 התובע \u0003ביד עבדו, או שאמר להן הנתבע\u0004 ולא התובע: \u0003\"משביע אני עליכם שאם אתם יודעין לו עדות שתבואו ותעידוהו\"\u0004 ונשבעו שבועת שקר שאינם יודעים — \u0003הרי אלו פטורים,\u0004"],["\u0003עד שישמעו מפי התובע!\u0004","ומשיבים: \u0003רץ אחריהן איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[\u0006היה \u0005עולה על דעתך לומר]:\u0006 \u0003כיון\u0004 ש\u0003רץ אחריהן כמאן דאמר להו דמי\u0004 \u0005[כמי שאומר להם\u0006 להעיד \u0005נחשב\u0006 הדבר\u0005],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שמואל שאף שמובנת כוונתו — אין חייבים עד שיאמר להם בפירוש.","ומקשים: \u0003והא נמי תנינא\u0004 \u0005[והרי גם זו שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003שבועת העדות כיצד? אמר לעדים בואו והעידוני, שבועה כו'.\u0004 ונדייק מכאן: \u0003אמר\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא אמר\u0004 — \u0003לא!\u0004","ודוחים: מכאן אי אפשר להוכיח, שאפשר לומר כי \u0003\"אמר\" לאו דוקא\u0004 \u0005[איננו מדוקדק],\u0006 והוא הדין כשלא אמר.","\u0003דאי לא תימא הכי\u0004 \u0005[שאם לא תאמר כך],\u0006 אלא שהלשון מדוייקת, \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003פקדון דקתני\u0004 \u0005[ששנה]\u0006 שם: \u0003שבועת הפקדון כיצד? אמר לו: \"תן לי פקדון שיש לי בידך\", הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר שאם \u0003אמר\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא אמר\u0004 — \u0003לא? הא\u0004 \u0005[הרי]\u0006 \u0003\"וכחש בעמיתו\"\u0004 (ויקרא ה, כא) \u0003כל דהו\u0004 \u0005[שהוא]\u0006 משמע, בכל אופן שהוא מכחש!","\u0003אלא\u0004 חייב אתה לומר ש\u0003\"אמר\"\u0004 לגבי שבועת הפקדון \u0003לאו דוקא\u0004 \u0005[אינו מדוייק],\u0006 \u0003הכא נמי לאו דוקא\u0004 \u0005[כאן גם כן,\u0006 בשבועת העדות, \u0005אינו מדוייק].\u0006","את ההוכחה הזו דוחים: \u0003האי מאי\u0004 \u0005[\u0006דבר \u0005זה מהו]?\u0006 \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 ש\u0003\"אמר\" דהכא דוקא\u0004 \u0005[של כאן\u0006 הוא \u0005מדוייק],\u0006 \u0003תנא התם אטו הכא\u0004 \u0005[שנה שם\u0006 בפקדון \"אמר\" \u0005משום כאן],\u0006 שהמשניות מדברות באותו סגנון, אף על פי ששם אין זו לשון מחוייבת. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003לא\u0004 הביטוי \u0003\"אמר\" דהתם דוקא\u0004 \u0005[של שם\u0006 הוא \u0005מדוייק]\u0006 \u0003ולא \"אמר\" דהכא דוקא\u0004 \u0005[של כאן מדוייק],\u0006 אם כן, \u0003\"אמר\" \"אמר\" למה לי למיתנייה\u0004 \u0005[לו לשנותו]?\u0006","ודוחים: \u0003דלמא אורחא דמילתא קא משמע לן\u0004 \u0005[שמא הדרך הרגילה משמיע לנו],\u0006 שבדרך כלל התובע אומר, אבל אין זה אומר שבלי זה לא יתחייב העד. וכיון שאין הדבר מוכח מן המשנה, היה חידוש בדברי שמואל.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003שמואל\u0004 לגבי שבועת העדות: \u0003ראוהו\u0004 העדים \u0003שבא\u0004 התובע \u0003אחריהן, אמרו לו: \"מה אתה בא אחרינו? שבועה שאין אנו יודעין לך עדות\"\u0004 — \u0003פטורין, ואם\u0004 היה זה \u0003בפקדון\u0004 — שהתובע רץ אחריהם והם מעצמם הכחישו — \u0003חייבים,\u0004 כפי שאמרנו, שעל שבועת פקדון חייבים בכל דרך.","שנינו במשנה: \u0003השביע עליהן חמשה פעמים\u0004 חוץ לבית דין והודו בבית דין — פטורים. ואם כפרו בבית דין — חייבים על כל שבועה \u0003כו'.\u0004","ושואלים: \u0003מנלן\u0004 \u0005[מנין לנו]\u0006 שעל ה\u0003כפירה בבית דין\u0004 דווקא \u0003הוא דמחייבי\u0004 \u0005[ש\u0006הם \u0005מתחייבים],\u0006 ועל הכפירה מ\u0003חוץ לבית דין לא מחייבי\u0004 \u0005[אינם מתחייבים]?\u0006","\u0003אמר אביי, אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין זה: \u0003\"אם לא יגיד ונשא עונו\"\u0004 (ויקרא ה א), לומר: \u0003לא אמרתי לך אלא במקום שאילו מגיד זה\u0004 העד, היה \u0003מתחייב זה ממון\u0004 כלומר, בבית דין. אבל לא במקום שההגדה אין לה ערך.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: אי הכי\u0004 \u0005[אם כך],\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 שדווקא אם ה\u0003שבועה גופא\u0004 \u0005[עצמה]\u0006 היתה \u0003בבית דין\u0004 — \u0003אין\u0004 \u0005[כן]\u0006 חייב, \u0003ושלא בבית דין\u0004 — \u0003לא!\u0004","ודחה אביי, \u0003לא סלקא דעתך\u0004 \u0005[לא יעלה על דעתך]\u0006 לומר כך, \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 נאמר \"והיה כי יאשם \u0003לאחת\u0004 מאלה\" (ויקרא ה, ה) — \u0003לחייב\u0004 קרבן \u0003על כל אחת ואחת\u0004 כשעבר יותר מפעם אחת על העבירות בפרשת קרבן עולה ויורד. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך\u0006 לומר\u0005]\u0006 שצריך להישבע \u0003בבית דין, מי מחייב\u0004 \u0005[האם חייב\u0006 הוא\u0005]\u0006 \u0003על כל אחת ואחת? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003השביע עליהן חמשה פעמים בפני בית דין וכפרו\u0004 — \u0003אין חייבין אלא אחת, אמר ר' שמעון: מה טעם? הואיל ואינם יכולין לחזור ולהודות\u0004 אחרי שכפרו! \u0003אלא לאו שמע מינה\u0004 \u0005[האם לא תשמע מכאן]\u0006 ש\u0003שבועה\u0004 היא גם \u0003חוץ לבית דין,\u0004 ובמקרה זה מתחייב על כל אחת ואחת, אבל \u0003כפירה\u0004 שמתחייב עליה היא \u0003בבית דין\u0004 דווקא.","שנינו במשנה: \u0003כפרו שניהן כאחת\u0004 — \u0003חייבין.\u0004 ושואלים: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אי אפשר לצמצם,\u0004 אי אפשר שיקרו שני דברים ממש בבת אחת, ואם כן בהכרח קדם אחד לחבירו!","\u0003אמר רב חסדא: הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 כשיטת \u0003ר' יוסי הגלילי היא,\u0004 ש\u0003אמר\u0004 בכלל ש\u0003אפשר לצמצם,\u0004 וייתכן שיקרו שני דברים בבת אחת.","\u0003ר' יוחנן אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 החולקים עליו, יש לומר שמדובר \u0003כגון שכפרו שניהן בתוך כדי דיבור, ותוך כדי דיבור כדיבור דמי\u0004 \u0005[נחשב],\u0006","שאף שאינו ממש בבת אחת, הרי הוא נחשב כבת אחת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: מכדי\u0004 \u0005[הרי]\u0006 \u0003תוך כדי דיבור כמה הוי\u0004 \u0005[הוא]\u0006 שיעורו? \u0003כדי שאילת תלמיד לרב\u0004 (שאומר שלוש מלים \"שלום עליך רבי\"), \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003כדי שאילת הרב לתלמיד,\u0004 שאומר שתי מלים \"שלום עליך\". על כל פנים, \u0003עד דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 שניהם \u0003\"שבועה שאין אנו יודעין לך עדות\" טובא הוי\u0004 \u0005[הרבה הוא]\u0006 יותר מכדי שלוש מלים, וכיצד ייתכן שיכפרו שניהם תוך כדי אמירת שלוש מלים? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 הכוונה היא ש\u0003כל אחד ואחד\u0004 צריך להתחיל עדותו \u0003תוך דיבורו של חבירו.\u0004","שנינו במשנה: כפרו \u0003בזה אחר זה\u0004 — \u0003הראשון חייב והשני פטור\u0004 כי השני נשאר רק עד אחד, והואיל ואינו יכול לחייב בעדותו — פטור משום שבועת העדות. ומעירים: \u0003מתניתין דלא כי האי תנא\u0004 \u0005[משנתנו שלא כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003משביע עד אחד\u0004 — \u0003פטור\u0004 מקרבן על שבועת העדות, \u0003ור' אלעזר בר' שמעון מחייב.\u0004 ולדעת ר' אלעזר בר' שמעון, במקרה של משנתנו, צריך היה השני להיות חייב.","ומציעים: \u0003לימא בהא קמיפלגי\u0004 \u0005[האם לומר\u0006 שבנושא \u0005זה הם חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 תנא קמא, \u0005סבור]:\u0006 \u0003עד אחד כי אתא\u0004 \u0005[כאשר\u0006 הוא \u0005בא]\u0006 להעיד — \u0003לשבועה\u0004 בלבד \u0003הוא דקא אתא\u0004 \u0005[שהוא בא],\u0006 לחייב את הצד האחר שישבע, ואין יכולים לחייב ממון בעדותו, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' אלעזר בר' שמעון, \u0005סבור]:\u0006 \u0003עד אחד כי אתא\u0004 \u0005[כאשר\u0006 הוא \u0005בא]\u0006 להעיד \u0003לממונא קא אתא\u0004 \u0005[ל\u0006הוציא \u0005ממון הוא בא],\u0006 ומשום כך נחלקו האם הכפירה של עד אחד נחשבת כפירה בדבר שבממון או לא?","ודוחים: \u0003ותיסברא\u0004 \u0005[וכי סבור אתה\u0006 שכך הוא\u0005]?\u0006 \u0003האמר\u0004 \u0005[הרי אמר]\u0006 \u0003אביי: הכל מודים בעד סוטה\u0004 שחייב משום שבועת העדות, \u0003והכל מודים בעדי סוטה, ומחלוקת בעדי סוטה.\u0004 ועוד: \u0003הכל מודים בעד אחד, והכל מודים בעד שכנגדו חשוד על השבועה.\u0004 וכפי שיוסבר להלן, הכל מודים שאין עד אחד מחייב ממון!","\u0003אלא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003עד אחד כי אתי\u0004 \u0005[כאשר\u0006 הוא \u0005בא]\u0006 להעיד, \u0003לשבועה קא אתי\u0004 \u0005[הוא בא].\u0006 \u0003והכא בהא קמיפלגי\u0004 \u0005[וכאן בזה הם חלוקים],\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר בר' שמעון, \u0005סבור]:\u0006 \u0003דבר הגורם לממון כממון דמי\u0004 \u0005[נחשב],\u0006 ואף שאין העדות של עד אחד מחייבת ממון, פעמים שאינו רוצה להישבע על פי אותו עד וחייב לשלם, ונמצא שעדות זו גורמת לממון, \u0003ומר סבר\u0004 \u0005[וחכם זה סבור]:\u0006 \u0003לאו כממון דמי\u0004 \u0005[אינו נחשב כממון].\u0006","\u0003גופא\u0004 \u0005[לגופה]\u0006 של האימרה שהזכרנו קודם, \u0003אמר אביי: הכל מודים בעד סוטה, והכל מודים בעדי סוטה, ומחלוקת בעדי סוטה. הכל מודים בעד אחד, והכל מודים בעד שכנגדו חשוד על השבועה.\u0004","ומבארים: \u0003הכל מודים בעד סוטה\u0004 — \u0003שחייב\u0004 אם נשבע שאינו יודע עדות, ומדובר \u0003בעד טומאה,\u0004 שהבעל קינא לה תחילה בפני עדים, שאמר לה שלא תיסתר עם פלוני, והעידו עדים שנסתרה עם אותו איש, ועד אחד מעיד שהאשה אכן נטמאה, \u0003דרחמנא הימניה\u0004 \u0005[שהתורה האמינה לו],\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בסוטה שהיא נבדקת במים המרים במקרה ש\u0003\"ועד אין בה\"\u0004 (במדבר ה, יד) שנטמאה, ומשמע: \u0003כל\u0004 עד \u0003שיש בה\u0004 אוסרה, ובעלה מגרשה בלא כתובה. ונמצא שעד טומאה הוא ממש עד ממון (על כסף הכתובה).","\u0003והכל מודים בעדי סוטה \u0004— \u0003שפטור\u0004 משום שבועת העדות, ומדובר פה \u0003בעדי קינוי,\u0004 שהם מעידים שהבעל קינא לאשתו, \u0003דהוה\u0004 \u0005[שהריהו]\u0006 רק \u0003גורם\u0004 של \u0003גורם,\u0004 שהיא צריכה גם עדי סתירה, ורק לאחר מכן אם יבוא עד טומאה, או שתשתה את המים ויתברר שזנתה — תפסיד את כתובתה. ונמצא שעדי קינוי הם רק גורם של הגורם להוצאה של ממון, ולכן אינם מחייבים כשהבעל משביע אותם."],["\u0003ומחלוקת בעדי סוטה\u0004 — מדובר כאן \u0003בעדי סתירה,\u0004 שהם מעידים שהאשה נסתרה עם אחר. \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' אלעזר בר' שמעון, \u0005סבור]:\u0006 \u0003דבר הגורם לממון כממון דמי\u0004 \u0005[נחשב],\u0006 \u0003וחייב\u0004 כלומר, חייבים עדים אלה על שבועת העדות, שהרי אם היו מעידים היו יכולים להביא אותה להפסיד כתובתה, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003לאו כממון דמי\u0004 \u0005[אינו נחשב כממון],\u0006 \u0003ופטור.\u0004","ועוד נאמר לעיל, \u0003הכל מודים בשכנגדו חשוד על השבועה, הכל מודים בעד אחד דר' אבא.\u0004","ודנים: \u0003הכל מודים בשכנגדו חשוד על השבועה. דחשיד מאן\u0004 \u0005[מיהו החשוד]?\u0006 \u0003אילימא דחשיד\u0004 \u0005[אם תאמר שהחשוד]\u0006 הוא ה\u0003לוה\u0004 שכופר בחוב, \u0003דאמר ליה\u0004 \u0005[שאומר לו]\u0006 ה\u0003מלוה\u0004 לעד: \u0003אי אתית אסהדת לי, הוה משתבענא ושקילנא\u0004 \u0005[אם היית בא ומעיד לי\u0006 לטובתי, \u0005הייתי נשבע ונוטל]\u0006 שהרי כנגדי חשוד על השבועה. מדוע יש לחייבו? \u0003ולימא ליה\u0004 \u0005[ושיאמר לו]\u0006 העד: \u0003מי יימר דמשתבעת\u0004 \u0005[מי יאמר שהיית נשבע],\u0006 ואין זה אלא גורם דגורם!","\u0003אלא\u0004 צריך לומר \u0003כגון ששניהן\u0004 הלווה והמלוה \u0003חשודין,\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]:\u0006 מכיון ששניהם חשודים \u0003חזרה\u0004 חובת \u0003שבועה למחויב לה\u0004 כלומר ללווה, \u0003ומתוך שאינו יכול לישבע\u0004 שהרי הוא חשוד על השבועה — \u0003משלם\u0004 הכל, ונמצא שהעד האחד היה מחייב את הלווה בממון.","ומה שאמר אביי \u0003הכל מודים בעד אחד דר' אבא,\u0004 מה עניינו? \u0003דההוא גברא דחטף נסכא מחבריה\u0004 \u0005[\u0006ש\u0005אדם אחד חטף חתיכת כסף מחבירו],\u0006 \u0003אתא לקמיה\u0004 \u0005[בא\u0006 הנגזל \u0005לפני]\u0006 \u0003ר' אמי. הוה יתיב\u0004 \u0005[היה יושב]\u0006 \u0003ר' אבא קמיה\u0004 \u0005[לפניו],\u0006 לפני ר' אמי. \u0003אזל אייתי חד סהדא דמיחטף חטפה מיניה\u0004 \u0005[הלך\u0006 התובע \u0005והביא עד אחד\u0006 שהעיד \u0005שחטף את\u0006 חתיכת הכסף \u0005ממנו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 השני: \u0003אין\u0004 \u0005[כן],\u0006 \u0003חטפי, ודידי חטפי\u0004 \u0005[חטפתי, ו\u0006אולם \u0005שלי חטפתי]\u0006 כי חתיכת הכסף שלי היא.","\u0003אמר ר' אמי: היכי לדייני דייני להאי דינא\u0004 \u0005[איך ידונו הדיינים בדין הזה]?\u0006 אם תאמר \u0003לישלם\u0004 \u0005[שישלם]\u0006 זה שחטף — \u0003ליכא תרי סהדי\u0004 \u0005[אין שני עדים\u0006 שראו שחטף\u0005]!\u0006 \u0003ליפטריה\u0004 \u0005[לפטור אותו\u0006 לגמרי\u0005]\u0006 — \u0003הא איכא חד סהדא דמחטף חטף\u0004 \u0005[הרי יש עד אחד ש\u0006הוא \u0005חטף]!\u0006 \u0003לישתבע\u0004 \u0005[שישבע]\u0006 שלא חטף — \u0003כיון דאמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 \u0003אין, חטפי, ודידי חטפי,\u0004 \u0005[כן, חטפתי, ושלי חטפתי],\u0006 \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003כגזלן,\u0004 שאינו יכול להישבע! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא:\u0004 אם כן, \u0003הוה ליה\u0004 \u0005[הרי הוא]\u0006 \u0003מחויב שבועה ואינו יכול לישבע, וכל המחויב שבועה ואינו יכול לישבע\u0004 — \u0003משלם,\u0004 והעד האחד במקרה כגון זה, אם כופר בשבועה — חייב.","\u0003אמר רב פפא\u0004 כעין דברי אביי: \u0003הכל מודים בעד מיתה שהוא חייב\u0004 משום שבועת העדות, אם כפר ונשבע, \u0003והכל מודים בעד מיתה שהוא פטור.\u0004","ומבארים: \u0003הכל מודים בעד מיתה שהוא פטור\u0004 — ש\u0003אמר לה לדידה\u0004 \u0005[ל\u0006אשה \u0005עצמה]\u0006 שבעלה מת \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003לבית דין,\u0004 ועכשיו הוא כופר בעדותו, ומדוע פטור? \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה שאמרה \"מת בעלי\"\u0004 — הרי זה \u0003תנשא\u0004 על סמך עדות עצמה, וכן אם אמרה \u0003\"מת בעלי\"\u0004 — \u0003תתיבם\u0004 על סמך עדות עצמה. ונמצא שעד זה לא גרם לה להפסיד ממון כתובתה, שהרי היא יכולה בעצמה לבוא לבית דין ולהעיד על פיו על מות בעלה.","\u0003הכל מודים בעד מיתה שהוא חייב\u0004 — מתי? ש\u0003לא אמר לדידה\u0004 \u0005[לה עצמה]\u0006 \u0003ולא אמר להו\u0004 \u0005[להם]\u0006 \u0003לבית דין,\u0004 שנמצא שהיא מפסידה את כתובתה בגלל כפירתו.","ושואלים: \u0003שמע מינה\u0004 \u0005[\u0006האם \u0005נלמד מכאן]\u0006 שלדעת רב פפא \u0003משביע עדי קרקע חייב\u0004 משום שבועת העדות? שהרי הכתובה נגבית מן הקרקעות של הבעל, והרי בנושא זה נחלקו חכמים (להלן שבועות לז,א)! ודוחים: לא, מכאן אין להוכיח, \u0003דלמא\u0004 \u0005[שמא]\u0006 דיבר רב פפא במקרה \u0003דתפישא מטלטלי\u0004 \u0005[שתופסת מיטלטלים]\u0006 של הבעל כדי לגבות מהם כתובתה, ואין זה עד קרקע.","שנינו במשנה: \u0003כפר אחד והודה אחד\u0004 הכופר חייב. ותוהים: מדוע צריך היה לשנות גם דין זה במשנה? \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 במקרה הקודם, שכפרו \u0003בזה אחר זה, דתרוייהו קא כפרי\u0004 \u0005[ששניהם כופרים],\u0006 \u0003אמרת הראשון חייב והשני פטור,\u0004 אם \u0003כפר אחד והודה אחד מיבעיא\u0004 \u0005[נצרכה]\u0006 לומר שהכופר חייב?","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003כגון שכפרו שניהן, וחזר אחד מהן והודה בתוך כדי דיבור, והא קא משמע לן\u0004 \u0005[ו\u0006דבר \u0005זה משמיע לנו],\u0006 ש\u0003תוך כדי דיבור כדיבור דמי\u0004 \u0005[נחשב].\u0006","ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב חסדא דמוקי לה לההוא\u0004 \u0005[שמעמיד אותו,\u0006 את הדין הקודם במשנה\u0005]\u0006 כשכפרו שניהם כאחד שחייבים, \u0003כר' יוסי הגלילי\u0004 שאומר שאפשר לצמצם, כי יש חידוש בשני הדינים, \u0003רישא\u0004 \u0005[בהתחלה]\u0006 היה החידוש בענין זה ש\u0003אפשר לצמצם, וסיפא איצטריך לאשמועינן\u0004 \u0005[והסוף,\u0006 המקרה שלנו, \u0005הוצרך להשמיענו]\u0006 ש\u0003תוך כדי דיבור כדיבור דמי\u0004 \u0005[נחשב].\u0006 \u0003אלא ל\u0004דעת \u0003ר' יוחנן\u0004 שמפרש שגם \u0003רישא\u0004 \u0005[בתחילה]\u0006 מדובר ב\u0003תוך כדי דיבור,\u0004 וגם \u0003סיפא\u0004 \u0005[בסוף]\u0006 \u0003תוך כדי דיבור,\u0004 אם כן \u0003תרתי\u0004 \u0005[שתי]\u0006 הלכות באותו ענין \u0003למה לי?\u0004","ומשיבים: צריך היה להוסיף גם דין זה, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שתוך כדי דיבור נחשב לדיבור אחד אמורים כשיש \u0003כפירה וכפירה\u0004 של השניים, \u0003אבל כפירה והודאה אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ואינו יכול להודות עוד לאחר שכפר, על כן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שתוך כדי דיבור נחשב כדיבור אחד לכל ענין, בין לצרף עדות ובין לחזור בו.","שנינו במשנה: \u0003היו שתי כיתי עדים, כפרה הראשונה ואחר כך כפרה השניה\u0004 — שתיהן חייבות. ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שניה תתחייב\u0004 משום ש\u0003כפרה לה ראשונה,\u0004 ולכן תביעת הממון תלויה בכת השניה, וכיון שכפרה מפסיד ממונו. \u0003אלא\u0004 כת \u0003ראשונה אמאי\u0004 \u0005[מדוע]\u0006 היא מתחייבת?"],["\u0003הא קיימא\u0004 \u0005[הרי עומדת]\u0006 הכת ה\u0003שניה\u0004 שיכולה להעיד, ומה הפסידוהו כשהם אומרים שאינם יודעים עדות!","\u0003אמר רבינא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שהיתה\u0004 כת \u0003שניה בשעת\u0004 (בזמן) \u0003כפירת\u0004 עדי הכת ה\u0003ראשונה קרובין\u0004 זה לזה \u0003בנשותיהן,\u0004 שנשאו שתי אחיות, ופסולים לעדות, וכל העדות תלויה בכת הראשונה. \u0003ו\u0004אולם היו \u0003נשותיהן\u0004 של הכת השניה \u0003גוססות.\u0004 \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003רוב גוססים\u0004 עומדים \u0003למיתה,\u0004 ולכן הם נחשבים אז כראויים להעיד עדות זו, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]:\u0006 \u0003השתא מיהא לא שכיב\u0004 \u0005[\u0006הואיל ו\u0005עכשיו עדיין לא מתו\u0006 נשותיהם\u0005],\u0006 אין הם נחשבים כראויים להעיד.","אמר התובע לעדים: \u0003\"משביע אני עליכם אם לא תבואו ותעידוני שיש לי ביד פלוני פקדון ותשומת יד\u0004 (הלואה) \u0003וגזל ואבידה\",\u0004 והם אמרו לו \u0003\"שבועה שאין אנו יודעין לך עדות\"\u0004 — \u0003אין חייבין אלא\u0004 משום שבועה \u0003אחת.\u0004","אבל אם הם אמרו: \u0003\"שבועה שאין אנו יודעין שיש לך ביד פלוני פקדון ותשומת יד וגזל ואבידה\"\u0004 ונמצאו שקרנים — \u0003חייבין על כל אחת ואחת,\u0004 שהם כנשבעים על כל אחד מהפרטים הללו.","וכן אם אמר: \u0003\"משביע אני עליכם אם לא תבואו ותעידו שיש לי ביד פלוני פקדון\u0004 של \u0003חטין ושעורין וכוסמין\",\u0004 אם אמרו לו: \u0003\"שבועה שאין אנו יודעין לך עדות\"\u0004 — \u0003אין חייבין אלא אחת,\u0004 אבל אם פירטו ואמרו","\u0003\"שבועה שאין אנו יודעין לך עדות שיש לך ביד פלוני חטין ושעורין וכוסמין\"\u0004 — \u0003חייבין על כל אחת ואחת.\u0004","אמר להם: \u0003\"משביע אני עליכם אם לא תבואו ותעידוני שיש לי ביד פלוני נזק\" ו\u0004כן \"שיש לי ביד פלוני \u0003חצי נזק\",\u0004 שמשלם בעל שור תם שנגח שור, וכיוצא בזה \u0003תשלומי כפל\u0004 שמשלם הגנב, \u0003ותשלומי ארבעה וחמשה\u0004 שמשלם גונב כבש או שור וטובחו או מוכרו, או: \"אם לא תעידוני \u0003שאנס איש פלוני את בתי\"\u0004 או \"ש \u0003פתה את בתי\", ו\u0004כן \u0003\"שהכני בני\", ו\"שחבל בי חבירי\", ו\"שהדליק את גדישי ביום הכפורים\",\u0004 אם נשבעו שאינם יודעים לו עדות — \u0003הרי אלו חייבין\u0004 משום שבועת העדות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003משביע עדי קנס\u0004 כלומר, שמשביעם שיעידו על שחבירו חייב לשלם לו תשלום קצוב שנתנה תורה על נזקים שונים, \u0003מהו?\u0004 האם הוא נחשב כמשביע עדי ממון, או לא?","\u0003אליבא\u0004 \u0005[לפי שיטת]\u0006 \u0003ר' אלעזר בר' שמעון לא תיבעי\u0004 \u0005[תישאל]\u0006 \u0003לך\u0004 השאלה, ובוודאי חייבים הם, ש\u0003אמר\u0004 \u0005[ש\u0006הוא \u0005אומר]:\u0006 מי שהיו עליו עדי קנס, והוא עצמו קדם והודה, אינו נפטר בכך, אלא \u0003יבואו עדים ויעידו\u0004 וישלם את הקנס. ונמצא שתשלומי הקנס תלויים רק בעדותם.","\u0003כי תיבעי\u0004 \u0005[כאשר נשאלת]\u0006 \u0003לך\u0004 השאלה הרי זה \u0003אליבא דרבנן\u0004 \u0005[לפי שיטת חכמים]\u0006 החולקים עליו שם, \u0003דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 מי ש\u0003מודה בקנס ואחר כך באו עדים\u0004 — \u0003פטור.\u0004 וכאן מדובר שתבע מן העדים להעיד קודם שהודה הנתבע בקנס.","ותחילה מבררים: \u0003ורבנן דהתם כמאן סבירא להו\u0004 \u0005[\u0006ואותם \u0005חכמים של שם,\u0006 במחלוקת בענין מודה בקנס קודם שבאו עדים, \u0005כמי סבורים הם]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003כר' אלעזר בר' שמעון דהכא\u0004 \u0005[של כאן],\u0006 שהבאנו דבריו קודם, \u0003הא קאמר\u0004 \u0005[הרי הוא אומר]\u0006 ש\u0003דבר הגורם לממון כממון דמי\u0004 \u0005[נחשב]\u0006 לענין שבועת העדות. ועדי קנס אלה אף הם יכולים להיחשב כדבר הגורם לממון, שהרי אם לא יודה הנתבע — מתחייב על פיהם.","\u0003אלא\u0004 צריך לומר שהחכמים של שם סבורים \u0003כרבנן דהכא\u0004 \u0005[כחכמים של כאן],\u0006 \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003דבר הגורם לממון לאו כממון דמי\u0004 \u0005[אינו נחשב כממון],\u0006 ולפיכך יש מקום לשאול \u0003מאי\u0004 \u0005[מה]\u0006 יהא הדין? האם לומר כי \u0003כיון\u0004 ש\u0003אילו\u0004 היה החייב \u0003מודה\u0004 בקנס \u0003מיפטר\u0004 \u0005[היה נפטר]\u0006 מן הקנס, אם כן העד שנשבע שאינו יודע עדות \u0003לאו ממונא קא כפר ליה\u0004 \u0005[לא ממון הוא כופר לו],\u0006 \u0003או דלמא השתא מיהא לא אודי\u0004 \u0005[שמא עכשיו על כל פנים\u0006 \u0005לא הודה]\u0006 החייב, והקנס תלוי איפוא בעדותם של אלו?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממשנתנו: \u0003\"משביע אני עליכם אם לא תבואו ותעידוני שיש לי ביד פלוני נזק וחצי נזק\"\u0004 — הרי אלו חייבים משום שבועת העדות. \u0003והא\u0004 \u0005[והרי]\u0006 \u0003חצי נזק קנסא\u0004 \u0005[קנס]\u0006 \u0003הוא!\u0004 ודוחים: צריכים לפרש זאת \u0003כמאן דאמר פלגא נזקא ממונא\u0004 \u0005[כ\u0006דעת \u0005מי שאומר חצי נזק ממון\u0006 הוא\u0005].\u0006","ושואלים: \u0003הניחא למאן דאמר פלגא נזקא ממונא\u0004 \u0005[זה נוח ל\u0006שיטת \u0005מי שאומר חצי נזק ממון\u0006 הוא\u0005],\u0006 \u0003אלא למאן דאמר קנסא, מאי איכא למימר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר קנס\u0006 הוא, \u0005מה יש לומר]?\u0006 ומשיבים: צריכים לפרש שמדובר בתובע שיעידו \u0003בחצי נזק\u0004 של \u0003צרורות,\u0004 שאדם משלם כשהלכה בהמתו וצרורות אבן נתזו על ידי הליכתה והזיקו, \u0003דהלכתא גמירי לה\u0004 \u0005[שהלכה\u0006 למשה מסיני \u0005למודים אנו]\u0006 שדבר זה אינו נחשב כקנס אלא \u0003דממונא\u0004 \u0005[שממון]\u0006 \u0003הוא.\u0004 ואם כן, מכאן אין להוכיח לענין קנס.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מההמשך במשנתנו: על עדות של \u0003תשלומי כפל,\u0004 שמשלם הגנב פי שנים, חייבים העדים, והוא קנס! ואומרים: אין הכוונה שהעדים חייבים משום תביעת הקנס (הכפל), אלא \u0003משום קרנא\u0004 \u0005[הקרן]\u0006 דמי הגניבה עצמה, שהיא תביעת ממון גמורה.","ומציעים עוד: שנינו שם \u0003\"ותשלומי ארבעה וחמשה\"!\u0004 ומשיבים: גם שם החיוב הוא \u0003משום קרנא\u0004 \u0005[הקרן]\u0006 של הגניבה, ולא בשל הקנס.","ועוד מקשים ממה ששנינו: \u0003\"שאנס איש פלוני ופתה את בתי\",\u0004 והרי האונס והמפתה משלמים קנס חמשים סלעים! ודוחים: שם חייבים \u0003משום\u0004 תביעת \u0003בושת ופגם\u0004 שהיו באונס ובפיתוי, שהם חיוב ממון, שאינם תשלום קצוב.","ושואלים: לפי דרך זו, \u0003מאי קא משמע לן\u0004 \u0005[מה הוא משמיע לנו]\u0006 בריבוי הדוגמאות הללו? הרי \u0003כולה ממונא הוא\u0004 \u0005[כל הדברים האלה יש בהם תביעת\u0006 \u0005ממון]!\u0006 ומשיבים: \u0003רישא, חדא קא משמע לן\u0004 \u0005[בהתחלה,\u0006 דבר \u0005אחד\u0006 של חידוש \u0005השמיע לנו],\u0006 \u0003סיפא, חדא קא משמע לן\u0004 \u0005[בסוף,\u0006 דבר \u0005אחד השמיע לנו];\u0006 \u0003רישא, חדא קא משמע לן\u0004 \u0005[בתחילה,\u0006 דבר \u0005אחד השמיע לנו],\u0006 ש\u0003חצי נזק צרורות ממונא\u0004 \u0005[ממון]\u0006 \u0003הוא\u0004 ולא קנס,","\u0003סיפא חדא קא משמע לן\u0004 \u0005[בסוף\u0006 דבר \u0005אחד השמיע לנו]\u0006 במה ששנינו \u0003ו\"שהדליק את גדישי ביום הכפורים\", לאפוקי מאי\u0004 \u0005[להוציא ממה]?\u0006 \u0003לאפוקי\u0004 \u0005[להוציא]\u0006 \u0003מ\u0004דברי \u0003ר' נחוניא בן הקנה. דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' נחוניא בן הקנה היה עושה\u0004 ודן את \u0003יום הכפורים כשבת לתשלומין, מה שבת\u0004 המדליק גדיש חייב מיתה בסקילה ולכן פטור מהתשלומים, אף ביום הכיפורים, כיון שיש עליו חיוב כרת הרי הוא מתחייב בנפשו ופטור מהתשלומים. ומשנתנו אינה סבורה כן.","ומציעים עוד, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 מברייתא: \u0003\"משביע אני עליכם אם לא תבואו ותעידוני\u0004"],["\u0003שהוציא איש פלוני שם רע על בתי\"\u0004 — \u0003חייבין,\u0004 אם \u0003הודה\u0004 האיש \u0003מפי עצמו\u0004 שהוציא שם רע — \u0003פטור.\u0004 והרי זה תשלום שכולו קנס, וחייבים עליו משום שבועת העדות!","ומשיבים: \u0003הא מני\u0004 \u0005[זו\u0006 כשיטת \u0005מי היא]?\u0006 שיטת \u0003ר' אלעזר בר' שמעון היא,\u0004 ש\u0003אמר:\u0004 אף המודה בקנס, \u0003יבואו עדים ויעידו\u0004 ויחייבו אותו בתשלום.","ומקשים: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של ברייתא זו\u0005]:\u0006 אם \u0003הודה מעצמו\u0004 — \u0003פטור,\u0004 אם כן \u0003אתאן לרבנן\u0004 \u0005[באנו ל\u0006שיטת \u0005חכמים]\u0006 שאומרים שהמודה בקנס נפטר, ולא כשיטתו!","ודוחים: הברייתא \u0003כולה\u0004 שיטת \u0003ר' אלעזר בר' שמעון היא, והכי קאמר\u0004 \u0005[וכך הוא אומר]:\u0006 \u0003לא משכחת לה\u0004 \u0005[אין אתה מוצא אותה]\u0006 הזדמנות של \u0003הודה מפי עצמו\u0004 ש\u0003פטור, אלא היכא דליכא\u0004 \u0005[במקום שאין]\u0006 \u0003עדים כלל והודה מעצמו,\u0004 אבל כשיש עדים הרי הוא מתחייב על פי העדים.","\u0003\"משביע אני עליכם אם לא תבואו ותעידו שאני כהן\",\u0004 או \u0003\"שאני לוי\", \"שאיני בן גרושה\", \"שאיני בן חלוצה\", \"שאיש פלוני\u0004 הוא \u0003כהן\",\u0004 \u0003\"שאיש פלוני לוי\", \"ש\u0004 איש פלוני \u0003אינו בן גרושה\", \"שאינו בן חלוצה\"\u0004 — פטורים על שבועת העדות, לפי שאין אלה תביעות של ממון.","וכן \"משביע אני עליכם אם לא תבואו ותעידו \u0003שאנס איש פלוני את בתו\u0004 שלו\", \u0003ו\u0004\"ש \u0003פתה את בתו\",\u0004 או \u0003\"שחבל בי בני\",\u0004 או \u0003\"שחבל בי חבירי\", \"שהדליק גדישי בשבת\",\u0004 בכל הדברים האלו — \u0003הרי אלו פטורין,\u0004 מפני שבכל אלה יש עונש מוות על העבירה, ופטור מתשלומים.","מלשון המשנה מדייקים: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 במקרה שאומר שיעידו ש\u0003איש פלוני כהן,\u0004 או ש\u0003איש פלוני לוי\u0004 — פטור, שאין זו תביעת ממון, \u0003הא\u0004 \u0005[הרי]\u0006 אם היה אומר \"משביע אני עליכם אם לא תבואו ותעידו ש\u0003מנה לפלוני ביד פלוני\"\u0004 — היו \u0003חייבין. הא קתני סיפא\u0004 \u0005[הרי הוא שונה בסוף,\u0006 בהמשך המשנה בפרקנו\u0005]:\u0006 אין חייבים \u0003עד שישמעו מפי התובע,\u0004 וכאן המשביע הוא אדם אחר, שאינו התובע!","\u0003אמר שמואל:\u0004 כאן מדובר \u0003בבא בהרשאה,\u0004 שהוא מורשה מטעמו של אותו אדם ויכול לתבוע בשמו. ומקשים: \u0003והאמרי נהרדעי\u0004 \u0005[והרי אומרים\u0006 חכמי \u0005נהרדעא]:\u0006 \u0003לא כתבינן אורכתא\u0004 \u0003אמטלטלי\u0004 \u0005[אין אנו כותבים שטר הרשאה על מיטלטלים]!\u0006 ומשיבים: \u0003הני מילי היכא דכפריה\u0004 \u0005[דברים אלה\u0006 אמורים \u0005במקום ש\u0006כבר \u0005כפר בו\u0006 הנתבע\u0005]\u0006 ואז אין עושים הרשאה, \u0003אבל\u0004 אם \u0003לא כפריה\u0004 \u0005[כפר בו]\u0006 — \u0003כתבינן\u0004 \u0005[כותבים אנו]\u0006 גם על מיטלטלים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003מנין שאין הכתוב\u0004 בענין שבועת העדות \u0003מדבר אלא בתביעת ממון? ר' אליעזר אומר: נאמר כאן \"אואין\"\u0004 שנזכרת כמה פעמים המלה \"או\": \"והוא עד או ראה או ידע\" (ויקרא ה, א), \u0003ונאמר להלן\u0004 בשבועת הפקדון \u0003\"אואין\":\u0004 \"או בתשומת יד או בגזל\" וכו' (ויקרא כ״א:י״ט-כ׳), \u0003מה להלן אינו מדבר אלא בתביעת ממון, אף כאן אינו מדבר אלא בתביעת ממון.\u0004","ומקשים: \u0003\"אואין\"\u0004 של \u0003רוצח יוכיחו,\u0004 שנאמר בו \"או השליך עליו בצדיה... או באיבה הכהו\" (במדבר לה, כ— כא), \u0003שהן \"אואין\" ומדברים שלא בתביעת ממון!\u0004","ומשיבים: יש להבדיל, \u0003דנין \"אואין\" שיש עמהן שבועה מ\"אואין\" שיש עמהן שבועה\u0004 כלומר, משבועת הפקדון, \u0003ואל יוכיחו \"אואין\"\u0004 של \u0003רוצח שאין עמהן שבועה.\u0004","ומקשים: \u0003\"אואין\"\u0004 של \u0003סוטה יוכיחו\u0004 כגון \"או עבר עליו רוח קנאה\" (ויקרא ה, יד. ויקרא ה, ל), \u0003שהן \"אואין\" ויש עמהן שבועה,\u0004 שהרי נאמר שהכהן משביע את האשה החשודה, \u0003ומדברים שלא בתביעת ממון!\u0004","ודוחים: \u0003דנין \"אואין\" שיש עמהן שבועה ואין עמהן כהן, מ\"אואין\" שיש עמהן שבועה ואין עמהן כהן, ואל יוכיחו \"אואין\"\u0004 של \u0003רוצח שאין עמהן שבועה, ואל יוכיחו \"אואין\"\u0004 של \u0003סוטה שאף על פי שיש עמהן שבועה יש עמהן כהן.\u0004 זוהי ההוכחה של ר' אליעזר.","\u0003ר' עקיבא אומר,\u0004 נאמר בפרשת שבועת העדות: \u0003\"והיה כי יאשם לאחת מאלה\"\u0004 (ויקרא ה, ה) — \"מאלה\" לשון מיעוט הוא, ללמד: \u0003יש מאלה שהוא חייב, ויש מאלה שהוא פטור, הא\u0004 \u0005[הרי]\u0006 \u0003כיצד?\u0004 אם \u0003תבעו ממון\u0004 — \u0003חייב,\u0004 תבעו \u0003דבר אחר\u0004 — \u0003פטור.\u0004","\u0003ר' יוסי הגלילי אומר\u0004 ראיה אחרת, \u0003הרי הוא אומר\u0004 בפרשה זאת: \u0003\"והוא עד או ראה או ידע\"\u0004 (ויקרא ה, א), לומר: \u0003בעדות המתקיימת בראיה בלא ידיעה\u0004 של הענין, או \u0003בידיעה בלא ראיה,\u0004 בזה \u0003הכתוב מדבר.\u0004","\u0003ראיה בלא ידיעה, כיצד?\u0004 שהוא אומר \u0003\"מנה מניתי לך בפני פלוני ופלוני\",\u0004 והלה טוען: \u0003\"יבואו פלוני ופלוני ויעידו\"\u0004 — \u0003זו היא ראיה בלא ידיעה,\u0004 שהרי אינם יודעים לשם מה מנה לו את המנה, אם כהלוואה, או כפקדון, או כתשלום חוב.","\u0003ידיעה בלא ראיה, כיצד? \"מנה הודיתה לי\u0004 שאתה חייב \u0003בפני פלוני ופלוני\",\u0004 והלה משיב: \u0003\"יבואו פלוני ופלוני ויעידו\"\u0004 — \u0003זו היא ידיעה\u0004 על החוב \u0003בלא ראיה\u0004 של מעשה ההלוואה. ועדות כזו (בראיה או בידיעה לחוד) אינה אלא בדיני ממונות, ולא בדברים אחרים.","\u0003ר' שמעון אומר:\u0004 יש ראיה אחרת לדבר, \u0003חייב כאן\u0004 שבועה \u0003וחייב בפקדון, מה להלן\u0004 בפקדון \u0003אינו מדבר אלא בתביעת ממון, אף כאן אינו מדבר אלא בתביעת ממון.\u0004","\u0003ועוד\u0004 אפשר לומר, \u0003קל וחומר\u0004 הוא מפקדון: \u0003מה פקדון שעשה בו נשים כאנשים, קרובים כרחוקים, פסולים ככשרים, וחייב על\u0004"],["\u0003כל אחת ואחת\u0004 אם השביע כמה פעמים וכפרו, בין שנשבע \u0003בפני בית דין ו\u0004בין \u0003שלא בפני בית דין,\u0004 ועם כל ההרחבה הזו \u0003אינו מדבר\u0004 שם \u0003אלא בתביעת ממון,\u0004 שבועת ה\u0003עדות שלא עשה בה נשים כאנשים,\u0004 ולא עשה בה \u0003קרובים כרחוקים,\u0004 ולא עשה \u0003פסולין ככשרים, ואינו חייב אלא אחת\u0004 אם השביע אותם כמה פעמים \u0003בפני בית דין\u0004 — \u0003אינו דין שלא יהא מדבר אלא בתביעת ממון!\u0004","ודוחים: \u0003מה לפקדון\u0004 שהוא שונה, \u0003שכן לא עשה בו\u0004 דין \u0003מושבע כנשבע,\u0004 שמי שהשביעוהו אחרים ולא נשבע בעצמו — פטור, \u0003ו\u0004כן לא עשה בו דין \u0003מזיד כשוגג, תאמר ב\u0004שבועת ה\u0003עדות שכן עשה בה מושבע כנשבע ומזיד כשוגג\u0004 שבשניהם מביא קרבן!","\u0003תלמוד לומר: \"תחטא\" \"תחטא\" לגזירה שוה, נאמר כאן\u0004 בשבועת העדות \u0003\"תחטא\"\u0004 (ויקרא ה, א), \u0003ונאמר להלן\u0004 בפקדון \u0003\"תחטא\"\u0004 (ויקרא ה כא), \u0003מה להלן\u0004 בשבועת הפקדון \u0003אינו מדבר אלא בתביעת ממון, אף כאן אינו מדבר אלא בתביעת ממון.\u0004","עד כאן ההוכחות השונות בברייתא. ומעתה דנים בדעות השונות שהוזכרו בה. ותחילה דנים בדעת ר' אליעזר, שסיכם כי למדים מ\"אואין\" שבפקדון שיש עמהם שבועה ואין עמהם כהן. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבה בר עולא: \"או\" \"או\"\u0004 האמורים בענין שבועת \u0003ביטוי יוכיחו\u0004 (\"או נפש כי תשבע\" \"להרע או להיטיב\". ויקרא ה, ד) \u0003שהן \"אואין\" ויש עמהן שבועה ואין עמהן כהן, ומדברים שלא בתביעת ממון!\u0004","ודוחים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 ש\u0003מפקדון הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן\u0004 יש דמיון במלים, \u0003\"תחטא\" מ\"תחטא\".\u0004","ודוחים: \u0003אדרבה, מ\u0004שבועת \u0003ביטוי\u0004 \u0003הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן חטאת מחטאת\u0004 שבשתיהן מביא קרבן חטאת, ואילו בשבועת הפקדון חייב קרבן אשם.","\u0003אלא\u0004 צריך לומר בדרך אחרת, \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 ש\u0003מפקדון הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן\u0004 יש בשניהם צדדים שווים: \u0003חטא במזיד תבעיה וכפריה ועבריה\u0004 \u0005[תבעו וכפרו ועברו],\u0006 שהוא סימן לצדדים השווים: בשניהם כתוב \"תחטא\", ועל שניהם חייב קרבן במזיד, ושניהם באים על ידי תביעה של צד אחד וכפירה של הנשבע, ושתיהן שבועות על העבר ולא על העתיד.","ומקשים: \u0003אדרבה,\u0004 להיפך, \u0003מ\u0004שבועת \u0003ביטוי הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן\u0004 יש בה צדדים שווים אחרים, וסימנם: \u0003חטאת שירדה לחומש,\u0004 שעל שניהם מביא קרבן חטאת (ולא אשם כבפקדון), בשניהם הקרבן עולה ויורד (ובפקדון הוא קרבן קבוע), ועל שניהם אין צריך להוסיף חומש! ומשיבים: מכל מקום \u0003הנך נפישן\u0004 \u0005[\u0006הצדדים \u0005הללו\u0006 ששווים בפקדון ובעדות \u0005מרובים\u0006 יותר\u0005]\u0006 ולכן ראוי להשוות שבועת העדות לשבועת הפקדון ולא לשבועת ביטוי.","וממשיכים לדון בדברי הברייתא. \u0003ר' עקיבא אומר: \"והיה כי יאשם לאחת מאלה\"\u0004 (ויקרא ה, ה) — \u0003יש מאלה שהוא חייב, ויש מאלה שהוא פטור. הא כיצד? תבעו ממון\u0004 — \u0003חייב, תבעו דבר אחר\u0004 — \u0003פטור.\u0004","ושואלים: כיון שאין ראיה מגוף הכתוב, \u0003איפוך אנא\u0004 \u0005[אהפוך אני],\u0006 ואומר שחייב רק על תביעה שאינה ממון!","ומשיבים: \u0003ר' עקיבא\u0004 על ה\u0003\"אואין\"\u0004 של \u0003ר' אליעזר סמיך\u0004 \u0005[\u0006הוא \u0005סומך],\u0006 ולומד שבועת העדים משבועת הפקדון, אלא שהוא עושה השוואה שונה קצת.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 להלכה \u0003בין ר' אליעזר ובין ר' עקיבא?\u0004 כיון שהם סומכים על אותה ראיה!","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש\u0006 הבדל \u0005ביניהם]\u0006 לגבי \u0003משביע עדי קרקע,\u0004 ש\u0003ל\u0004דעת \u0003ר' אליעזר חייבין, לר' עקיבא פטורין,\u0004 משום המיעוט על \"מאלה\".","ושואלים: \u0003ול\u0004דעת \u0003ר' יוחנן\u0004 ש\u0003אמר התם\u0004 \u0005[שם]\u0006 שעולה מדבריו לגבי שבועת הפקדון: \u0003משביע עדי קרקע אפילו ל\u0004דעת \u0003ר' אליעזר פטורין,\u0004 אם כן \u0003הכא מאי איכא\u0004 \u0005[כאן מה יש]\u0006 הבדל \u0003בין ר' אליעזר לר' עקיבא?\u0004","ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 בהלכה בענין \u0003עדי קנס,\u0004 שלר' אליעזר חייבים, ולר' עקיבא, בגלל המיעוט, פטורים.","ועוד באותה ברייתא, \u0003ר' יוסי הגלילי אומר: \"והוא עד או ראה או ידע\"\u0004 — \u0003בעדות המתקיימת בראיה בלא ידיעה ובידיעה בלא ראיה הכתוב מדבר,\u0004 והיא עדות ממון, לפי שבעדות אחרת יש צורך שיהא בה גם ראיה וגם ידיעה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב פפא לאביי: לימא\u0004 \u0005[האם לומר]\u0006 ש\u0003ר' יוסי הגלילי לית ליה\u0004 \u0005[אינו סבור]\u0006 כשיטת \u0003ר' אחא? דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אחא אומר: גמל האוחר\u0004 מיוחם ומשתולל \u0003בין הגמלים ונמצא גמל הרוג בצידו\u0004 — \u0003בידוע שזה הרגו,\u0004 ואין צורך לראות שכך היה כדי לחייב את בעליו. \u0003דאי אית ליה\u0004 \u0005[שאם יש לו,\u0006 הוא מקבל\u0005]\u0006 את שיטת \u0003ר' אחא\u0004 שהולכים אחרי ידיעה מסוג זה, המבוססת על אומדנא, אם כן \u0003בדיני נפשות נמי משכחת לה\u0004 \u0005[גם כן מוצא אתה אותה],\u0006 כמו המקרה שדן בו \u0003ר' שמעון בן שטח.\u0004","\u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר ר' שמעון בן שטח\u0004 בלשון שבועה: \u0003אראה בנחמה\u0004 (של גאולת ישראל השלימה) \u0003אם לא ראיתי אחד שרץ אחר חבירו לחורבה, ורצתי אחריו ומצאתי סייף\u0004 (חרב) \u0003בידו\u0004 של הרודף \u0003ודם מטפטף\u0004 מן הסייף, \u0003ו\u0004ה\u0003הרוג\u0004 מונח שם \u0003מפרפר, אמרתי לו: רשע, מי הרגו לזה, או אני או אתה?\u0004","שהרי רק שנינו מצויים כאן, \u0003אבל מה אעשה שאין דמך מסור בידי, שהרי אמרה תורה: \"על פי שנים עדים או שלשה עדים יומת המת\"\u0004 (דברים יז, ו) ואין כאן שני עדים, \u0003אלא המקום\u0004 (הקב\"ה) \u0003יפרע ממך. אמרו: לא זזו משם עד שנשכו נחש ומת!\u0004 ובמקרה כזה, לדעת ר' אחא יש לסמוך על האומדנא שזה הרגו, להחשיבה כידיעה וודאית, למרות שלא ראה. ולכאורה ר' יוסי הגלילי אינו סבור כן, שהרי הוא אומר שידיעה בלא ראיה אינה אלא בממונות.","ומשיבים: \u0003אפילו תימא אית ליה\u0004 \u0005[תאמר\u0006 ש\u0005יש לו,\u0006 שהוא מקבל\u0005]\u0006 את דברי \u0003ר' אחא,\u0004 שהולכים בדיני נפשות אחר אומדנא בלא ראיה, עדיין יש להבחין בין דיני ממונות לדיני נפשות, כי \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ידיעה בלא ראיה משכחת לה\u0004 \u0005[מוצא אתה אותה]\u0006 גם בדיני נפשות, באומדנא, \u0003אלא ראיה בלא ידיעה היכי משכחת לה\u0004 \u0005[כיצד מוצא אתה אותה]?\u0006 \u0003מי לא בעי מידע\u0004 \u0005[האם אין\u0006 הוא \u0005צריך לדעת]\u0006 \u0003אם גוי הרג או ישראל הרג, אם אדם טרפה\u0004 (שקרוב למוות) \u0003הרג או שלם הרג?\u0004 ולפיכך יש הבדל בין דיני ממונות לשאר דינים.","ועוד מעירים: \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 מברייתא זו ש\u0003קסבר\u0004 \u0005[סבור]\u0006 \u0003ר' יוסי הגלילי: משביע עדי קנס\u0004 — \u0003פטור\u0004 העד משבועת העדות, \u0003דאי סלקא דעתך\u0004 \u0005[שאם עולה על דעתך]\u0006 שהוא \u0003חייב, נהי\u0004 \u0005[אם אמנם]\u0006 צד של \u0003ידיעה בלא ראיה אשכחן לה\u0004 \u0005[מוצאים אנו אותה]\u0006 בקנסות, שפעמים אינו רואה את מעשה העבירה אבל יודע שכן היה הדבר, כגון במקרה של אונס. אולם \u0003ראיה בלא ידיעה\u0004 אינך מוצא בקנסות, כי \u0003מי לא בעי מידע\u0004 \u0005[האם\u0006 אין העד \u0005צריך לדעת]\u0006 אם \u0003גויה בעל\u0004 או \u0003בת ישראל בעל, בתולה בעל\u0004 או \u0003בעולה בעל?\u0004","בקשר לענין זה של ראיה בלי ידיעה בממונות, מספרים: \u0003יתיב\u0004 \u0005[יושב\u0006 היה\u0005]\u0006 \u0003רב המנונא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יהודה, ויתיב\u0004 \u0005[ויושב\u0006 היה\u0005]\u0006 \u0003רב יהודה וקא מיבעיא ליה\u0004 \u0005[והיה מסתפק\u0006 בשאלה \u0005זו]:\u0006 אם תובע אדם פלוני ואומר לו: \u0003\"מנה מניתיך\u0004 (נתתי ומניתי לך) \u0003בפני פלוני ופלוני\",\u0004"],["\u0003ועדים\u0004 היו \u0003רואין אותו מבחוץ\u0004 כשמנה לו, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? האם אפשר לקבל את עדותם בזה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב המנונא\u0004 לרב יהודה: \u0003והלה,\u0004 הנתבע, \u0003מה\u0004 הוא \u0003טוען\u0004 בענין זה? \u0003אי אמר\u0004 \u0005[אם הוא אומר]:\u0006 \u0003\"לא היו דברים מעולם\"\u0004 — אם כן \u0003הוחזק כפרן,\u0004 שהרי העדים מעידים שכן היה מעשה! \u0003אי אמר\u0004 \u0005[אם הוא אומר]:\u0006 \u0003\"אין,\u0004 \u0003שקלי ודידי שקלי\"\u0004 \u0005[\"כן, לקחתי\u0006 את הכסף ממנו \u0005ו\u0006אולם את \u0005שלי לקחתי\"],\u0006 \u0003כי אתו\u0004 \u0005[כאשר יבואו]\u0006 \u0003עדים מאי הוי\u0004 \u0005[מה יהיה]?\u0006 הרי אין העדים יודעים מפני מה נטל ממנו כסף זה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003המנונא את\u0004 \u0005[אתה]?\u0006 \u0003עול תא\u0004 \u0005[בוא והיכנס],\u0006 שדברים של טעם אמרת.","ובענין דומה מסופר, \u0003ההוא דאמר ליה לחבריה\u0004 \u0005[אדם אחד שאמר לו לחבירו]:\u0006 \u0003מנה מניתי לך\u0004 כהלוואה \u0003בצד עמוד זה, אמר ליה\u0004 \u0005[לו]\u0006 החבר: \u0003לא עברתי בצד עמוד זה, אתו תרי סהדי אסהידו ביה\u0004 \u0005[באו שני עדים העידו בו]\u0006 ש\u0003השתין מים בצד עמוד זה. אמר ריש לקיש: הוחזק כפרן,\u0004 שהרי הוכח שעבר בצד עמוד זה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב נחמן: האי דינא פרסאה\u0004 \u0005[זה דין פרסי]\u0006 \u0003הוא,\u0004 ולא דין שקול כדיני ישראל! \u0003מי קאמר\u0004 \u0005[האם אמר]\u0006 ש\u0003מעולם\u0004 לא עבר בצד העמוד? \u0003בעסק זה קאמר ליה\u0004 \u0005[בענין זה אמר לו],\u0006 ואין דברי העדים שייכים לכאן.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 מעין זה בלשון אחרת, \u0003ההוא דאמר ליה לחבריה\u0004 \u0005[אחד שאמר לו לחבירו]:\u0006 \u0003מנה מניתי לך בצד עמוד זה, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא עברתי בצד עמוד זה מעולם, נפקו ביה סהדי\u0004 \u0005[יצאו בו עדים]\u0006 שהעידו בו ש\u0003השתין מים בצד עמוד זה. אמר רב נחמן: הוחזק כפרן\u0004 שהרי הוכחשו דבריו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן:\u0004 מכאן אין ראיה שהוא כפרן, כי \u0003כל מילתא דלא רמיא עליה דאיניש\u0004 \u0005[כל דבר שאינו מוטל על האדם\u0006 לזכור\u0005]\u0006 \u0003עביד לה, ולאו אדעתיה\u0004 \u0005[עושה אותו, ואין זה בדעתו\u0006 ובזכרונו\u0005],\u0006 וכאשר הכחיש שהיה בצד העמוד — היה זה משום שלא היה צריך לזכור דבר זה.","ושוב לביאורה של הברייתא, בשאלה מנין שדין שבועת העדות הוא דווקא בדבר שבממון, ששנינו שם ש\u0003ר' שמעון אומר: חייב כאן וחייב ב\u0004שבועת \u0003פקדון,\u0004 מה להלן אינו מדבר אלא בתביעת ממון אף כאן אינו מדבר אלא בתביעת ממון.","\u0003מחכו עלה במערבא\u0004 \u0005[היו צוחקים על כך בארץ ישראל]\u0006 על ההוכחה הזו. ושואלים: \u0003מאי חוכא\u0004 \u0005[מה הצחוק\u0006 שבדבר\u0005]?\u0006","ומסבירים: \u0003דקתני\u0004 \u0005[ששנה]\u0006 בהמשך הדברים: \u0003מה לפקדון שכן לא עשה בו מושבע כנשבע מזיד כשוגג;\u0004 וזה הקושי:","\u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003מושבע מפי עצמו בעדות ל\u0004דעת \u0003ר' שמעון מנא ליה\u0004 \u0005[מנין לו]?\u0006 \u0003דגמר\u0004 \u0005[ש\u0006הוא \u0005לומד]\u0006 דין זה בגזירה שווה \u0003מפקדון,\u0004 והרי \u0003פקדון נמי\u0004 \u0005[גם כן]\u0006 נאמר כי \u0003מושבע מפי אחרים נגמר\u0004 \u0005[נלמד]\u0006 באותה דרך \u0003מעדות,\u0004 ונאמר שאף בפקדון חייב כשמושבע מפי אחרים!","ודוחים: \u0003ומאי חוכא\u0004 \u0005[ומה הצחוק\u0006 שבדבר\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003ר' שמעון\u0004 הלכה זו לא מגזירה שווה לדין פקדון למד, אלא \u0003בקל וחומר מייתי לה\u0004 \u0005[מוציא אותה],\u0006 מדין שבועת העדות בעצמה, וכך הוא לומד: כיצד יודעים שבעדות מושבע מפי עצמו חייב? אם מושבע \u0003מפי אחרים חייב, מפי עצמו לא כל שכן!\u0004","ומשיבים: \u0003אלא חוכא\u0004 \u0005[הצחוק]\u0006 הוא על \u0003מזיד כשוגג, דקתני\u0004 \u0005[ששנה]:\u0006 \u0003מה לפקדון שכן לא עשה בו מושבע כנשבע מזיד כשוגג;\u0004 וכן הקושיה:","\u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003מזיד גבי\u0004 \u0005[אצל]\u0006 \u0003עדות מנא ליה\u0004 \u0005[מנין לו]\u0006 שהוא חייב? משום ש\u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"ונעלם\",\u0004 והרי \u0003הכא נמי\u0004 \u0005[כאן,\u0006 בפקדון \u0005גם כן]\u0006 \u0003לא כתיב ביה\u0004 \u0005[נאמר בו]\u0006 \u0003\"ונעלם\",\u0004 ולפיכך גם בפקדון יהא חייב על המזיד כשוגג!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב הונא\u0004 לחכמים: \u0003ומאי חוכא\u0004 \u0005[ומה הצחוק\u0006 שבזה\u0005]?\u0006 \u0003דלמא\u0004 \u0005[שמא]\u0006 הלכה זו ש\u0003מזיד דלאו\u0004 \u0005[שאינו]\u0006 \u0003כשוגג בפקדון\u0004 — \u0003מ\u0004דין \u0003מעילה ר' שמעון גמר לה\u0004 \u0005[לומד אותה],\u0006 שמשווה דין שבועת הפקדון לדין מעילה בקדשים, שכשם שבמעילה חייב רק בשוגג — הוא הדין בפקדון!","ומשיבים: \u0003והיינו חוכא\u0004 \u0005[וזהו הצחוק],\u0006 \u0003אדגמר לה\u0004 \u0005[עד ש\u0006הוא \u0005לומד את\u0006 הדבר\u0005]\u0006 \u0003ממעילה\u0004 לומר שאינה במזיד \u0003נגמר לה\u0004 \u0005[שילמד אותה]\u0006 \u0003מעדות,\u0004 ויחייב גם על המזיד!","ודוחים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003ממעילה הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן מעילה ממעילה,\u0004 שהביטוי \"מעל\" מופיע גם במעילה (\"כי תמעול מעל\". ויקרא ה, טו) וגם בשבועת הפקדון כתוב \"כי תמעול מעל\" (ויקרא ה, כא).","ומקשים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003מעדות הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן \"תחטא\" מ\"תחטא\"\u0004 שמלה זו מצויה בשניהם!","ודוחים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי \u0003ממעילה הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן\u0004 יש בפקדון הרבה צדדים דומים למעילה: ששניהם קרויים \u0003מעילה\u0004 ששניהם נוהגים \u0003בכל\u0004 אדם, ולא רק בראויים לכך כמו בעדות. בשניהם \u0003נהנה\u0004 מדבר שאינו שלו (במעילה — מקדשים, ובפקדון — מרכוש של אחר). בשניהם יש כפרה בקרבן \u0003קבוע\u0004 (ובשבועת עדות בעולה ויורד). בשניהם יש חיוב \u0003חומש\u0004 בנוסף על תשלום הקרן, \u0003ואשם\u0004 ששניהם מתכפרים בקרבן אשם.","ודוחים: \u0003אדרבה\u0004 \u0005[גדולה מזו,\u0006 להיפך\u0005],\u0006 \u0003מעדות הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 \u0003שכן חטא\u0004 (\"תחטא\" \"תחטא\"). בשניהם מדובר בממון של \u0003הדיוט\u0004 ולא קדשים. וכן מדובר \u0003בשבועה.\u0004 בשניהם מתחייב במקרה ש\u0003תבעיה וכפריה\u0004 \u0005[שתבעו וכפר לו],\u0006 שאין עבירות אלה באות אלא לאחר תביעה וכפירה, \u0003ו\"אואין\"\u0004 בשניהם מצויה המלה \"או\" כמה פעמים! ומשיבים: מכל מקום \u0003הנך נפישין\u0004 \u0005[אלה\u0006 הצדדים השווים למעילה \u0005מרובים יותר].\u0006","ושואלים: אם כן, שיישבנו דברי ר' שמעון, \u0003אלא מאי חוכא\u0004 \u0005[מהו הצחוק]\u0006 שצחקו בארץ ישראל?","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב פפא ורב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע מבי רב\u0004 \u0005[מבית רבם]\u0006 \u0003אמרי\u0004 \u0005[אמרו]\u0006 כך: \u0003היינו חוכא\u0004 \u0005[זהו הצחוק],\u0006 \u0003מכדי\u0004 \u0005[הרי]\u0006 \u0003ר' שמעון\u0004 ב\u0003גזירה שוה גמיר\u0004 \u0005[\u0006הוא \u0005לומד]\u0006 בסוף (מן המלים \"תחטא\" \"תחטא\"), ואם כן \u0003למה ליה דפריך\u0004 \u0005[לו להקשות]:\u0006 \u0003מה לפקדון שכן לא עשה בו מושבע כנשבע מזיד כשוגג?\u0004 היה לו ללמוד דין פקדון מעדות, ולהשוותם בדברים אלה!","ודוחים: \u0003ומאי חוכא\u0004 \u0005[ומה הצחוק]?\u0006 \u0003דלמא כי פריך\u0004 \u0005[שמא כאשר\u0006 הוא \u0005מקשה]\u0006 וסבור שיש הבדל באלה — הרי זה \u0003מקמי דתיקום ליה\u0004 \u0005[לפני שעמדה\u0006 והוחזקה \u0005בידו]\u0006 ה\u0003גזירה שוה,\u0004 שקודם הישווה את הדינים בדרך של בנין אב, אבל \u0003בתר דקמא ליה\u0004 \u0005[אחרי שעמדה לו]\u0006 ה\u0003גזירה שוה\u0004 שבה יש השוואה גמורה של הדברים, \u0003לא פריך\u0004 \u0005[מקשה]\u0006 קושיה הזו, וסבור באמת שבפקדון חייב על המזיד כשוגג!","ושואלים: \u0003ולא?\u0004 האם אין ר' שמעון סבור עוד כך, והוא חוזר בו מקושיה זו? \u0003והאמר להו\u0004 \u0005[והרי אמר להם]\u0006 \u0003רבא בר איתי לרבנן\u0004 \u0005[לחכמים]:\u0006 \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור ש\u0003שבועת הפקדון לא ניתן זדונה לכפרה\u0004 כלל? שיטת \u0003ר' שמעון היא!\u0004 משמע שהוא עומד בדעתו שבפקדון אין הזדון כשגגה!","ומציעים: \u0003דלמא\u0004 \u0005[שמא]\u0006 כאשר ר' שמעון מקשה, דווקא מ\u0003מזיד כשוגג פריך\u0004 \u0005[\u0006הוא \u0005מקשה],\u0006 והלכה זו עומדת בעינה גם לאחר שלמד גזירה שווה, משום \u0003דגמר לה\u0004 \u0005[ש\u0006הוא \u0005לומד אותה]\u0006 \u0003ממעילה,\u0004 שכשם שבמעילה מביא קרבן רק על השגגה — כן הוא גם כן לענין הפקדון. והטעם שלמד הלכה זו ממעילה ולא מעדות, הוא כפי שאמרנו \u0003דהנך נפישין\u0004 \u0005[שאלה\u0006 הצדדים השווים למעילה \u0005מרובים יותר]\u0006 מאשר בהשוואה לעדות, \u0003אבל\u0004 לגבי \u0003מושבע כנשבע לא פריך\u0004 \u0005[אינו מקשה]\u0006 עוד, אלא הוא סבור שבגלל הגזירה השווה הרי גם בפקדון כמו בעדות עשו מושבע כנשבע.","ושואלים: \u0003ו\u0004אם כן, שלר' שמעון בפקדון אין המזיד מביא קרבן כשוגג, \u0003תהדר\u0004 \u0005[תחזור]\u0006 ה\u0003עדות ותגמר לה\u0004 \u0005[ותילמד]\u0006 \u0003מפקדון\u0004 ונאמר \u0003מזיד דלאו\u0004 \u0005[שאינו]\u0006 \u0003כשוגג: מה פקדון, שוגג\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מזיד\u0004 — \u0003לא, אף עדות, שוגג\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003מזיד\u0004 — \u0003לא, כי היכי דיליף\u0004 \u0005[כמו ש\u0006הוא \u0005לומד]\u0006 \u0003פקדון ממעילה!\u0004"],["ומשיבים: \u0003להכי כתבה רחמנא\u0004 \u0005[משום כך כתבה אותה התורה]\u0006 \u0003לעדות גבי\u0004 \u0005[אצל]\u0006 \u0003שבועת ביטוי וגבי\u0004 \u0005[ואצל]\u0006 \u0003טומאת מקדש וקדשיו,\u0004 ש\u0003בכולן נאמר בהן \"ונעלם\" וכאן\u0004 בעדות \u0003לא נאמר בהן \"ונעלם\"\u0004 — הרי זה להדגיש \u0003לחייב על המזיד כשוגג.\u0004","אמר להם: \u0003\"משביע אני עליכם אם לא תבואו ותעידוני שאמר איש פלוני ליתן לי מאתים זוז ולא נתן\"\u0004 ונשבעו לשקר שאינם יודעים לו עדות — \u0003הרי אלו פטורים\u0004 מדין שבועת העדות, \u0003שאין חייבין אלא על תביעת ממון\u0004 כמו \u0003פקדון,\u0004 וכאן אין בו תביעת ממון.","\u0003\"משביע אני עליכם כשתדעו לי עדות שתבואו ותעידוני\"\u0004 — \u0003הרי אלו פטורים\u0004 גם אם לא העידו, \u0003מפני שקדמה שבועה ל\u0004ידיעת ה\u0003עדות.\u0004","אם \u0003עמד בבית הכנסת ואמר\u0004 לכלל הקהל: \u0003\"משביע אני עליכם שאם אתם יודעין לי עדות שתבואו ותעידוני\"\u0004 — \u0003הרי אלו פטורין, עד שיהא מתכוין להם\u0004 לאנשים מסויימים.","וכן \u0003אמר לשנים: \"משביע אני עליכם איש פלוני ופלוני שאם אתם יודעין לי עדות שתבואו ותעידוני\",\u0004 והם אמרו לו: \u0003\"שבועה שאין אנו יודעין לך עדות\", והם\u0004 היו \u0003יודעין לו עדות,\u0004 אבל לא עדות ישירה, אלא \u0003עד מפי עד,\u0004 וזו אינה נקראת עדות, \u0003או שהיה אחד מהן קרוב או פסול\u0004 — \u0003הרי אלו פטורין,\u0004 לפי שאינם ראויים להעיד.","\u0003שלח\u0004 להם \u0003ביד עבדו, או שאמר להן הנתבע: \"משביע אני עליכם שאם אתם יודעין לו\u0004 לתובע \u0003עדות שתבואו ותעידוהו\"\u0004 — \u0003הרי אלו פטורין,\u0004 ואין חייבים משום שבועת העדות \u0003עד שישמעו מפי התובע.\u0004","ומביאים ראיות מן הכתובים לדינים האמורים במשנה. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003\"משביעני עליכם אם לא תבואו ותעידוני שאמר איש פלוני ליתן לי מאתים זוז ולא נתן\", יכול יהו חייבין? תלמוד לומר: \"תחטא\" \"תחטא\" לגזירה שוה,\u0004","\u0003נאמר כאן\u0004 בשבועת העדות \u0003\"תחטא\"\u0004 (ויקרא ה, א), \u0003ונאמר להלן\u0004 בשבועת הפקדון \u0003\"תחטא\"\u0004 (ויקרא ה כא), \u0003מה להלן\u0004 בפקדון מדובר \u0003בתביעת ממון\u0004 (כמבואר שם: בפקדון, בתשומת יד, בגזל, בעושק) \u0003ויש לו\u0004 לתובע זכות בממון זה, \u0003אף כאן\u0004 בעדות מדובר \u0003בתביעת ממון ויש לו,\u0004 וכאן אין לו זכות בממון זה.","שנינו במשנה \u0003\"משביע אני עליכם כשתדעו לי עדות\u0004 שתבואו ותעידוני\".","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003\"משביע אני עליכם כשתדעו לי עדות שתבואו ותעידוני\", יכול יהו חייבין? תלמוד לומר: \"ושמעה קול אלה והוא עד או ראה או ידע\"\u0004 (ויקרא ה, א), לומר שמדובר ב\u0003מי שקדמה עדות לשבועה\u0004 שהמושבע הוא באותו זמן כבר עד, וכבר ראה או ידע, \u0003ולא שקדמה שבועה לעדות.\u0004","ועל מה ששנינו: \u0003\"עמד בבית הכנסת ואמר \"משביעני עליכם\u0004 שאם אתם יודעים לי עדות שתבואו ותעידוני — הרי אלו פטורים\". \u0003אמר שמואל: אפילו\u0004 היו \u0003עדיו\u0004 \u0003ביניהן\u0004 בתוך הקהל.","ושואלים: \u0003פשיטא\u0004 \u0005[פשוט]\u0006 הוא, שאם לא כן אין בכך כל חידוש! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דקאי עילויהו\u0004 \u0005[\u0006כשהוא \u0005עומד עליהם]\u0006 בסמוך להם, \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003כמאן דאמר להו דמי\u0004 \u0005[כמי שאומר להם\u0006 במפורש \u0005נחשב],\u0006 \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שכל זמן שלא פירש למי כוונתו אין זו השבעה מחייבת לענין שבועת העדות.","ומביאים: \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003ראה סיעה\u0004 (חבורה) \u0003של בני אדם עומדין ועדיו\u0004 היו \u0003ביניהן, ואמר להן\u0004 לאנשי כל הסיעה: \u0003\"משביעני עליכם אם אתם יודעין לי עדות שתבואו ותעידוני\", יכול יהו חייבין? תלמוד לומר: \"והוא עד\"\u0004 (ויקרא ה,א), \u0003והרי\u0004 כאן \u0003לא ייחד עדיו. יכול אפילו אמר \"כל העומדין כאן\u0004 יבואו להעיד\"? כי \u0003תלמוד לומר: \"והוא עד\", והרי ייחד עדיו\u0004 אף על פי שדיבר לאנשים הרבה, ובמקרה זה חייב.","ועוד שנינו במשנה: \u0003אמר לשנים \"משביע אני עליכם\",\u0004 והם יודעים לו עדות מפי עד, או שהיה אחד מהם קרוב או פסול — פטורים. ומביאים, \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אמר לשנים: \"משביע אני עליכם פלוני ופלוני אם אתם יודעין לי עדות שתבואו ותעידוני\", והן יודעין לו עדות עד מפי עד, או שהיה אחד מהן קרוב או פסול, יכול יהו חייבין? תלמוד לומר: \"אם לוא יגיד ונשא עונו\"\u0004 (ויקרא ה,א), \u0003בראוין להגדה הכתוב מדבר,\u0004 ולא בשאינם ראויים להעיד.","שנינו במשנה: \u0003שלח ביד עבדו וכו'. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003שלח ביד עבדו, או שאמר להן הנתבע: \"משביעני עליכם שאם אתם יודעין לו עדות שתבואו ותעידוהו\", יכול יהו חייבין\u0004 משום שבועת העדות אם לא יעידו? \u0003תלמוד לומר: \"אם לא יגיד ונשא עונו\".\u0004","ושואלים: \u0003מאי תלמודא\u0004 \u0005[מה הלימוד\u0006 בזה\u0005]?\u0006 מה ההוכחה מן הכתוב? \u0003אמר ר' אלעזר: \"אם לוא יגיד\"\u0004 בוא\"ו \u0003כתיב\u0004 \u0005[נאמר],\u0006 ואנו קוראים צורה זו כאילו היתה שתי מלים \"לו לא\", כלומר: \u0003אם לו\u0004 (לתובע) \u0003לא יגיד\u0004 — \u0003ונשא עונו, ואם לאחר לא יגיד\u0004 — הרי הוא \u0003פטור.\u0004","ודנים בלשונה של שבועת העדות. אמר לעדים: \u0003\"משביעני (אני) עליכם\u0004 אם לא תבואו ותעידוני\", או אפילו אמר \u0003\"מצוה אני עליכם\",\u0004 או \u0003\"אוסרכם אני\",\u0004 אף שאמר שלא בלשון השבעה גמורה — \u0003הרי אלו חייבין.\u0004","השביעם \u0003\"בשמים ובארץ\"\u0004 — \u0003הרי אלו פטורין,\u0004 שאין זו השבעה בשם ה'. השביעם \u0003ב\"אלף דלת\"\u0004 (קיצור של שם אדנות), או \u0003ב\"יוד הי\"\u0004 (קיצור של שם הוי-ה), או \u0003ב\"שדי\", ב\"צבאות\", ב\"חנון\" ו\"רחום\", ב\"ארך אפים\", ב\"רב חסד\", ובכל\u0004 שאר \u0003הכנויין\u0004 שמכנים בהם את ה', אף על פי שלא הזכיר אותו בשם מפורש — \u0003הרי אלו חייבין.\u0004","וכן \u0003המקלל\u0004 את השם \u0003בכולן,\u0004 בכל אחד משמות אלו או בכינויים — הרי זה \u0003חייב, דברי ר' מאיר, וחכמים פוטרין,\u0004 שהם סבורים שחייב רק אם מזכיר את השם המפורש.","\u0003המקלל אביו ואמו בכולן\u0004 — \u0003חייב, דברי ר' מאיר, וחכמים פוטרין\u0004 שלדעתם אין חייב אלא המקלל בשם המפורש.","\u0003המקלל עצמו וחבירו בכולן\u0004 — \u0003עובר בלא תעשה.\u0004 אם הוא אומר \u0003\"יככה ה' אלהים\"\u0004 (ראה דברים כח, כב), \u0003וכן\u0004 האומר \u0003\"יככה אלהים\u0004 אם לא תבוא להעיד\" — \u0003זו היא אלה הכתובה בתורה,\u0004 ובוודאי חייב עליה אם לא העיד.","אם אמר לאדם: \u0003\"אל יכך\", ו\"יברכך\", ו\"ייטיב לך\"\u0004 אם תבוא להעיד — \u0003ר' מאיר מחייב\u0004 משום שמכלל הדברים מובן שאם לא תעשה כן — יככה, ולא יברכך, \u0003וחכמים פוטרין\u0004 משום שלא נאמרה הקללה במפורש.","שנינו במשנה: \u0003\"משביעני עליכם\",\u0004 \"מצוה אני עליכם\", \"אוסרכם אני\" — הרי אלו חייבים. ושואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר]?\u0006 הרי רק אמר שהוא משביע, אבל לא אמר במה הוא משביע! \u0003אמר רב יהודה, הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 לכך הכוונה: \u0003\"משביע אני עליכם בשבועה האמורה בתורה\", \"מצוה אני עליכם בצוואה האמורה בתורה\", \"אוסרכם אני באיסור האמור בתורה\",\u0004 ובתורה נזכר בכל אלה שם ה'.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי, אלא הא דתני\u0004 \u0005[זו ששנה]\u0006 \u0003ר' חייא\u0004 שאם אמר להם \u0003\"כובלכם אני\"\u0004 — \u0003הרי אלו חייבין,\u0004 וכי \u0003כובל באורייתא\u0004 \u0005[בתורה]\u0006 \u0003מי כתיב\u0004 \u0005[האם\u0006 הוא \u0005כתוב]?\u0006 ואם כן, הוא לא מסתמך על הכתוב בתורה!","\u0003אלא אמר אביי, הכי קאמר\u0004 \u0005[כך\u0006 הוא \u0005אומר]:\u0006 אם אמר \u0003\"משביע אני עליכם בשבועה\", \"מצוה אני עליכם בשבועה\", \"אוסרכם אני בשבועה\", \"כובלכם אני בשבועה\"\u0004 — הרי אלו חייבים כל זמן שמזכיר שבועה.","שנינו במשנה שאם השביעם \u0003ב\"אלף דלת\", ב\"יוד הי\", ב\"שדי\", ב\"צבאות\", ב\"חנון\" ו\"רחום\", ב\"ארך אפים\", ב\"רב חסד\"\u0004 — הרי אלו חייבים.","ומתקשים: \u0003למימרא\u0004 \u0005[האם לומר],\u0006 ש\u0003\"חנון\" ו\"רחום\" שמות\u0004 קדושים \u0003נינהו\u0004 \u0005[הם]?\u0006 \u0003ורמינהי\u0004 \u0005[ומשליכים\u0006 ומקשים על כך\u0005]\u0006 ממה ששנינו בברייתא: \u0003יש שמות\u0004 של הקדוש ברוך הוא \u0003שנמחקין\u0004 שמותר למוחקם, \u0003ויש שמות שאין נמחקין,\u0004 מפני שיש בהם קדושה עצמית ואסור למחוק את השם. \u0003אלו הן שמות שאין נמחקין: כגון \"אל\", \"אלהיך\", \"אלהים\", \"אלהיכם\", \"אהיה אשר אהיה\", \"אלף דלת\", ו\"יוד הי\", \"שדי\", \"צבאות\"\u0004 — \u0003הרי אלו אין נמחקין;\u0004","\u0003אבל\u0004 תארים שמתייחסים לקדוש ברוך הוא, כגון: \u0003\"הגדול\", \"הגבור\", \"הנורא\", \"האדיר\", ו\"החזק\", ו\"האמיץ\", \"העזוז\", \"חנון\" ו\"רחום\", \"ארך אפים\", ו\"רב חסד\"\u0004 — \u0003הרי אלו נמחקין.\u0004 ואם כן, אין \"רחום\" ו\"חנון\" נחשבים שמות ממש, וכיצד תוכל שבועה או קללה לחול ביחס לאלה!","\u0003אמר אביי: מתניתין\u0004 \u0005[משנתנו]\u0006 יש להבינה כאילו \u0003במי שהוא חנון,\u0004"],["\u0003במי שהוא רחום קאמר\u0004 \u0005[הוא אומר],\u0006 שאף ש\"חנון\" ו\"רחום\" אינם שמות, מובן שהכוונה היא לשבועה בשם.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: אי הכי\u0004 \u0005[אם כך],\u0006 בדין הקודם במשנה, כשמשביע אותם \u0003\"בשמים ובארץ\" נמי\u0004 \u0005[גם כן]\u0006 נפרש ש\u0003במי שהשמים והארץ שלו קאמר\u0004 \u0005[הוא אומר],\u0006 ומדוע שנינו שפטורים?","ודוחים: \u0003הכי השתא\u0004 \u0005[כך אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם],\u0006 \u0003כיון דליכא מידי אחרינא דאיקרי\u0004 \u0005[שאין דבר אחר שנקרא]\u0006 \u0003רחום וחנון, ודאי\u0004 \u0003במי שהוא חנון, ודאי במי שהוא רחום קאמר\u0004 \u0005[הוא אומר].\u0006 \u0003הכא\u0004 \u0005[כאן],\u0006 \u0003כיון דאיכא\u0004 \u0005[שיש]\u0006 \u0003שמים וארץ,\u0004 שמא כשאומר \"משביעכם אני בשמים ובארץ\", \u0003בשמים ובארץ\u0004 ממש \u0003קאמר\u0004 \u0005[הוא אומר]\u0006 ולא בבורא שמים וארץ.","מתוך שהוזכרו שמות נמחקים ושאינם נמחקים דנים בפרטי הדברים. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כתב אלף למד מ\u0004שם \u0003\"אלהים\", \"יה\" מ\u0004תוך \u0003יי\u0004 (שם הויה) — \u0003הרי זה אינו נמחק,\u0004 אבל אם כתב \u0003שין דלת מ\"שדי\", אלף דלת מ\"אדני\", צדי בית מ\"צבאות\"\u0004 — \u0003הרי זה נמחק.\u0004","\u0003ר' יוסי אומר: \"צבאות\" כולו נמחק, שלא נקרא צבאות אלא על שם ישראל,\u0004 ואין זה שם לעצמו, \u0003שנאמר: \"והוצאתי את צבאתי את עמי בני ישראל מארץ מצרים\"\u0004 (שמות ז, ד). \u0003אמר שמואל: אין הלכה כר' יוסי.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כל הטפל לשם\u0004 כלומר, כל אות שימוש הקשורה לאחד מן השמות שאינם נמחקים, \u0003בין מלפניו ובין מלאחריו\u0004 — \u0003הרי זה נמחק. לפניו כיצד?\u0004 אם כתב \u0003\"ליי' \"\u0004— \u0003ל' נמחק, \"ביי' \"\u0004— \u0003ב' נמחק, \"ויי' \"\u0004— \u0003ו' נמחק, \"מיי' \"\u0004— \u0003מ' נמחק, \"שיי' \"\u0004— \u0003ש' נמחק, \"היי' \"\u0004— \u0003ה' נמחק, \"כיי' \"\u0004— \u0003כ' נמחק.\u0004","\u0003לאחריו כיצד?\u0004 אם כתב \u0003\"אלהינו\"\u0004 — \u0003נ\"ו נמחק, \"אלהיהם\"\u0004 — \u0003ה\"ם נמחק, \"אלהיכם\"\u0004 — \u0003כ\"ם נמחק. אחרים אומרים:\u0004 מה שכתוב \u0003לאחריו אינו נמחק, שכבר קדשו השם\u0004 שהוא כחלק ממנו. \u0003אמר רב הונא: הלכה כאחרים.\u0004","(סימן להלכות הבאות: \u0003אברהם דלטיא לנבות בגבעת בנימן שלמה דניאל, סימן).\u0004","\u0003כל שמות\u0004 של קודש \u0003האמורים בתורה באברהם\u0004 — כולם הם שמות \u0003קדש, חוץ מ\u0004שם \u0003זה שהוא חול, שנאמר: \"ויאמר יי' אם נא מצאתי חן בעיניך\"\u0004 (בראשית יח, ג), שכוונתו היא לשון רבים, למלאכים.","\u0003חנינא בן אחי ר' יהושע ור' אלעזר בן עזריה משום ר' אלעזר המודעי אמרו: אף זה קדש.\u0004 ואומרים: \u0003כמאן אזלא הא\u0004 \u0005[כ\u0006שיטת \u0005מי הולכת זו]\u0006 ש\u0003אמר רב יהודה אמר רב: גדולה הכנסת אורחין יותר מהקבלת פני שכינה,\u0004 שהרי אמר אברהם לה' שימתין לו עד שיכניס את האורחים, \u0003כמאן\u0004 \u0005[כ\u0006שיטת \u0005מי]?\u0006 \u0003כאותו הזוג\u0004 שהם מפרשים ששם זה הוא שם קודש.","\u0003כל שמות האמורים בלוט\u0004 — \u0003חול,\u0004 שכוונתו למלאכים, \u0003חוץ מזה שהוא קדש, שנאמר: \"ויאמר לוט אלהם אל נא אדני הנה נא מצא עבדך חן בעיניך\u0004 ותגדל את חסדך אשר עשית עמדי להחיות את נפשי\" (בראשית יט, יח— יט), שמתוך הפסוק נראה שהוא מדבר ל\u0003מי שיש בידו להמית ולהחיות, זה הקדוש ברוך הוא.\u0004","\u0003כל שמות האמורים בנבות\u0004 כגון \"ברך נבות אלהים ומלך\" (מלכים א כא, יג) — כולם שמות \u0003קדש\u0004 הם. וכל שמות האמורים \u0003במיכה\u0004 ובפסל שעשה (ראה שופטים פרקים יז— יח) — \u0003חול,\u0004 שהכוונה לעבודה זרה. \u0003ר' אליעזר אומר:\u0004 השמות האמורים \u0003בנבות\u0004 — \u0003קדש, במיכה\u0004 — \u0003יש מהן חול ויש מהן קדש,\u0004 אם כתוב השם ב\u0003אלף למד\u0004 (אלהים) — הרי זה שם \u0003חול,\u0004 שהכוונה לעבודה זרה, אם כתוב ב\u0003יוד הי\u0004 (שם הויה) — \u0003קדש, חוץ מזה ש\u0004הוא ב\u0003אלף למד והוא קדש,\u0004 והוא מה שנאמר: \u0003\"כל ימי היות בית האלהים בשילה\"\u0004 (שופטים יח, לא).","\u0003כל שמות האמורים בגבעת בנימין\u0004 ששאלו בה' אם לצאת למלחמה (ראה שופטים פרק כ) — \u0003ר' אליעזר אומר: חול,\u0004 שאין הכוונה שם לקדוש ברוך הוא, אלא לאלילים שהיו להם. \u0003ר' יהושע אומר: קדש.\u0004","\u0003אמר לו ר' אליעזר:\u0004 כיצד יכול אתה לומר שהוא קודש? \u0003וכי\u0004 הקדוש ברוך הוא \u0003מבטיח ואינו עושה?\u0004 והרי פעמיים עלו למלחמה והוכו!","\u0003אמר לו ר' יהושע: מה שהבטיח\u0004 הקדוש ברוך הוא \u0003עשה,\u0004 ובכל פעם ענה למה ששאלו, \u0003ו\u0004בפעמים הראשונות כששאלו באורים ותומים \u0003הם לא ביחנו\u0004 (שאלו, בדקו) \u0003אם\u0004 הם עומדים \u0003לנצוח\u0004 (לנצח במלחמה) \u0003אם לנצח\u0004 (להיות מנוצחים), ו\u0003ב\u0004פעם ה\u0003אחרונה שביחנו\u0004 (בדקו דבר זה) האם יעלו ויצליחו או לא, \u0003הסכימו על ידן, שנאמר: \"ופנחס בן אלעזר בן אהרן (הכהן) עמד לפניו בימים ההם לאמר האוסף עוד לצאת למלחמה עם [בני] בנימן אחי אם אחדל\u0004 ויאמר ה' עלו כי מחר אתננו בידך\" (שופטים כ, כח).","\u0003כל \"שלמה\" האמורין בשיר השירים\u0004 הם \u0003קדש,\u0004 כגון \"שיר השירים אשר לשלמה\", וכוונתו \u0003שיר למי שהשלום שלו, חוץ מ\u0004פסוק \u0003זה: \"כרמי שלי לפני, האלף לך שלמה\"\u0004 (שיר השירים ח, יב), כלומר, אלף הם של המלך \u0003שלמה לדידיה\u0004 \u0005[לעצמו],\u0006 \u0003\"ומאתים לנטרים את פריו\"\u0004 (שיר השירים ח, יב) שהם \u0003רבנן\u0004 \u0005[חכמים].\u0006 \u0003ויש אומרים: אף\u0004 פסוק \u0003זה\u0004 בשיר השירים \u0003חול,\u0004 שנאמר בו: \u0003\"הנה מטתו שלשלמה ששים\u0004 גבורים סביב לה\" (שיר השירים ג, ז).","ושואלים: \u0003אף\u0004 כתוב \u0003זה\u0004 חול, \u0003ולא מיבעי האיך\u0004 \u0005[נצרך לומר האחר]\u0006 הפסוק הקודם שהובא? \u0003אלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר\u0004 \u0003שמואל: מלכותא דקטלא חד משיתא בעלמא לא מיענשא\u0004 \u0005[מלכות שהורגת אחד משישה מבני העולם אינה נענשת]\u0006 משום שזה חלק מכוח המלכות, \u0003שנאמר: \"כרמי שלי לפני, האלף לך שלמה\",\u0004 שכוונתו \u0003למלכותא דרקיעא\u0004 \u0005[למלכות השמים],\u0006 שאלף שייכים לקב\"ה, \u0003\"ומאתים לנטרים את פריו\"\u0004 — \u0003למלכותא דארעא\u0004 \u0005[למלכות הארץ],\u0006 ואם כן יוצא ש\u0003שמואל\u0004 שמפרש שה\"אלף לך שלמה\" כוונתו הקדוש ברוך הוא, \u0003לא\u0004 סבור לא \u0003כתנא קמא ולא כיש אומרים,\u0004 שלכאורה שניהם מודים ש\"האלף לך שלמה\" הוא חול!","\u0003אלא הכי קאמר\u0004 \u0005[כך הוא אומר],\u0006 \u0003ויש אומרים:\u0004 שם \u0003זה\u0004 של \"האלף לך שלמה\" \u0003קדש, וזה הוא חול\u0004 — הפסוק האחר שמדבר ב\u0003\"מטתו\", ו\u0004לפי זה \u0003שמואל\u0004 ש\u0003אמר\u0004 הוא \u0003כ\u0004דעת \u0003יש אומרים.\u0004","\u0003כל מלכיא\u0004 \u0005[המלכים]\u0006 \u0003האמורים בדניאל חול,\u0004 וכוונתם מלכים סתם, \u0003חוץ מזה שהוא קדש,\u0004 שנאמר בו: \u0003\"אנת מלכא [מלך] מלכיא די אלה שמיא מלכותא חסנא ותקפא ויקרא יהב לך\"\u0004 (דניאל ב, לז);","\u0003ויש אומרים: אף זה קדש, שנאמר: \"מרי חלמא לשנאך ופשרה לערך\"\u0004 (דניאל ד, טז), שיש לשאול \u0003למאן קאמר\u0004 \u0005[למי הוא אומר]\u0006 את הדבר הזה? \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 שכאשר הוא אומר \"מרי\" \u0003לנבוכד נצר קאמר ליה\u0004 \u0005[אומר לו],\u0006 והרי \u0003שנאותיה מאי נינהו\u0004 \u0005[שונאיו מי הם]?\u0006 \u0003ישראל, מילט קא לייט להו\u0004 \u0005[\u0006וכי הוא \u0005מקלל אותם]\u0006 את \u0003ישראל? ו\u0004מצד שני,","\u0003תנא קמא\u0004 הסבור ש\"מרי\" פה כוונתו נבוכדנצר, \u0003סבר\u0004 \u0005[סבור]:\u0006 וכי \u0003שונאי ישראל איכא\u0004 \u0005[יש]\u0006 לנבוכדנצר, \u0003שונאי גוים ליכא\u0004 \u0005[אין]?\u0006 הרי היו לו גם שונאים שלא היו ישראל, ועליהם דיבר דניאל.","שנינו במשנה: \u0003ובכל כנויין\u0004 — \u0003הרי אלו חייבין\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה מברייתא\u0005]:\u0006 הכתוב \u0003\"יתן ה' אותך לאלה ולשבעה\"\u0004 (במדבר ה, כא) \u0003מה תלמוד לומר? והלא כבר נאמר\u0004 בתחילת הפסוק: \u0003\"והשביע הכהן את האשה בשבעת האלה\"!\u0004 ומשיבים: \u0003לפי שנאמר\u0004 בשבועת העדות: \u0003\"ושמעה קול אלה\"\u0004 (ויקרא ה, טו) יש ללמוד כך: \u0003נאמר כאן\u0004 בעדות \u0003\"אלה\", ונאמר להלן\u0004 בסוטה \u0003\"אלה\", מה להלן\u0004 בסוטה מדובר ב\u0003שבועה, אף כאן\u0004 בעדות מדובר ב\u0003שבועה,\u0004 וכן \u0003מה להלן\u0004 השבועה היא \u0003בשם אף כאן בשם.\u0004 והרי זה שלא כמשנתנו, לפיה שבועת העדות היא גם בכינויים!","\u0003אמר אביי, לא קשיא\u0004 \u0005[אין זה קשה]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 הברייתא, כדברי \u0003ר' חנינא בר אידי, הא רבנן\u0004 \u0005[זו,\u0006 משנתנו, כדברי \u0005חכמים].\u0006 \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' חנינא בר אידי אומר: הואיל ואמרה תורה\u0004 במקרים מסויימים \u0003השבע, ו\u0004במקרים אחרים אמרה \u0003אל תשבע,\u0004 וכן אמרה \u0003קלל ו\u0004אמרה \u0003אל תקלל, מה השבע\u0004 שאמרה תורה הוא \u0003בשם, אף\u0004 כשאמרה \u0003לא תשבע\u0004 הוא \u0003בשם,\u0004 וכן \u0003מה\u0004 במקום שנאמר \u0003קלל\u0004 הוא \u0003בשם אף לא תקלל\u0004 הוא \u0003בשם.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים]\u0006 החולקים על ר' חנינא בר אידי, \u0003אי גמירי\u0004 \u0005[אם\u0006 הם \u0005למודים במסורת]\u0006 \u0003גזירה שוה\u0004 זו מסוטה לשבועת העדות, אם כן \u0003ניבעי\u0004 \u0005[שנצטרך]\u0006 שתהא שבועת העדות והקללה דווקא ב\u0003שם המיוחד, אי לא גמירי\u0004 \u0005[אם\u0006 הם \u0005לא למודים]\u0006 \u0003גזירה שוה,\u0004 זו, אם כן \u0003אלה\u0004 האמורה בשבועת העדות ש\u0003שבועה היא מנא להו\u0004 \u0005[מנין להם]?\u0006","ומשיבים: \u0003נפקא להו מדתניא\u0004 \u0005[לומדים הם\u0006 דבר זה \u0005מ\u0006מה \u0005ששנויה\u0006 ברייתא\u0005]\u0006 בענין שבועת העדות: \"ושמעה קול \u0003אלה\"\u0004 (ויקרא ה,א) — \u0003אין אלה אלא לשון שבועה, וכן הוא אומר: \"והשביע הכהן את האשה בשבועת האלה\"\u0004 (במדבר ה, כא).","ומקשים: \u0003התם\u0004 \u0005[שם]\u0006 לא נאמרה \"אלה\" סתם, אלא \u0003\"שבועת האלה\" כתיב\u0004 \u0005[נאמר],\u0006 ומשמע שאלה עצמה אינה שבועה! ומסבירים: \u0003הכי קאמר\u0004 \u0005[כך הוא אומר]:\u0006 \u0003\"אלה\"\u0004 — \u0003אין אלה אלא בשבועה, וכן הוא אומר:\u0004 \u0003\"והשביע הכהן את האשה בשבעת האלה\".\u0004"],["\u0003ומנין לעשות אלה שאין עמה שבועה כאלה שיש עמה שבועה, ושבועה שאין עמה אלה כשבועה שיש עמה אלה? תלמוד לומר: \"ושמעה קול אלה\"\u0004 (ויקרא ה, א), שהצירוף \"קול אלה\" הוא כמיותר, ויש לפרשו כאילו נכתב: \u0003\"ושמעה אלה\", \"ושמעה קול\".\u0004","\u0003אמר ר' אבהו: מנין לאלה שהיא שבועה? שנאמר:\u0004 \"ויקח מזרע המלוכה וכו' \u0003ויבא אתו באלה\" וגו'\u0004 (יחזקאל יז, יג), \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בצדקיהו \u0005:\u0006 \u0003\"וגם במלך נבוכדנצר מרד אשר השביעו באלהים\"\u0004 (דברי הימים ב לו, יג). משמע ש\"אלה\" הנזכרת ביחזקאל — שבועה היא.","אגב כך מביאים בנושאים דומים. \u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003\"ארור\"\u0004 — \u0003בו\u0004 יש לשון \u0003נידוי, בו\u0004 יש לשון \u0003קללה, בו\u0004 לשון \u0003שבועה.\u0004","ומפרטים: \u0003בו נידוי\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בשירת דבורה: \u0003\"אורו מרוז אמר מלאך ה' ארו ארור ישביה\"\u0004 (שופטים ה, כג), \u0003ואמר עולא: בארבע מאה שיפורי שמתיה\u0004 \u0005[ב\u0006תקיעה של \u0005ארבע מאות שופרות\u0006 נידה, \u0005החרים אותו]\u0006 \u0003ברק ל\u0004עיר \u0003מרוז,\u0004 כדרך שעושים בנידוי, הרי שארור הוא נידוי.","\u0003בו קללה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ואלה יעמדו על הקללה\"\u0004 (דברים כז, יג), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ארור האיש אשר יעשה פסל\" וגו'\u0004 (דברים כז, טו).","\u0003בו שבועה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וישבע יהושע בעת ההיא לאמר ארור האיש לפני ה'\u0004 אשר יקום ובנה את העיר הזאת את יריחו\" (יהושע ו, כו). ושואלים: \u0003ודלמא תרתי עבד להו\u0004 \u0005[ושמא שני\u0006 דברים יחד \u0005עשה להם]\u0006 יהושע, \u0003אשבעינהו ולייטינהו\u0004 \u0005[השביע אותם וקילל אותם]!\u0006","\u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 הראיה: שנאמר \u0003\"ואיש ישראל נגש ביום ההוא ויאל שאול את העם לאמר ארור האיש אשר יאכל\u0004 לחם עד הערב ונקמתי מאויבי\" (שמואל א יד, כד), \"ויואל\" — מלשון אלה ושבועה, \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהונתן לא שמע בהשביע אביו את העם\"\u0004 (שמואל א יד כז), הרי ש\"ארור\" הוא שבועה. ושואלים: \u0003ודלמא הכא נמי תרתי עבד להו\u0004 \u0005[ושמא גם כאן שנים\u0006 דברים \u0005עשה להם]\u0006 שאול, \u0003אשבעינהו ולייטינהו\u0004 \u0005[השביע אותם וקילל אותם]!\u0006","ומתרצים: \u0003מי כתיב\u0004 \u0005[האם נאמר שם]\u0006 \u0003\"וארור\"\u0004 בו' החיבור? אלא כתוב \"ארור\", משמע שהוא הפירוט של \"ויואל\". ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכאן],\u0006 לתירוץ זה, \u0003התם נמי\u0004 \u0005[שם גם כן]\u0006 בפסוק האמור ביהושע, אפשר לתרץ כן: \u0003לא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"וארור\"\u0004 אלא \"ארור\", משמע שהוא אותו ענין.","ובדומה לזה \u0003אמר ר' יוסי בר' חנינא: \"אמן\"\u0004 — \u0003בו\u0004 לשון \u0003שבועה, בו\u0004 לשון \u0003קבלת דברים\u0004 והסכמה להם, \u0003בו האמנת דברים,\u0004 שהוא מאמין ומתפלל לקיום הדברים.","ומפרט: \u0003בו שבועה\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"והשביע הכהן את האשה... \u0003ואמרה האשה אמן אמן\"\u0004 (במדבר ה, כב),","ואמירת \"אמן\" כאן היא שבועתה של האשה עצמה. \u0003בו קבלת דברים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ארור אשר לא יקים את דברי התורה הזאת לעשות אותם ואמר כל העם אמן\"\u0004 (דברים כז, כו),","שמקבלים עליהם לקיים כל אלה. \u0003בו האמנת דברים\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ויאמר ירמיה [הנביא] (אל חנניהו) אמן כן יעשה ה' יקם ה' את דבריך\"\u0004 (ירמיהו כח, ו). כלומר, ולוואי שכך יהיה.","\u0003אמר ר' אלעזר: \"לאו\"\u0004 יכול להיות לשון \u0003שבועה,\u0004 וכן \u0003\"הן\"\u0004 הוא לשון \u0003שבועה.\u0004 ומעירים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003\"לאו\"\u0004 שהוא \u0003שבועה, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא יהיה עוד המים למבול\"\u0004 (בראשית ט, טו), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"כי מי נח זאת לי אשר נשבעתי\"\u0004 (ישעיהו נד, יט), והיכן נשבע? אלא שאמירת \"לא יהיה\" כמוה כשבועה. \u0003אלא \"הן\"\u0004 שהוא \u0003שבועה, מנא לן\u0004 \u0005[מנין לנו]?\u0006 ומשיבים: \u0003סברא הוא\u0004 בדבר, \u0003מ\u0004כיון ש\u0003\"לאו\"\u0004 הוא \u0003שבועה, \"הן\" נמי\u0004 \u0005[גם כן]\u0006 \u0003שבועה.\u0004","\u0003אמר רבא: והוא\u0004 ש\u0003אמר \"לאו\" \"לאו\" תרי זימני\u0004 \u0005[שתי פעמים].\u0006 \u0003והוא\u0004 ש\u0003אמר \"הן\" \"הן\" תרי זימני\u0004 \u0005[שתי פעמים].\u0006 וכן יש להוכיח מן מקראות, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ולא יכרת כל בשר עוד ממי המבול\"\u0004 (בראשית ט, יא) ואחר כך חזר ואמר: \u0003\"ולא יהיה עוד המים למבול\"\u0004 (בראשית ט טו), \u0003ומ\u0004כיון ש\u0003\"לאו\"\u0004 הוא \u0003תרי זימני\u0004 \u0005[שתי פעמים],\u0006 \u0003\"הן\" נמי תרי זימני\u0004 \u0005[גם כן שתי פעמים].\u0006","שנינו במשנה: \u0003המקלל\u0004 את השם \u0003בכולן\u0004 (בכל השמות והכינויים) — \u0003חייב, דברי ר' מאיר, וחכמים פוטרין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 נאמר \u0003\"איש [איש] כי יקלל אלהיו ונשא חטאו\"\u0004 (ויקרא כד, טו), \u0003מה תלמוד לומר\u0004 בפסוק זה? \u0003והלא כבר נאמר: \"ונקב שם ה' מות יומת\"\u0004 (ויקרא כד טז)! ומסבירים: \u0003יכול לא יהא חייב אלא על שם המיוחד בלבד,\u0004 שם הויה, \u0003מנין לרבות את הכינויין? תלמוד לומר: \"איש איש כי יקלל אלהיו\" וגו'\u0004 — \u0003מכל מקום,\u0004 אף שלא בשם המיוחד. אלו \u0003דברי ר' מאיר. וחכמים אומרים: על שם מיוחד\u0004 — חייב \u0003במיתה\u0004 כמפורש בכתוב, \u0003ועל הכינויין\u0004 שמקלל — חייב רק \u0003באזהרה\u0004 (באיסור לאו), אבל אין בזה חיוב מיתה.","ועוד שנינו במשנה: \u0003והמקלל אביו ואמו\u0004 בכינויים — חייב, דברי ר' מאיר, וחכמים פוטרים. ושואלים: \u0003מאן\u0004 \u0005[מי הם]\u0006 ה\u0003חכמים\u0004 הנזכרים כאן?","ומשיבים: שיטת \u0003ר' מנחם בר יוסי\u0004 היא. \u0003דתניא\u0004 \u0005[ששנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' מנחם בר יוסי אומר:\u0004 נאמר במקלל את השם \u0003\"בנקבו שם יומת\"\u0004 (ויקרא כד, טז), \u0003מה תלמוד לומר \"שם\"?\u0004 והרי כבר נאמר בתחילת פסוק זה \"ונוקב שם ה' יומת\"! \u0003לימד\u0004 יתור זה גם \u0003על המקלל אביו ואמו, שאינו חייב\u0004 סקילה \u0003עד שיקללם בשם.\u0004","ועוד שנינו במשנה: \u0003והמקלל עצמו וחבירו\u0004 בכל הכינויים עובר בלא תעשה. \u0003אמר ר' ינאי: ודברי הכל\u0004 הם, וגם חכמים הסבורים במקלל את השם ומקלל אביו ואמו שאינו חייב אלא בשם המיוחד, גם הם מודים שבזה חייב מלקות כשמקלל בכינויים. ומביאים את המקור בתורה לאיסורים אלה.","האיסור לקלל את \u0003עצמו\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"רק השמר לך ושמר נפשך מאד\"\u0004 (דברים ד, יט), ויש להבין זאת \u0003כ\u0004דברי \u0003ר' אבין אמר ר' אילעא,\u0004 ש\u0003אמר: כל מקום שנאמר \"השמר\"\u0004 או \u0003\"פן\"\u0004 או \u0003\"אל\"\u0004 — \u0003אינו אלא\u0004 למצוות של \u0003לא תעשה,\u0004 ולכן הפוגע בעצמו, על ידי הקללה, עובר בלאו. \u0003ו\u0004מקלל \u0003חבירו\u0004 — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"לא תקלל חרש\"\u0004 (ויקרא יט, יד), והוא הדין לכל אדם.","שנינו במשנה: \u0003\"יכך ה' אלהים\", וכן \"יככה אלהים\"\u0004 — \u0003זו היא אלה הכתובה בתורה.\u0004 מסופר \u0003יתיב\u0004 \u0005[יושב היה]\u0006 \u0003רב כהנא קמיה\u0004 \u0005[לפני]\u0006 \u0003רב יהודה, ויתיב וקאמר הא מתניתין כדתנן\u0004 \u0005[ויושב היה ואומר\u0006 את \u0005המשנה הזו כמו ש\u0006היא \u0005שנויה],\u0006 בדיוק בלשון הזו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יהודה: \u0003כנה\u0004 כלומר, אל תאמר לשון זו, אלא אמור אותם בכינוי (\"יכהו ה' \") שלא תישמע כמקלל את רבך.","ומביאים עוד מעשה דומה, \u0003יתיב ההוא מרבנן קמיה\u0004 \u0005[יושב היה אחד מהחכמים לפני]\u0006 \u0003רב כהנא, ויתיב וקאמר\u0004 \u0005[ויושב היה ואומר]\u0006 פסוק זה בתוך לימודו: \u0003\"גם אל יתצך לנצח יחתך ויסחך מאהל ושרשך מארץ חיים סלה\"\u0004 (תהלים נב, ז), \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כנה.\u0004 אל תאמר כלשון הכתוב בלשון נוכח, אלא בגוף שלישי, נסתר.","ושואלים: \u0003תרתי\u0004 \u0005[פעמיים]\u0006 \u0003למה לי\u0004 לספר אותו ענין עצמו? ומשיבים: נחוץ זה המקרה השני, כי \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003הני מילי מתניתין\u0004 \u0005[דברים אלה\u0006 אמורים ב\u0005משנה]\u0006 שהעיקר בה הוא התוכן, ולא צירוף המילים, ולכן יכול לשנות את הלשון, \u0003אבל בקראי אימא לא מכנינן\u0004 \u0005[במקראות אמור\u0006 ש\u0005אין מכנים],\u0006 אלא אומרים אותם ככתבם, לכן \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 שגם כשהוא קורא מקרא יכול לכנות.","שנינו במשנה: האומר \u0003\"אל יכך, ויברכך, וייטיב לך\u0004 אם תבוא ותעיד\" — \u0003ר' מאיר מחייב\u0004 משום שבועת העדות, שהרי זה כאומר \"יכך אם לא תבוא ותעיד\", \u0003וחכמים פוטרין.\u0004","ותוהים: \u0003והא לית ליה\u0004 \u0005[והרי אין לו]\u0006 \u0003לר' מאיר\u0004 את השיטה הזו של \u0003מכלל לאו אתה שומע הן,\u0004 והוא מצריך לפרש בהסכם גם את צד החיוב וגם את צד השלילה! ואומרים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות, ואמור שכאן חכמים הם המחייבים ור' מאיר פוטר.","מסופר, \u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' יצחק\u0004 מארץ ישראל \u0003תנא כדתנן\u0004 \u0005[שנה כמו ששנינו\u0006 במשנתנו\u0005].\u0006 \u0003אמר רב יוסף: השתא דאנן תנן הכי\u0004 \u0005[עכשיו שאנו שונים כך]\u0006 כנוסח זה, \u0003וכי אתא\u0004 \u0005[וכאשר בא]\u0006 \u0003ר' יצחק תני הכי\u0004 \u0005[שנה\u0006 גם כן \u0005כך],\u0006 \u0003שמע מינה דוקא תנן\u0004 \u0005[מכאן אתה למד\u0006 ש\u0005בדיוק שנינו].\u0006 שכך הנוסחה האמיתית במשנה, שר' מאיר הוא המחייב.","ומתקשים: \u0003אלא קשיא\u0004 \u0005[קשה],\u0006 שהרי ר' מאיר אינו סובר שמכלל לאו אתה שומע הן! ומשיבים: \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 מכלל לאו אתה שומע הן, הרי זה \u0003ב\u0004ענייני \u0003ממונא\u0004 \u0005[ממונות],\u0006 \u0003אבל ב\u0004ענייני \u0003איסורא\u0004 \u0005[איסור]\u0006 והיתר — \u0003אית ליה\u0004 \u0005[יש לו],\u0006 ואדם מתחייב אף באופן זה.","ומקשים: \u0003הרי סוטה דאיסורא\u0004 \u0005[שאיסור]\u0006 \u0003הוא,\u0004 ושם נאמר רק מה יעשה לאשה אם לא חטאה, ולא נאמר צד השלילה.","והקשינו על כך על שיטת ר' מאיר, \u0003ואמר ר' תנחום בר חכינאי\u0004 כדי לתרץ את הדברים: \u0003\"הנקי\" כתיב\u0004 \u0005[כתוב]\u0006 (במדבר ה, יט), שאנו דורשים אותו כאילו נאמר \"חנקי\". ויש לדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום \u0003דכתיב\u0004 \u0005[שכתוב]\u0006 \u0003\"הנקי\",\u0004 מובן הדבר לשיטת ר' מאיר, \u0003הא לאו הכי\u0004 \u0005[הרי בלא זה]\u0006 \u0003מכלל לאו אתה שומע הן לא אמרינן\u0004 \u0005[אומרים אנו],\u0006 ואף שמדובר באיסור!"],["\u0003אלא\u0004 בכל זאת \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות במשנתנו, ואמור שר' מאיר הוא הפוטר, \u0003אפילו באיסורא לית ליה\u0004 \u0005[באיסור אין לו]\u0006 מכלל לאו אתה שומע הן.","\u0003מתקיף ליה\u0004 \u0005[מקשה על כך]\u0006 \u0003רבינא: ובאיסורא לית ליה\u0004 \u0005[וב\u0006ענייני \u0005איסורים אין לו]\u0006 מכלל לאו אתה שומע הן? \u0003אלא מעתה, שתויי יין ופרועי ראש\u0004 שדינם \u0003במיתה, הכי נמי דלית ליה\u0004 \u0005[כך גם כן שאין לו]\u0006 \u0003לר' מאיר\u0004 הלכה זו? שהרי אין הדבר מפורש בלשון זו בכתוב, ונלמד רק בדרך מכלל לאו אתה שומע הן. \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005],\u0006 \u0003אלו שבמיתה: שתויי יין ופרועי ראש,\u0004 ולא נחלקו בזה כלל!","\u0003אלא לעולם תיפוך\u0004 \u0005[תהפוך]\u0006 את השיטות במשנתנו, ואמור שלדעת ר' מאיר אין אומרים מכלל לאו אתה שומע הן, ואולם \u0003כי לית ליה\u0004 \u0005[כאשר אין לו]\u0006 לר' מאיר מכלל לאו אתה שומע הן — הרי זה \u0003ב\u0004ענין \u0003ממונא\u0004 \u0005[ממון],\u0006 אבל \u0003באיסורא אית ליה\u0004 \u0005[באיסור יש לו],\u0006 ומשום כך אינו חולק בענין שתויי יין, \u0003ושאני\u0004 \u0005[ושונה]\u0006 \u0003סוטה\u0004 שאינו סבור בעניינה מכלל לאו אתה שומע הן, למרות שהוא איסור — משום \u0003דאיסורא דאית ביה ממונא\u0004 \u0005[שאיסור שיש בו ממון]\u0006 \u0003הוא,\u0004 שהרי יש בזה השלכות לענין תשלום כתובתה.","","\u0003שבועת הפקדון\u0004 שנשבע לשקר שאין בידו פקדון של חבירו (או כל ממון אחר שחבירו תובעו). ודיניה מפורשים בכתוב (ויקרא ה, כ—כו) שמשיב את החפץ לבעליו בתוספת חומש, ומביא קרבן אשם, \u0003נוהגת באנשים ובנשים, ברחוקים ובקרובים\u0004 גם אם בעל הפקדון (המשביע) קרוב לנפקד, \u0003בכשרים ובפסולים,\u0004 בין","\u0003בפני בית דין ו\u0004בין \u0003שלא בפני בית דין\u0004 — \u0003מפי עצמו\u0004 כשנשבע הוא בעצמו, \u0003ו\u0004אם מושבע \u0003מפי אחרים, אינו חייב עד שיכפרנו בבית דין, דברי ר' מאיר.\u0004","\u0003וחכמים אומרים: בין מפי עצמו בין מפי אחרים\u0004 — \u0003כיון שכפר בו חייב,\u0004 ואפילו שלא בבית דין.","\u0003וחייב\u0004 קרבן \u0003על זדון השבועה, ו\u0004כן חייב \u0003על שגגתה\u0004 של השבועה, שאינו יודע שמתחייב על כך קרבן, \u0003עם זדון הפקדון,\u0004 שהוא יודע שהוא נשבע לשקר. \u0003ואינו חייב על שגגתה גרידתא\u0004 \u0005[בלבד],\u0006 אם שכח וחשב שבאמת אינו חייב לחבירו דבר. \u0003ומה חייב על זדונה?\u0004 קרבן \u0003אשם בכסף\u0004 שני \u0003שקלים\u0004 לפחות.","\u0003שבועת הפקדון כיצד? אמר לו: \"תן לי פקדוני שיש לי בידך\",\u0004 ואמר הנפקד: \u0003\"שבועה שאין לך בידי\"; או שאמר לו\u0004 הנפקד: \u0003\"אין לך בידי\",\u0004 ואמר לו המפקיד: \u0003\"משביעך אני\", ואמר: \"אמן\"\u0004 — \u0003הרי זה חייב\u0004 קרבן, אם שיקר.","\u0003השביע עליו חמש פעמים, בין בפני בית דין ובין שלא בפני בית דין, וכפר\u0004 — \u0003חייב על כל אחת ואחת. אמר ר' שמעון: מה טעם\u0004 הדבר? \u0003מפני שיכול לחזור ולהודות\u0004 בכל פעם, לאחר שנשבע, ולשלם, ואם כן בכל שבועה חוזר וכופר.","\u0003היו חמשה תובעים אותו, אמרו לו: \"תן לנו פקדון שיש לנו בידך\",\u0004 ואמר להם: \u0003\"שבועה שאין לכם בידי\"\u0004 — \u0003אינו חייב אלא\u0004 משום שבועה \u0003אחת.\u0004 אבל אמר להם \u0003\"שבועה שאין לך בידי, ולא לך, ולא לך\"\u0004 — \u0003חייב על כל אחת ואחת. ר' אליעזר אומר: עד שיאמר\u0004 לשון \u0003שבועה באחרונה,\u0004 שיאמר \"ולא לך ולא לך בשבועה\", שברור מכאן שנשבע לכל אחד. \u0003ר' שמעון אומר: עד שיאמר\u0004 לשון \u0003שבועה\u0004 במפורש \u0003לכל אחד ואחד:\u0004 \"...ושבועה שאין לך, ושבועה שאין לך\".","אמר לו חבירו: \u0003\"תן לי פקדון ותשומת יד גזל ואבידה שיש לי בידך\",\u0004 ואמר לו: \u0003\"שבועה שאין לך בידי\"\u0004 — \u0003אינו חייב אלא\u0004 משום שבועה \u0003אחת,\u0004 אבל אם נשבע לו: \u0003\"שבועה שאין לך בידי פקדון ותשומת יד וגזל ואבידה\"\u0004 — \u0003חייב על כל אחת ואחת.\u0004","אמר לו: \u0003\"תן לי חטין ושעורין וכוסמין שיש לי בידך\",\u0004 ואמר לו: \u0003\"שבועה שאין לך בידי\"\u0004 — \u0003אינו חייב אלא אחת,\u0004 ואם פירש: \u0003\"שבועה שאין לך בידי חטין ושעורין וכוסמין\"\u0004 — \u0003חייב על כל אחת ואחת. ר' מאיר אומר: אפילו אמר \"חטה ושעורה וכוסמת\"\u0004 — \u0003חייב על כל אחת ואחת.\u0004","אם אמר לו חבירו: \u0003\"אנסת ופיתית את בתי\", והוא אומר: \"לא אנסתי ולא פיתיתי\", \"משביעך אני\", ואמר: \"אמן\"\u0004 — \u0003חייב. ר' שמעון פוטר,\u0004 לפי \u0003שאינו משלם קנס על פי עצמו,\u0004 כיון שאם היה מודה לא היה מתחייב — אינו חייב על כפירתו. \u0003אמרו לו: אף על פי שאינו משלם קנס על פי עצמו,\u0004 מכל מקום הריהו \u0003משלם בשת ופגם על פי עצמו,\u0004 שהם תשלומי ממון ולא קנס, ועל כך הוא חייב.","וכיוצא בזה, אמר לחבירו: \u0003\"גנבת את שורי\", והוא אומר: \"לא גנבתי\", \"משביעך אני\", ואמר: \"אמן\"\u0004 — \u0003חייב\u0004 קרבן, אם שיקר, שהרי מתחייב גם על פי עצמו בהחזרת השור. אבל אם האשימו שגנב את שורו וטבחו או מכרו, ואמר האיש: \u0003\"גנבתי, אבל לא טבחתי ולא מכרתי\",\u0004 ואמר לו: \u0003\"משביעך אני\", ואמר: \"אמן\",\u0004 והיה הדבר שקר — \u0003פטור\u0004 על הארבעה והחמישה של טביחה ומכירה, משום שהם קנס.","טען כנגדו: \u0003\"המית שורך את שורי\", והוא\u0004 הנתבע \u0003אומר: \"לא המית\",\u0004 אמר לו: \u0003\"משביעך אני\" ואמר: \"אמן\"\u0004 — הרי זה \u0003חייב.\u0004 אבל אם אמר לו: \u0003\"המית שורך את עבדי\"\u0004 ואתה חייב לי קנס של שלושים שקלים, \u0003והוא אומר: \"לא המית\", \"משביעך אני\", ואמר: \"אמן\"\u0004 — הרי הוא \u0003פטור,\u0004 משום שהתשלום עבור העבד הוא קנס.","כיוצא בזה, \u0003אמר לו: \"חבלת בי ועשית בי חבורה\", והוא אומר: \"לא חבלתי ולא עשיתי בך חבורה\", \"משביעך אני\", ואמר: \"אמן\"\u0004 — הרי הוא \u0003חייב.\u0004 אבל אם \u0003אמר לו עבדו: \"הפלת את שיני וסימית את עיני\", והוא אומר: \"לא הפלתי ולא סימיתי\",\u0004 אמר לו העבד: \u0003\"משביעך אני\", ואמר: \"אמן\",\u0004 אף על פי ששיקר — \u0003פטור,\u0004 משום ששחרור העבד בגלל סיבה זו קנס הוא.","\u0003זה הכלל: כל המשלם על פי עצמו\u0004 כלומר, בהודאת עצמו — \u0003חייב, ושאינו משלם על פי עצמו\u0004 אלא רק על פי עדים — \u0003פטור\u0004 גם אם הוא כופר בדבר זה בשבועה.","\u0003רב אחא בר הונא ורב שמואל בריה\u0004 \u0005[בנו]\u0006 של \u0003רבה בר בר חנה ורב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה תנו\u0004 \u0005[שנו,\u0006 למדו\u0005]\u0006 מסכת \u0003שבועות בי\u0004 \u0005[בבית]\u0006 \u0003רבה, פגע בהו\u0004 \u0005[פגש אותם]\u0006 \u0003רב כהנא, אמר\u0004"],["\u0003להו\u0004 \u0005[להם]:\u0006 אם \u0003הזיד בשבועת הפקדון\u0004 שידע שהוא נשבע לשקר, ושאדם מתחייב על כך מן התורה, \u0003ו\u0004גם \u0003התרו בו, מהו\u0004 דינו? \u0003כיון\u0004 ש\u0003חידוש הוא\u0004 דין שבועת הפקדון, ש\u0003בכל התורה לא אשכחן\u0004 \u0005[מצאנו]\u0006 \u0003מזיד דמייתי\u0004 \u0005[שמביא]\u0006 \u0003קרבן\u0004 לכפרה, \u0003והכא\u0004 \u0005[וכאן]\u0006 מקרה מיוחד הוא שמזיד \u0003מייתי\u0004 \u0005[מביא]\u0006 \u0003קרבן,\u0004 אם כן בענין זה \u0003לא שנא אתרו ביה ולא שנא לא אתרו ביה\u0004 \u0005[אינו שונה\u0006 אם \u0005התרו בו ואינו שונה\u0006 אם \u0005לא התרו בו],\u0006 ומביא קרבן; \u0003או דלמא\u0004 \u0005[שמא]\u0006 נאמר כך: \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שמביא קרבן אמורים \u0003היכא דלא אתרו ביה\u0004 \u0005[במקום שלא התרו בו],\u0006 \u0003אבל היכא דאתרו ביה\u0004 \u0005[במקום שהתרו בו]\u0006 — \u0003מילקא לקי\u0004 \u0005[מלקות\u0006 הוא \u0005לוקה]\u0006 משום שעובר על לאו של שבועת שקר, \u0003קרבן לא מייתי\u0004 \u0005[מביא];\u0006 \u0003או דלמא הא והא עבדינא\u0004 \u0005[שמא זה וזה עושים\u0006 לו\u0005],\u0006 גם לוקה וגם מביא קרבן?","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 לרב כהנא, \u0003תנינא\u0004 \u0005[שנינו]\u0006 דבר זה בברייתא: \u0003חמורה הימנה\u0004 משבועת העדות \u0003שבועת הפקדון, שחייבין על זדונה מכות ועל שגגתה אשם בכסף שקלים,\u0004 ועל שבועת העדות אינו מביא אלא קרבן חטאת בין בשוגג ובין במזיד; \u0003מדקאמר ליה\u0004 \u0005[מכיון שאמר לו]\u0006 שחייב \u0003על זדונה מכות\u0004 — \u0003מכלל\u0004 הדברים אתה למד \u0003דאתרו ביה\u0004 \u0005[שהתרו בו],\u0006 שהרי אין מלקות בלא התראה, \u0003וקאמר\u0004 \u0005[והוא אומר]:\u0006 \u0003מכות\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 חייב על זדונה, \u0003קרבן\u0004 — \u0003לא.\u0004 ומכאן תשובה לשאלתו של רב כהנא.","ומסבירים לפי פירוש זה: \u0003ומאי חומרא\u0004 \u0005[ומה החומרה]\u0006 שבשבועת הפקדון שלוקה, \u0003דניחא ליה לאיניש דמייתי\u0004 \u0005[שנוח לו לאדם שיביא]\u0006 \u0003קרבן ולא לילקי\u0004 \u0005[ילקה].\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רבא בר איתי\u0004 על שהביאו ראיה מברייתא זו: \u0003מאן תנא\u0004 \u0005[מי שנה\u0006 ברייתא זו\u0005]\u0006 ש\u0003זדון שבועת הפקדון לא ניתן לכפרה\u0004 על ידי קרבן — זו שיטת \u0003ר' שמעון\u0004 היא, \u0003אבל לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 \u0003קרבן נמי מייתי\u0004 \u0005[גם כן מביא],\u0006 ואם כן אין לפתור את השאלה מכאן.","ומצד אחר \u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב כהנא\u0004 לחכמים: \u0003בר מינה דההיא\u0004 \u0005[חוץ ממנה מאותה\u0006 ברייתא\u0005]\u0006 אין להוכיח ממנה למה ששאלתי, \u0003דאנא תנינא לה\u0004 \u0005[שאני\u0006 הוא זה ש\u0005שניתי אותה]\u0006 כלומר, אני הבאתי אותה לבית המדרש, \u0003והכי תנינא לה\u0004 \u0005[וכך שניתי אותה],\u0006 בנוסח שונה: חמורה הימנה שבועת הפקדון, ש\u0003אחד זדונה ואחד שגגתה\u0004 — \u0003אשם בכסף שקלים, ומאי חומרא\u0004 \u0005[ומה החומרה\u0006 שבדבר\u0005]?\u0006 ש\u0003אילו התם\u0004 \u0005[שם]\u0006 על שבועת העדות, מביא \u0003חטאת\u0004 אפילו \u0003בת דנקא\u0004 \u0005[מעה,\u0006 ששווה שישית הדינר\u0005],\u0006 \u0003והכא\u0004 \u0005[וכאן]\u0006 מביא דווקא \u0003אשם בכסף\u0004 שני \u0003שקלים.\u0004","ושואלים: אם כן, \u0003וליגמר מינה\u0004 \u0005[וילמד ממנה]\u0006 תשובה לשאלתו, שבזדון שבועת הפקדון מביא קרבן ואינו לוקה! ודוחים: \u0003דלמא דלא אתרו ביה\u0004 \u0005[שמא\u0006 מדובר בברייתא זו כ\u0005שלא התרו בו],\u0006 אבל אם היו מתרים בו — שמא לוקה.","ומביאים \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת],\u0006 \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו במשנתנו: \u0003אין חייבין על שגגתה\u0004 של שבועת הפקדון, \u0003מה הן חייבין על זדונה? אשם בכסף שקלים; מאי לאו בדאתרו ביה\u0004 \u0005[האם לא\u0006 מדובר \u0005ב\u0006מקרה \u0005שהתרו בו]\u0006 ובכל זאת מביא קרבן? ודוחים: \u0003הכא נמי דלא אתרו ביה\u0004 \u0005[כאן גם כן\u0006 מדובר \u0005שלא התרו בו].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מברייתא ששנו בה: \u0003לא, אם אמרת בנזיר טמא שכן לוקה, תאמר בשבועת הפקדון שאינו לוקה? מדקאמר\u0004 \u0005[ממה שהוא אומר]\u0006 בנזיר ש\u0003לוקה\u0004 — \u0003מכלל\u0004 הדברים אתה למד שמדובר במקרה \u0003דאתרו ביה\u0004 \u0005[שהתרו בו],\u0006 שהרי אין לוקים בלא התראה, \u0003וקאמר\u0004 \u0005[ואמר]:\u0006 \u0003תאמר בשבועת הפקדון שאינו לוקה, אבל קרבן מייתי\u0004 \u0005[מביא]!\u0006","ודוחים: אל תבין כמו שהבנת, אלא \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אינו לוקה\"\u0004 בשבועת פקדון? ש\u0003אינו נפטר במלקות\u0004 בלבד, אלא צריך להביא גם קרבן. ותוהים: \u0003מכלל\u0004 הדברים אתה רוצה לומר ש\u0003נזיר טמא נפטר במלקות\u0004 בלבד? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003קרבן כתיב ביה\u0004 \u0005[כתוב בו]\u0006 במפורש! ומשיבים: הקרבן שמביא הנזיר הטמא אינו לכפרת חטאו, אלא \u0003התם דמייתי\u0004 \u0005[שם שמביא]\u0006 \u0003קרבן,\u0004 הרי זה \u0003כי היכי דתיחול עליה\u0004 \u0005[כדי שתחול עליו]\u0006 \u0003נזירות בטהרה,\u0004 והיא חלק מדין הנזירות, שהרי קרבן זה מביא גם אם נטמא באונס.","מסופר, \u0003אמרוה רבנן\u0004 \u0005[חכמים]\u0006 את הענין הזה \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003רבה,\u0004 שסיפרו לו את שאלת רב כהנא, מה דינו של המזיד בשבועת הפקדון והתרו בו, האם הוא חייב קרבן. \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003מכלל\u0004 הדברים אתה מסיק \u0003דכי לא אתרו ביה\u0004 \u0005[שכאשר לא התרו בו],\u0006 \u0003ואיכא\u0004 \u0005[ויש]\u0006 \u0003עדים\u0004 שהוא חייב לחבירו, \u0003מיחייב\u0004 \u0005[חייב הוא]\u0006 בקרבן? הלוא \u0003כפירת דברים בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 כשנשבע, ולא כפירת ממון, שהרי העדים ממילא מחייבים אותו ממון, ועל כפירה שאין בה משמעות ממונית אינו חייב בקרבן! ומעירים, \u0003אלמא קסבר\u0004 \u0005[מכאן יוצא\u0006 ש\u0005סבור]\u0006 \u0003רבה: הכופר בממון שיש עליו עדים\u0004 — הרי זה \u0003פטור,\u0004 כיון שהוא חייב לשלם בגלל העדים, ואין ממש בכפירתו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חנינא לרבה, תניא דמסייע לך\u0004 \u0005[שנויה\u0006 ברייתא \u0005המסייעת לך\u0006 לשיטתך\u0005]\u0006 על מה שנאמר בשבועת הפקדון: \u0003\"וכחש בה\"\u0004 (ויקרא ה, כב) — \u0003פרט למודה לאחד מן האחין או לאחד מן השותפין,\u0004 אף שכופר באחים או בשותפים האחרים. \u0003\"ונשבע על שקר\"\u0004 (ויקרא ה, כב) — \u0003פרט ללוה בשטר ו\u0004כן \u0003ללוה בעדים,\u0004 הרי שעל ממון שיש עליו עדים אינו מתחייב משום שבועת הפקדון.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 \u0003לא תסייען\u0004 \u0005[תסייע לנו],\u0006 כי יש להסביר שבברייתא מדובר \u0003באומר\u0004 אותו אדם \u0003\"לויתי\u0004 אבל \u0003לא לויתי בעדים\",\u0004 או \u0003\"לויתי ולא לויתי בשטר\",\u0004 שאינו כופר בממון עצמו שהוא חייב, אלא טוען טענה אחרת, ולכן פטור משום שבועת הפקדון.","\u0003ממאי\u0004 \u0005[ממה]\u0006 אתה מבין שכך הוא? \u0003מדקתני\u0004 \u0005[ממה ששנה]\u0006 תחילה בברייתא: \u0003\"וכחש בה\"\u0004 — \u0003פרט למודה לאחד מן האחין או לאחד מן השותפין.\u0004 ונברר: \u0003האי\u0004 \u0005[זה]\u0006 שאמר שמודה \u0003לאחד מן האחין היכי דמי\u0004 \u0005[איך היה הדבר]?\u0006 \u0003אילימא דאודי ליה בפלגא דידיה\u0004 \u0005[אם תאמר שהודה לו\u0006 לאח הזה \u0005בחלק ששייך לו]\u0006 — מדוע פטור? \u0003הא איכא\u0004 \u0005[הרי יש]\u0006 \u0003כפירה דאידך\u0004 \u0005[של\u0006 האח \u0005האחר]\u0006 וכפירת ממון גמורה היא! \u0003אלא לאו דאמרי ליה\u0004 \u0005[האם לא\u0006 במקרה \u0005שאומרים לו]\u0006 שני האחים: \u0003מתרוינן יזפת\u0004 \u0005[משנינו לווית],\u0006 \u0003ואמר להו\u0004 \u0005[להם]:\u0006 \u0003לא, מחד מינייכו יזפי\u0004 \u0005[מאחד מכם לוויתי]\u0006 את כל הסכום, \u0003דהויא ליה\u0004 \u0005[שהרי היא]\u0006 \u0003כפירת דברים בעלמא\u0004 \u0005[בלבד],\u0006 שהרי הוא מודה בגוף החוב, אלא מתווכח עם התובעים כיצד היה המעשה. \u0003ומ\u0004כיון \u0003דרישא\u0004 \u0005[שראשה]\u0006 של אותה ברייתא מדבר ב\u0003כפירת דברים\u0004 ולא בכפירת הממון, \u0003סיפא נמי\u0004 \u0005[סופה גם כן]\u0006 מדבר ב\u0003כפירת דברים\u0004 ולא בכפירה בעצם החוב, ואין מכאן ראיה.","ומנסים להביא ראיות שגם הכופר בממון שיש עליו עדים חייב קרבן משום שבועת הפקדון \u0003(סימן\u0004 לראיות: \u0003חובה כיתות דבעל הבית חומר נזירא). תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו במשנתנו: \u0003אינו חייב על שגגתה\u0004 של שבועת הפקדון, \u0003ומהו חייב על זדונה? אשם בכסף שקלים. מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר ב\u0003זדון עדים,\u0004 שכופר במזיד בדברים שאומרים העדים? והרי הוא חייב! ודוחים: \u0003לא,\u0004 מדובר ב\u0003זדון עצמו\u0004 בלי עדים, שהוא מודה בעצמו שנשבע לשקר, אבל אם היה זה בעדים — הריהו פטור.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה מדין שבועת העדות: \u0003היו\u0004 שם \u0003שתי כתי עדים, כפרה הראשונה ואחר כך כפרה השניה\u0004 — \u0003שתיהן חייבות, מפני שיכולה עדות להתקיים בשתיהן.\u0004 ונברר: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003שניה תחייב\u0004 \u0005[תתחייב\u0006 בקרבן\u0005]\u0006 על שבועתה \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003כפרה לה כת ראשונה,\u0004 ונמצא שהשבת ממון לבעליו תלויה בעדותם שלהם, \u0003אלא\u0004 כת \u0003ראשונה אמאי מיחייבא\u0004 \u0005[מדוע מתחייבת\u0006 בכלל\u0005]?\u0006"],["\u0003הא קיימא\u0004 \u0005[הרי\u0006 עדיין \u0005עומדת]\u0006 כת \u0003שניה\u0004 שיכולה להעיד, ואין בכך כפירת ממון. ומכאן משמע שכפירת ממון שיש בו עדים כפירה היא!","\u0003אמר רבינא: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שהיתה\u0004 כת \u0003שניה\u0004 של עדים \u0003בשעת כפירת הראשונה קרובין\u0004 זה לזה \u0003בנשותיהן ו\u0004לכן היו פסולים לעדות, אבל \u0003נשותיהן\u0004 היו אז \u0003גוססות, מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003רוב גוססין למיתה\u0004 ולכן הם נחשבים כראויים להעיד, \u0003קא משמע לן\u0004 \u0005[משמיע לנו]\u0006 ש\u0003השתא מיהת חיי נינהו ולא שכיבי\u0004 \u0005[עכשיו על כל פנים חיות הן ולא מתו],\u0006 ולכן הם קרובים ואינם יכולים להעיד.","ומנסים להביא ראיה נוספת, \u0003תא שמע\u0004 \u0005[בוא\u0006 \u0005ו\u0006\u0005שמע]\u0006 ברייתא \u0005:\u0006 \u0003בעל הבית שטען טענת גנב בפקדון\u0004 שטוען שנגנב הפקדון ממנו, \u0003ונשבע\u0004 על טענתו זו, \u0003והודה\u0004 אחר כך ששיקר, \u0003ובאו עדים\u0004 והעידו שלא נגנב ממנו, \u0003אם עד שלא באו עדים הודה\u0004 מעצמו ששיקר — הרי הוא \u0003משלם קרן\u0004 (הסכום שלקח) \u0003וחומש\u0004 קנס על מה שכפר, \u0003ואשם\u0004 לכפרת שבועת הפקדון. \u0003אם משבאו עדים הודה\u0004 — \u0003משלם תשלומי כפל\u0004 כגנב, \u0003ו\u0004משלם \u0003אשם,\u0004 ומכאן שגם ממון שיש עליו עדים — מביא עליו קרבן!","ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם\u0006 כן\u0005]\u0006 מדובר במעשה \u0003כ\u0004עין זה של \u0003רבינא,\u0004 שהיו העדים קרובים בשעת שבועה ולא היו יכולים לחייבו ממון, ולכך חייב קרבן על השבועה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי, תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו בברייתא: \u0003חמורה ממנה שבועת הפקדון\u0004 משבועת העדות, \u0003שחייבין על זדונה מכות ועל שגגתה אשם בכסף שקלים. מדקאמר\u0004 \u0005[ממה שהוא אומר]\u0006 \u0003לוקה\u0004 — \u0003מכלל\u0004 הדברים אתה למד \u0003דאיכא\u0004 \u0005[שיש]\u0006 \u0003עדים\u0004 בדבר שראו את הפקדון ברשותו, והתרו בו, \u0003וקאמר\u0004 \u0005[והוא אומר]:\u0006 חייב \u0003על שגגתה אשם בכסף שקלים!\u0004","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב מרדכי: בר מינה דההיא\u0004 \u0005[חוץ ממנה\u0006 מברייתא \u0005זו]\u0006 אין להוכיח ממנה, \u0003דהאמר להו\u0004 \u0005[שהרי אמר להם]\u0006 \u0003רב כהנא\u0004 לחכמים בסוגיה הקודמת, \u0003אנא תנינא לה והכי תנינא לה\u0004 \u0005[אני שניתי אותה וכך שניתי אותה]:\u0006 \u0003אחד זדונה ואחד שגגתה\u0004 של שבועת הפקדון — \u0003אשם בכסף שקלים,\u0004 ואין מדובר שם בעדים שהתרו בו.","ומציעים, \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה ממה ששנינו בברייתא: \u0003לא, אם אמרת בנזיר טמא שכן לוקה, תאמר בשבועת הפקדון שאינו לוקה?\u0004 ונברר: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר]?\u0006 \u0003אי דליכא\u0004 \u0005[אם שאין]\u0006 \u0003עדים, אמאי\u0004 \u0005[מדוע]\u0006 הוא \u0003לוקה? אלא פשיטא דאיכא\u0004 \u0005[פשוט\u0006 הוא שמדובר במקרה \u0005שיש]\u0006 \u0003עדים, וקתני\u0004 \u0005[והוא שונה]:\u0006 \u0003תאמר בשבועת הפקדון שאינו לוקה.\u0004 ונדייק מכאן: \u0003מלקא\u0004 \u0005[ללקות]\u0006 \u0003הוא דלא לקי\u0004 \u0005[שאינו לוקה],\u0006 \u0003אבל קרבן מייתי\u0004 \u0005[מביא],\u0006 אף שיש עדים, הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבה!\u0004 ומסכמים: אכן \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006\u0005]\u0006 היא, ונדחו דבריו.","ובאותו ענין \u0003ר' יוחנן אמר: הכופר בממון שיש עליו עדים\u0004 — \u0003חייב\u0004 (שלא כשיטת רבה), אבל הכופר בממון שיש עליו \u0003שטר\u0004 — \u0003פטור. אמר רב פפא: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוחנן? עדים עבידי דמייתי\u0004 \u0005[עשויים שימותו],\u0006 וגם אם יש עדים יתכן שלא ישלם על פיהם, ונמצא שהוא כופר ממון בשבועה זו. \u0003שטר\u0004 — \u0003הא מנח\u0004 \u0005[הרי\u0006 הוא \u0005מונח],\u0006 ונמצא שלעולם אינו נפטר ממון בכפירתו\u0005.\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע לרב פפא:\u0004 טעם זה אינו נכון, שהרי \u0003שטרא נמי עביד דמרכס\u0004 \u0005[שטר גם כן עשוי שיאבד]!\u0006 \u0003אלא\u0004 \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע: היינו טעמיה\u0004 \u0005[זהו טעמו]\u0006 של \u0003ר' יוחנן, משום דהוה\u0004 \u0005[שהריהו]\u0006 \u0003שטר שעבוד קרקעות,\u0004 ששטר יש בו סעיף אחריות ושעבוד על הקרקע של החייב, ועל ידו משתעבדת הקרקע, \u0003ואין מביאין קרבן\u0004 של שבועת הפקדון \u0003על כפירת שעבוד קרקעות,\u0004 לפי שאין נשבעים על הקרקע.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שחלקו אמוראים בשאלה הבאה: \u0003משביע עדי קרקע\u0004 שיעידו שקרקע זו שלו היא, ונשבעו שאינם יודעים לו עדות — \u0003פליגי\u0004 \u0005[נחלקו]\u0006 בענין זה \u0003ר' יוחנן ור' אלעזר, חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר: חייב\u0004 העד בקרבן משום שבועת העדות, \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: פטור.\u0004 ומעירים: \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 ש\u0003ר' יוחנן\u0004 הוא ש\u0003אמר פטור,\u0004 מדוע? \u0003מ\u0004מה ש\u0003אמר ר' יוחנן\u0004 בענייננו: \u0003הכופר בממון שיש עליו עדים\u0004 — \u0003חייב\u0004 משום שבועת הפקדון, בממון שיש עליו \u0003שטר\u0004 — \u0003פטור, ו\u0004הוא \u0003כ\u0004דברי \u0003רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע,\u0004 שהטעם הוא משום שטר שעבוד קרקעות, ואין מביאים קרבן על כפירת שעבוד קרקעות. ומסכמים: אכן, \u0003תסתיים\u0004 \u0005[תוגדר]\u0006 שכך הדבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' ירמיה לר' אבהו: לימא\u0004 \u0005[האם נאמר]\u0006 ש\u0003ר' יוחנן ור' אלעזר בפלוגתא\u0004 \u0005[במחלוקתם]\u0006 של התנאים \u0003ר' אליעזר ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003קא מיפלגי\u0004 \u0005[הם חלוקים]?\u0006 \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הגוזל שדה מחבירו ושטפה נהר\u0004 — \u0003חייב להעמיד לו שדה\u0004 אחר, שהרי עתה פחת ערכה הרבה, ועליו מוטל להשיב לנגזל את הגזילה שגזל, \u0003דברי ר' אליעזר. וחכמים אומרים: אומר לו \"הרי שלך לפניך\",\u0004 שיכול להחזיר את השדה כמו שהיא, למרות שעכשיו נתמעט ערכה, משום שלדעתם הקרקע אינה נחשבת גזולה, כדי שתחול עליה חובת ההשבה, אלא הריהי כמצויה ברשות בעליה.","\u0003ואמרינן\u0004 \u0005[ואומרים\u0006 היינו\u0005]:\u0006 \u0003במאי קמיפלגי\u0004 \u0005[במה חלוקים הם]?\u0006 בדרך שבה דורשים את פרשת שבועת הפקדון, שבה מצויה גם חובת ההשבה של הגזילה לבעליה, \u0003ר' אליעזר דריש רבויי ומיעוטי\u0004 \u0005[דורש\u0006 בדרך \u0005ריבויים ומיעוטים],\u0006 \u0003ורבנן דרשי כללי ופרטי\u0004 \u0005[וחכמים דורשים\u0006 בדרך \u0005כללים ופרטים].\u0006 וכיצד?","\u0003ר' אליעזר דריש רבויי ומיעוטי\u0004 \u0005[דורש ריבויים ומיעוטים]:\u0006 נאמר שם: \u0003\"וכחש בעמיתו\"\u0004 (ויקרא ה, כא) — הרי זה \u0003ריבה\u0004 הכחשה בכל דבר, \u0003\"בפקדון או בתשומת יד\"\u0004 — \u0003מיעט,\u0004 לומר שמדובר רק בדברים מסויימים, \u0003\"או מכל אשר ישבע\"\u0004 (ויקרא ה, כד) — \u0003חזר וריבה,\u0004","אם כן נמצא שיש פה \u0003ריבה ומיעט וריבה,\u0004 ולפי כללי מדרש ההלכה במקרה כזה \u0003ריבה הכל, מאי\u0004 \u0005[מהו]\u0006 \u0003ריבה? ריבה כל מילי\u0004 \u0005[דבר],\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 בכל זאת \u0003מיעט? מיעט\u0004 דבר אחד: \u0003שטרות.\u0004","\u0003ו\u0004אילו \u0003רבנן דרשי כללי ופרטי\u0004 \u0005[חכמים דורשים\u0006 בדרך \u0005כללים ופרטים]:\u0006 \u0003\"וכחש בעמיתו\"\u0004 — הרי זה \u0003כלל, \"בפקדון או בתשומת יד או בגזל\"\u0004 — \u0003פרט, \"או מכל אשר ישבע עליו\"\u0004 — \u0003חזר וכלל,\u0004 אם כן, הרי זה \u0003כלל ופרט וכלל,\u0004 ובמקרה זה \u0003אי\u0004 (אין) \u0003אתה דן אלא כעין הפרט:\u0004","\u0003מה הפרט מפורש, דבר המטלטל וגופו ממון\u0004 — \u0003אף כל דבר המטלטל וגופו ממון, יצאו קרקעות\u0004 — \u0003שאין\u0004 הם דבר ה\u0003מטלטל, יצאו עבדים\u0004 — \u0003שהוקשו\u0004 (הושוו במקרא) \u0003לקרקעות, יצאו שטרות\u0004 — \u0003שאף על פי ש\u0004הם \u0003מטלטלין אין גופן ממון,\u0004 אלא הם רק ראיה לממון.","ואם כן, האם נאמר: \u0003מאן דמחייב\u0004 \u0005[מי שמחייב]\u0006 עדי קרקע משום שבועת העדות, כלומר ר' אלעזר, הוא סבור \u0003כ\u0004דברי \u0003ר' אליעזר,\u0004 שקרקע נכללת בכלל השבת גזילה ושבועת הפקדון, וממילא גם בשבועת העדות שנלמדת ממנה, \u0003ומאן דפטר\u0004 \u0005[ומי שפוטר],\u0006 כלומר ר' יוחנן, סבור \u0003כרבנן\u0004 \u0005[כחכמים],\u0006 שמוציאים קרקעות מכלל זה?","\u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבהו לר' ירמיה: \u0003לא, מאן דמחייב\u0004 \u0005[מי שמחייב]\u0006 אכן סבור \u0003כר' אליעזר, ומאן דפטר\u0004 \u0005[ומי שפוטר]\u0006 \u0003אמר לך\u0004 \u0005[יכול לומר לך]:\u0006 \u0003בהא\u0004 \u0005[ב\u0006דבר \u0005זה]\u0006 בענין שבועה \u0003אפילו ר' אליעזר מודה\u0004 שאין מביא קרבן, \u0003דרחמנא אמר\u0004 \u0005[שהתורה אמרה]\u0006 \u0003\"מכל\u0004 אשר ישבע עליו לשקר\" (ויקרא ה, כד), ומשמעות הדברים היא — חלק \u0003ולא הכל,\u0004 ולפיכך ממעט קרקעות מחיוב זה, שהרי אינם דומים לפרטים שבתורה.","\u0003אמר רב פפא משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 שאין דין שבועת הפקדון בכפירת שעבוד קרקעות, \u0003דקתני\u0004 \u0005[ששנה]\u0006 בה: \u0003\"גנבת את שורי\", והוא אומר: \"לא גנבתי\",\u0004 אמר לו: \u0003\"משביעך אני\", ואמר: \"אמן\"\u0004 — \u0003חייב, ואילו \"גנבת את עבדי\" לא קתני\u0004 \u0005[שנה],\u0006 \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 מדוע לא שנה אותו? \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 ש\u0003עבד איתקש\u0004 \u0005[הוקש]\u0006 \u0003לקרקעות, ואין מביאין קרבן על כפירת שעבוד קרקעות?\u0004","\u0003אמר רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא\u0004 בדחייה: \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של המשנה\u0005],\u0006 \u0003זה הכלל: כל המשלם על פי עצמו\u0004 — \u0003חייב, ושאינו משלם על פי עצמו\u0004 — \u0003פטור.\u0004 ונברר: \u0003\"זה הכלל\" לאתויי מאי\u0004 \u0005[להביא\u0006 את \u0005מה]?\u0006 מה החידוש שנוסף על ידי הכללה זו? \u0003לאו לאתויי\u0004 \u0005[האם לא להביא]\u0006 הלכה נוספת, בטוען \u0003\"גנבת את עבדי\"?\u0004"]]};
